	('0K5fwx85jDK', '2024s106', 'Penyusunan SUT Tahun 2020-2022', '2024', '2024s106', '<p>Ketua Tim: Meita Jumiartanti</p>\n<ul>\n<li>PIC Produksi: Ridha Meutia &amp; Fitri Mulyani</li>\n<li>PIC Pengeluaran: Hendra Dharmawan</li>\n</ul>', '<p>(akan dilengkapi kemudian)</p>', '<p>(akan dilengkapi kemudian)</p>', '2024-02-20 12:06:01', '198512092009021002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('0Sh1Ss4vYGI', '2024s105', 'Survei Angkutan Penumpang dan Barang (SAPB)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Hani\'ah</p>\n<p>Anggota&nbsp; &nbsp; : Akhmad Sugito&nbsp;</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ferfi Hamdina&nbsp;</p>', '<p>Link Dashboard:</p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pelatihan Innas dan Petugas</td>\n<td>&nbsp;</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;&nbsp;2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-05 11:45:39', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('0YJ6nqozKuw', '2024s105', 'Penyusunan Publikasi Statistik Harga Produsen', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Mursalina</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>', '<table dir="ltr" style="width: 50.3684%;" border="1" cellspacing="0" cellpadding="0" data-sheets-root="1"><colgroup><col style="width: 62.7226%;" width="509"><col style="width: 18.5025%;" width="100"><col style="width: 18.775%;" width="100"></colgroup>\n<tbody>\n<tr>\n<td style="text-align: center;" rowspan="3" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Judul Publikasi (Indonesia)&quot;}">\n<div><strong>Judul Publikasi (Indonesia)</strong></div>\n</td>\n<td style="text-align: center;" rowspan="3" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Penyusun&quot;}">\n<div><strong>Penyusun</strong></div>\n</td>\n<td style="text-align: center;" rowspan="3" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Pemeriksaan&quot;}">\n<div><strong>Pemeriksaan</strong></div>\n</td>\n</tr>\n<tr></tr>\n<tr></tr>\n<tr>\n<td data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Statistik Harga Produsen Gabah Provinsi Aceh 2023&quot;}">Statistik Harga Produsen Gabah Provinsi Aceh 2023</td>\n<td style="text-align: center;" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Mursalina&quot;}">Mursalina</td>\n<td style="text-align: center;" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Akhmad S&quot;}">Akhmad Sugito</td>\n</tr>\n</tbody>\n</table>', '<table dir="ltr" border="1" cellspacing="0" cellpadding="0" data-sheets-root="1"><colgroup><col width="509"><col width="127"><col width="120"></colgroup>\n<tbody>\n<tr>\n<td style="text-align: center;" rowspan="3" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Judul Publikasi (Indonesia)&quot;}">\n<div><strong>Judul Publikasi (Indonesia)</strong></div>\n</td>\n<td style="text-align: center;" rowspan="3" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;ARC/NonARC&quot;}">\n<div><strong>ARC/NonARC</strong></div>\n</td>\n<td style="text-align: center;" rowspan="3" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Tanggal Rilis di Website&quot;}">\n<div><strong>Tanggal Rilis di Website</strong></div>\n</td>\n</tr>\n<tr></tr>\n<tr></tr>\n<tr>\n<td data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Statistik Harga Produsen Gabah Provinsi Aceh 2023&quot;}">Statistik Harga Produsen Gabah Provinsi Aceh 2023</td>\n<td style="text-align: center;" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;ARC&quot;}">ARC</td>\n<td style="text-align: center;" data-sheets-value="{&quot;1&quot;:3,&quot;3&quot;:45463}" data-sheets-numberformat="{&quot;1&quot;:5,&quot;2&quot;:&quot;d mmmm yyyy&quot;,&quot;3&quot;:1}">20 June 2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-21 15:56:09', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('1cecs8dLBoS', '2024s105', 'Survei Harga Properti Perumahan (SHPP)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Melly</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Cut Malahayati&nbsp; &nbsp;</p>', '<p>Link:</p>', '<table style="border-collapse: collapse; width: 100%;" border="1"><colgroup><col style="width: 49.9665%;"><col style="width: 49.9665%;"></colgroup>\n<tbody>\n<tr>\n<td>Pelatihan</td>\n<td>&nbsp;April 2024</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;April - Mei 2024</td>\n</tr>\n</tbody>\n</table>', '2024-01-29 12:26:44', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('1hzG2Lq6vHa', '2024s102', 'Evaluasi Penyelenggaraan Statistik Sektoral (EPSS)', '2024', '2024s109', '<p><strong>Ketua Tim</strong>: Wahyu Agung Sutikno<br><strong>PJK</strong>: Darwis Abubakar</p>\n<p>Tim Pelaksana/TPB: Yan Yan Gustiana, M. Alimuddin, Fikri, Azwar, Darwis Abubakar, Nur Hasanah, Dewi Putri Rahayu</p>', '<p>Rincian progres EPSS dapat dilihat pada gsheet di tautan: <a href="http://s.bps.go.id/11_monitoring_epss2024">http://s.bps.go.id/11_monitoring_epss2024</a></p>\n<p>Progres penilaian Kamis, 16 Mei 2024 pukul 14:00 sebagai berikut:<br>1 pemda (Aceh Jaya) status *Pending Dokumen*, artinya telah melakukan *SUBMIT* penilaian mandiri dan menunggu tahap penilaian dokumen;<br>0 pemda status *Pending Supervisor*, artinya sudah selesai oleh operator dan dalam pemeriksaan supervisor TPI;<br>21 pemda (selain Aceh Jaya dan Kota Lhokseumawe) status *Pending Operator* atau masih dalam proses penilaian mandiri;<br>1 pemko Lhokseumawe berstatus *Belum Isi*.<br><br></p>', '<p>&nbsp;</p>\n<table style="border-collapse: collapse; width: 20%; height: 116.953px;" border="1"><colgroup><col style="width: 59.0988%;"><col style="width: 40.9012%;"></colgroup>\n<tbody>\n<tr>\n<td>Persiapan pelaksanaan penilaian</td>\n<td>: Januari s.d Maret 2024</td>\n</tr>\n<tr style="height: 22.3906px;">\n<td style="height: 22.3906px;">Penilaian mandiri di Instansi Pemda</td>\n<td style="height: 22.3906px;">: April s.d Mei 2024</td>\n</tr>\n<tr style="height: 22.3906px;">\n<td style="height: 22.3906px;">Penilaian</td>\n<td style="height: 22.3906px;">: Juni s.d Agustus 2024</td>\n</tr>\n<tr style="height: 22.3906px;">\n<td style="height: 22.3906px;">Harmonisasi</td>\n<td style="height: 22.3906px;">: Agustus 2024</td>\n</tr>\n<tr style="height: 22.3906px;">\n<td style="height: 22.3906px;">Hasil</td>\n<td style="height: 22.3906px;">: September 2024</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>\n<p><img src="https://drive.google.com/file/d/1nOeoA-PaWVZi6P430GmhAORBEwDw-OIg/view?usp=drive_li