	('8Ky7XuSIeWn', '2024s102', 'Pemutakhiran MFD', '2025', '2025s105', '<ol>\n<li>\n<p><strong>Ketua Tim</strong>: Fitral Pratomo</p>\n<p><strong>Pjk</strong>: Kahar Muzakar</p>\n<p><strong>Anggota</strong>:&nbsp;</p>\n<ul>\n<li>Wira Junardi</li>\n</ul>\n</li>\n</ol>', '<ul>\n<li>Rilis MFD 2024 Semester 2 <a href="https://s.bps.go.id/MFD_Rilis_Daerah">https://s.bps.go.id/MFD_Rilis_Daerah</a></li>\n<li>Pemutakhiran MFD 2025 Semester 1 melalui MFDOnline <a href="https://frs.bps.go.id/area">https://frs.bps.go.id/area</a></li>\n<li>Pemutakhiran MFD 2025 Semester 2 melalui MFDOnline <a href="https://frs.bps.go.id/area">https://frs.bps.go.id/area</a></li>\n<li>Publikasi Master File Wilayah (MFW) Tahun 2025&nbsp;</li>\n</ul>', 'NULL', '2025-02-18 8:29:54', '198906132012111001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('91reHmEybFH', '2024s106', 'Penyusunan Angka PDRB Triwulan 3', '2025', '2025s106', '<p>PJK :</p>\n<p>Meita Jumiartanti, SST, M.Si</p>\n<p>Anggota:</p>\n<ol>\n<li>Hendra Dharmawan, SST, M.Si</li>\n<li>Ridha Mutia, SE, M.Si</li>\n<li>Hilda Aprina, SST, M.Si</li>\n<li>Cahya Danu Rahman, SST</li>\n<li>Maulizasari, S.Stat</li>\n<li>Fitri Mulyani, SST</li>\n<li>Mazaya Alifah Syadzwina, S.Tr.Stat</li>\n<li>Azwar, SE</li>\n</ol>', '<p><strong><span class="deskripsi-label">Tujuan dan Manfaat Kegiatan</span></strong></p>\n<p>Menyediakan data dan indikator ekonomi makro sebagai evaluasi dan perencanaan pembangunan</p>\n<p>&nbsp;</p>\n<p><strong><span class="deskripsi-label">Frekuensi Penyelenggaraan</span></strong></p>\n<p>Triwulanan</p>', 'NULL', '2025-07-24 14:16:17', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('92divvfWowW', '2024s105', 'Survei Spesifik Komoditas (SVK)', '2024', '2024s103', '<p>Ketua Tim : Titiek Zurryati</p>\n<p>PJK : Mursalina</p>\n<p>Anggota: Dwi Susanti</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Andariati Afrida</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Nyimas Eka</p>', '<p>Link Laporan: s.bps.go.id/LaporanSVK2024</p>', '<table style="width: 500px;" border="1" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td style="width: 195.828px;">Pencacahan SVK</td>\n<td style="width: 297.172px;">September 2024</td>\n</tr>\n<tr>\n<td style="width: 195.828px;">Pengolahan SVK</td>\n<td style="width: 297.172px;">September 2024</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>', '2024-01-29 12:07:16', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
