	('AH7zu0iHbD4', '2024s101', 'Pengelolaan Peningkatan Kompetensi Pegawai', '2024', '2024s108', '<p>Ketua:&nbsp;<strong>Yan Yan Gustiana</strong></p>\n<p>Anggota:&nbsp;</p>\n<p>Maulizasari</p>\n<p>Reza Rezki Pulungan</p>\n<p>Wahdini</p>\n<p>Edo Mara Nasution</p>', '<ol>\n<li>Pengisian CKP dilakukan rutin setiap bulan pada KiPApp&nbsp;<em><a href="https://webapps.bps.go.id/kipapp">website kipapp </a></em></li>\n</ol>', '<p>KiPApp rutin setiap bulan dengan deadline pengisian di awal bulan</p>', '2024-03-25 9:22:58', '199509142019032002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('aKSOJV6uBF1', '2024s106', 'Indepth Study SEEA', '2024', '2024s106', '<div class="card-body">\n<p><strong>Ketua Tim:</strong>&nbsp;Meita Jumiartanti</p>\n<ul>\n<li><strong>PIC SINASI:</strong>&nbsp;Fitri Mulyani</li>\n<li><strong>Anggota:</strong> Ridha Mutia, Azwar</li>\n</ul>\n</div>', '<p style="text-align: justify;"><strong>Tujuan Kegiatan</strong><br><em>In-depth Study SEEA tahun 2023 bermaksud untuk memperoleh data/informasi mengenai keanekaragaman hayati dan perubahan iklim di Indonesia, khususnya yang berkaitan dengan dimensi ekonomi dan lingkungan. Oleh karena itu, pada tahun ini BPS menyelenggarakan in-depth study yang memiliki tujuan-tujuan sebagai berikut:&nbsp;</em></p>\n<ul>\n<li><em>Mengetahui jumlah flora dan fauna serta perubahannya menurut jenis spesies </em></li>\n<li><em>Mengetahui pemanfaatan keanekaragaman hayati dalam ekonomi </em></li>\n<li><em>Mengetahui penyediaan produk-produk energi </em></li>\n<li><em>Mengetahui penggunaan bahan bakar dan produk energi yang dapat menghasilkan emisi gas rumah kaca&nbsp;</em></li>\n</ul>\n<p>&nbsp;</p>\n<p><strong>Dokumentasi Kegiatan</strong></p>\n<p><em><a href="s.bps.go.id/Administrasi-SEEA2024">s.bps.go.id/Administrasi-SEEA2024</a></em></p>', '<p><strong>Pelatihan Petugas &gt;&gt;</strong> 24-28 Juni 2024</p>\n<p><strong>Pendataan Lapangan &gt;&gt;</strong> Mei-September 2024</p>', '2024-02-20 12:44:15', '199503172018022001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('AkWzlVJHGCn', '2024s105', 'Survei Usaha Penyedia Jasa Akomodasi Bulanan (VHTS)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Effendy</p>\n<p>Anggota&nbsp; &nbsp; : Cut Sandra&nbsp;</p>', '<p>Link Dashboard:</p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp; Tanggal 12 setiap bulan</td>\n</tr>\n</tbody>\n</table>', '2024-02-06 11:06:31', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('AnyectkslVZ', '2024s105', 'International Comparison Program (ICP) Komoditas Mesin dan Peralatan yang berkualitas', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Melly</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Cut Malahayati&nbsp; &nbsp;</p>', '<p>Link:</p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;Juni 2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-21 3:59:48', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('aPtlXhv8Agk', '2024s103', 'Pendataan Registrasi Sosial Ekonomi (Regsosek)', '2024', '2024s102', '<p>Ketua Tim : Abd.Hakim</p>\n<p>PJK : M.Ridha &nbsp; &nbsp;</p>\n<p>Anggota Tim : A.Sugito &nbsp; &nbsp;Darwis &nbsp; &nbsp;Juliana &nbsp; &nbsp;Zelvia &nbsp; &nbsp;Maulidya &nbsp; &nbsp;Fitral</p>', '<p>-</p>', '<p>-</p>', '2024-02-26 15:44:37', '198109132006021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('auPWAHctuau', '2024s103', 'Desa Cantik 2025', '2025', '2025s102', '<p><strong>Ketua </strong>Tim: Abd.Hakim<br><strong>PJK</strong>:M.Ridha &nbsp;&nbsp;<br><strong>Anggota</strong>: Darwis,Alfi,Juliana,Naura,Ismaturahmi,Maulidya</p>', '<p>Dalam rangka pengembangan statistik di Indonesia, Badan Pusat Statistik berkewajiban memberikan pembinaan kepada Kementerian/Lembaga/Satuan Kerja Perangkat Daerah/Institusi Lainnya melalui Sistem Statistik Nasional (SSN) yang berkesinambungan, termasuk sampai tingkat desa, sebagai salah satu bentuk kontribusi dalam peningkatan literasi statistik guna mendukung pembangunan nasional.</p>\n<p>Arsip :&nbsp;<br><a href="https://linktr.ee/Desa_Cantik_2025">https://linktr.ee/Desa_Cantik_2025</a>&nbsp;&nbsp;<br><a href="https://s.bps.go.id/descan-aceh">https://s.bps.go.id/descan-aceh</a>&nbsp; &nbsp; &nbsp;<br><a href="https://s.bps.go.id/usulan_DC2025-aceh">https://s.bps.go.id/usulan_DC2025-aceh</a>&nbsp;<br>___________________________<br>Penilaian Desa Cantik (LKE) : <a href="https://linktr.ee/Desa_Cantik_2025">https://</a>s.bps.go.id/PenilaianDescan2025 (Link Prov)&nbsp;<br>Dashboard : <a href="https://indah-dev.bps.go.id/desa-cantik">https://indah-dev.bps.go.id/desa-cantik</a>&nbsp;&nbsp;<br>Input Identifikasi Kebutuhan Desa/Kelurahan: &nbsp;<a href="https://s.bps.go.id/InstrumenIdentifikasiDC2025">https://s.bps.go.id/InstrumenIdentifikasiDC2025</a>&nbsp; &nbsp;<br>Monitoring : <a href="https://s.bps.go.id/monitoring_descan2025">https://s.bps.go.id/monitoring_descan2025</a>&nbsp; &nbsp;<br>Laporan akhir Kako : <a href="https://s.bps.go.id/laporan_akhir_Kabkota_descan2025">https://s.bps.go.id/laporan_akhir_Kabkota_descan2025</a>&nbsp;&nbsp;<br>Contoh output : <a href="https://s.bps.go.id/program-descan-terbaik">https://s.bps.go.id/program-descan-terbaik</a>&nbsp; &nbsp;</p>', '<ol>\n<li>Pelatihan Calon Pembina Desa Cantik Tahun 2025: M2 Maret - M4 Maret 2025</li>\n<li>Sosialisasi dan Pembinaan Desa Cantik Tahun 2025: M2 April - M3 April 2025</li>\n<li>Penilaian Desa Cantik Tahun 2025: M1 Agustus - M2 September 2025</li>\n</ol>', '2025-07-26 22:35:04', '198109132006021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('B1Aeo4ThRON', '2024s104', 'Survei Tanaman Pangan Ubinan', '2023', '2024s104', '<p>Hendra Gunawan</p>\n\n<p>Nilam Humaira</p>\n\n<p>Raiski Ramadhoni</p>', '<p>Survei Tanaman Pangan Ubinan terdiri dari Ubinan Padi dan Palawija</p>\n\n<p>&nbsp;</p>', '<table border="0" cellpadding="0" cellspacing="0" width="341">\n	<tbody>\n		<tr height="25">\n			<td height="25" width="341"><strong>Subround I</strong> <font>: Januari &ndash; April</font></td>\n		</tr>\n		<tr height="25">\n			<td height="25"><strong>Subround II</strong> <font>: Mei &ndash; Agustus</font></td>\n		</tr>\n		<tr height="25">\n			<td height="25"><strong>Subround III </strong><font>: September &ndash; Desember</font></td>\n		</tr>\n	</tbody>\n</table>\n\n<p>&nbsp;</p>\n\n<p><strong>Ubinan Padi :</strong></p>\n\n<table border="0" cellpadding="0" cellspacing="0" width="664">\n	<tbody>\n		<tr height="25">\n			<td height="25" width="295">Penerimaan Sampel (SUB-KSA.DS)</td>\n			<td width="11">:</td>\n			<td width="358">Subround I <font>: Desember dan Februari</font></td>\n		</tr>\n		<tr height="25">\n			<td height="25">&nbsp;</td>\n			<td>&nbsp;</td>\n			<td>Subround II <font>: April dan Juni</font></td>\n		</tr>\n		<tr height="25">\n			<td height="25">&nbsp;</td>\n			<td>&nbsp;</td>\n			<td>Subround III <font>: Agustus dan Oktober</font></td>\n		</tr>\n		<tr height="25">\n			<td height="25">Pelaksanaan Ubinan (SUB-S)</td>\n			<td>:</td>\n			<td>Sesuai jadwal panen pada&nbsp;<strong><em><font>Subround</font></em></strong><font> berjalan</font></td>\n		</tr>\n	</tbody>\n</table>\n\n<p>&nbsp;</p>\n\n<p><strong>Ubinan Palawija:</strong></p>\n\n<table border="0" cellpadding="0" cellspacing="0" style="width: 400px;" width="664">\n	<tbody>\n		<tr height="25">\n			<td height="25" width="295">Pemutakhiran (SUB-P)</td>\n			<td width="11">:</td>\n			<td width="358">Dua Minggu <font>sebelum </font><font>Subround </font><font>berjalan</font></td>\n		</tr>\n		<tr height="25">\n			<td height="25">Sampel (SUB-DS)</td>\n			<td>:</td>\n			<td>Satu Minggu <font>sebelum </font><font>Subround </font><font>berjalan</font></td>\n		</tr>\n		<tr height="25">\n			<td height="25">Pelaksanaan Ubinan (SUB-S)</td>\n			<td>:</td>\n			<td>Sesuai jadwal panen pada <font>Subround</font><font> berjalan</font></td>\n		</tr>\n	</tbody>\n</table>\n\n<p>&nbsp;</p>', '2024-01-26 4:17:40', '197904222005022001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('B4rnfb4ES2a', '2024s104', 'Laporan Tahunan Perusahaan Peternakan Ternak Besar dan Kecil (LTT)', '2025', '2025s104', '<p>Ketua Tim : Hendra Gunawan</p>\n<p>Pjk&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Nilam Humaira</p>', '<p><span class="fontstyle0">Pencacahan Lengkap&nbsp;Perusahaan Peternakan&nbsp;Ternak Besar dan Kecil&nbsp;Tahunan menggunakan Daftar LTT.&nbsp;</span></p>\n<p>&nbsp;</p>\n<p><span class="fontstyle0">Informasi Target Direktori sampel Perusahaan dapat di akses pada tautan : <strong><a href="https://s.bps.go.id/Direktori_Perusahaan_Peternakan_2025">https://s.bps.go.id/Direktori_Perusahaan_Peternakan_2025</a></strong></span></p>', '<p>&nbsp;&nbsp;</p>', '2025-07-25 15:48:05', '198607292009022005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('be70J1J3cha', '2024s105', 'Survei Lembaga Keuangan Pedagang Valuta Asing (VALAS)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Effendy</p>\n<p>Anggota&nbsp; &nbsp; : Cut Sandra&nbsp;</p>', '<p>Link Dashboard:&nbsp;</p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp; Maret - Juli&nbsp;2024</td>\n</tr>\n<tr>\n<td>Pengolahan</td>\n<td>&nbsp; September 2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-06 10:52:44', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('BguLBo3cfWs', '2024s103', 'Kemiskinan 2025', '2025', '2025s102', '<p><strong>Ketua</strong> Tim: Abd.Hakim<br><strong>PJK</strong>:M.Ridha &nbsp;&nbsp;<br><strong>Anggota</strong>: Darwis,Alfi,Juliana,Naura,Ismaturahmi,Maulidya</p>', '<p>-</p>', '<p>Rilis Kemiskinan &amp; Ketimpangan 25 Juli 2025<br>Rekonsiliasi Penghitungan Kemiskinan Kab/Kota Agustus : 14-18 Oktober 2025<br>Rilis Kemiskinan &amp; Ketimpangan Kabupaten Kota : -</p>', '2025-07-26 22:30:52', '198109132006021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('bjOmhVLKzo0', '2024s103', 'Survei Pengalaman Hidup Perempuan Nasional (SPHPN) 2024', '2024', '2024s102', '<p><strong>Ketua Tim:</strong> Abd.Hakim<br><strong>PJK: </strong>M.Ridha &nbsp; &nbsp;<br><strong>Anggota :</strong> Darwis &nbsp; &nbsp;Maulidya &nbsp; &nbsp;Bahzur A &nbsp; &nbsp;Juliana &nbsp; &nbsp;Zelvia &nbsp; &nbsp;A.Sugito</p>', '<p>-</p>', '<table style="border-collapse: collapse; width: 100.031%; border-width: 0px;" border="1"><colgroup><col style="width: 50.0403%;"><col style="width: 50.0403%;"></colgroup>\n<tbody>\n<tr>\n<td class="xl65" style="height: 12.5pt; width: 363pt; border-width: 0px;" width="484" height="17">Pelatihan Petugas Pemutakhiran&nbsp;</td>\n<td class="xl66" style="width: 308pt; border-width: 0px;" width="410">18-19 Apr 2024</td>\n</tr>\n<tr>\n<td class="xl65" style="height: 12.5pt; border-width: 0px; border-top-style: none; border-top-color: initial;" height="17">Pelaksanaan Pemutakhiran</td>\n<td class="xl66" style="border-width: 0px; border-top-style: none; border-top-color: initial;">29 Apr-10 Mei 2024</td>\n</tr>\n<tr>\n<td class="xl65" style="height: 12.5pt; border-width: 0px; border-top-style: none; border-top-color: initial;" height="17">Pelatihan Petugas&nbsp;</td>\n<td class="xl66" style="border-width: 0px; border-top-style: none; border-top-color: initial;">29 Apr-4 Mei 2024</td>\n</tr>\n<tr>\n<td class="xl65" style="height: 12.5pt; border-width: 0px; border-top-style: none; border-top-color: initial;" height="17">Pelaksanaan Lapangan</td>\n<td class="xl66" style="border-width: 0px; border-top-style: none; border-top-color: initial;">20 Mei-7 Juni 2024</td>\n</tr>\n</tbody>\n</table>', '2024-03-18 9:42:39', '198109132006021001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('bLyqhFVbMKz', '2024s104', 'Survei Industri Mikro dan Kecil (IMK) Tahunan', '2025', '2025s104', '<p>Melly<br>Rodiah</p>', '<ul>\n<li>Survei Industri Mikro dan Kecil 2025 (VIMK25) Tahunan diselenggarakan untuk mendata karakteristik usaha IMK dengan sampel berupa usaha/perusahaan terpilih yang berskala mikro dan kecil pada 23 kabupaten/kota di Provinsi Aceh. Hasil survei ini disajikan dalam Publikasi Statistik Industri Mikro dan Kecil Provinsi Aceh 2025.</li>\n<li>Kegiatan ini menggunakan moda CAPI dengan aplikasi FASIH.</li>\n<li>Monitoring Dashboard:&nbsp;<a href="https://fasih-dashboard.bps.go.id">https://fasih-dashboard.bps.go.id</a>&nbsp;</li>\n</ul>', 'NULL', '2025-07-25 17:00:18', '198604222009022005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('BP1t2id7jNp', '2024s102', 'Pemantauan dan Evaluasi Kinerja Penyelenggaraan Pelayanan Publik', '2024', '2024s107', '<p>Ketua: Hendri Achmad Hudori</p>\n\n<p>Anggota:</p>\n\n<ul>\n	<li>Nyimas Eka Hasnita</li>\n	<li>Anandika Dian Pramesti</li>\n	<li>Rubama</li>\n	<li>Nurzakiah</li>\n	<li>Marhami</li>\n	<li>Hani&#39;ah</li>\n</ul>', '<ul>\n	<li>Link pengisian kuesioner evaluasi:&nbsp;<u><strong><a href="https://dokumentasi.bps.go.id/app/SIPP" target="_blank">dokumentasi.bps.go.id/app/SIPP</a></strong></u></li>\n	<li>Link unggah bukti dukung: <u><strong><a href="http://s.bps.go.id/pekppp11" target="_blank">s.bps.go.id/pekppp11</a></strong></u></li>\n</ul>', '<table border="0" cellpadding="1" cellspacing="1" style="width: 350px;">\n	<tbody>\n		<tr>\n			<td><strong>Sosialisasi PEKPPP 2024</strong></td>\n			<td>10 Januari 2024</td>\n		</tr>\n		<tr>\n			<td><strong>Coaching aspek 1 dan 2</strong></td>\n			<td>17 Januari 2024</td>\n		</tr>\n		<tr>\n			<td><strong>Monitoring aspek 1 dan 2&nbsp;</strong></td>\n			<td>24 Januari 2024</td>\n		</tr>\n		<tr>\n			<td><strong>Coaching aspek 3 dan 4</strong></td>\n			<td>24 Januari 2024</td>\n		</tr>\n		<tr>\n			<td><strong>Monitoring aspek 3 dan 4</strong></td>\n			<td>30 Januari 2024</td>\n		</tr>\n		<tr>\n			<td><strong>Coaching aspek 5 dan 6</strong></td>\n			<td>30 Januari 2024</td>\n		</tr>\n		<tr>\n			<td><strong>Monitoring aspek 5 dan 6</strong></td>\n			<td>6 Februari 2024</td>\n		</tr>\n		<tr>\n			<td><strong>Batas akhir pengisian kuesioner</strong></td>\n			<td>8 Maret 2024</td>\n		</tr>\n	</tbody>\n</table>\n\n<p>&nbsp;</p>', '2024-01-23 10:05:10', '199711192021042001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('Bs5FNqlTDNz', '2024s105', 'Survei Harga Kemahalan Konstruksi (SHKK)', '2025', '2025s103', '<p>Ketua Tim : Ahkmad Sugito</p>\n<p>PJK : Mega Thursina</p>\n<p>Anggota : Yan Yan Gustiana, Dwi Susanti, Nurzakiah, Sinta Nuriyah, Bambang Wahyudi</p>', '<p>Pencacahan Triwulan I 2025 : Januari 2025<br>Pencacahan Triwulan II 2025 : April 2025<br>Pencacahan Triwulan III 2025 : Juli 2025</p>\n<p>Pencacahan Triwulan IV 2025 : Oktober 2025<br><br></p>', 'NULL', '2025-03-06 10:14:38', '199303312016022002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('BUtFQLNSu30', '2024s103', 'Desa Cantik 2024', '2024', '2024s109', '<p><strong>Ketua Tim</strong>: Wahyu Agung Sutikno<br><strong>PJK</strong>: Nur Hasanah<br><strong>Anggota</strong>: M. Alimuddin, Fikri, Kanasha Humaira</p>', '<p>Dalam rangka pengembangan statistik di Indonesia, Badan Pusat Statistik berkewajiban memberikan pembinaan kepada Kementerian/Lembaga/Satuan Kerja Perangkat Daerah/Institusi Lainnya melalui Sistem Statistik Nasional (SSN) yang berkesinambungan, termasuk sampai tingkat desa, sebagai salah satu bentuk kontribusi dalam peningkatan literasi statistik guna mendukung pembangunan nasional.</p>\n<p>Pada Tahun 2024, BPS Kabupaten/Kota di Provinsi Aceh membina 23 Desa Cinta Statistik yang ditetapkan dalam Keputusan Kepala Badan Pusat Statistik Nomor 352 Tahun 2024. Keputusan tersebut dapat diakses melalui tautan berikut:</p>\n<p><a href="https://drive.bps.go.id/s/E9c5KLxmfqGgCBJ">https://drive.bps.go.id/s/E9c5KLxmfqGgCBJ</a></p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>', '<ol>\n<li>Pelatihan Calon Pembina Desa Cantik Tahun 2024: 25 s.d. 31 Juli 2024</li>\n<li>Sosialisasi dan Pembinaan Desa Cantik Tahun 2024: Agustus s.d. September 2024</li>\n<li>Penilaian Desa Cantik Tahun 2024: 30 September s.d. 4 November 2024</li>\n</ol>', '2024-02-20 15:08:23', '199507292017012001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('bWXxtXVdBIU', '2024s102', 'Manajemen Mitra / SOBAT', '2024', '2024s105', '<p>Ketua : Fitral</p>\n<p>Anggota:&nbsp;</p>\n<ul>\n<li>Ichsan</li>\n<li>Anandika</li>\n<li>Wira J</li>\n<li>Kahar M</li>\n</ul>', '<ul>\n<li>Sobat Web:&nbsp;<a href="https://mitra.bps.go.id/" target="_blank" rel="noopener">mitra.bps.go.id</a>&nbsp;</li>\n<li>Manajemen Mitra:&nbsp;<a href="https://manajemen-mitra.bps.go.id/" target="_blank" rel="noopener">manajemen-mitra.bps.go.id</a></li>\n</ul>', '<p>-</p>', '2024-02-26 11:15:16', '198505122009021003', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('cBx8wcIIumn', '2024s102', 'Konfigurasi Perangkat Wifi', '2024', '2024s105', '<p><strong>Ketua : Fitral</strong></p>\n<p>Anggota:&nbsp;</p>\n<ul>\n<li>Munandar [PJK]</li>\n</ul>', '<p>Melakukan penamaan kembali wifi dari format lama ke format baru sesuai dengan ruangan tempat wifi di tempatkan</p>', '<table style="border-collapse: collapse; width: 100%; height: 89.6px;" border="1"><colgroup><col style="width: 50%;"><col style="width: 50%;"></colgroup>\n<tbody>\n<tr style="height: 22.4px;">\n<td style="text-align: center; height: 22.4px;"><strong>Kegiatan</strong></td>\n<td style="text-align: center; height: 22.4px;"><strong>Waktu</strong></td>\n</tr>\n<tr style="height: 22.4px;">\n<td style="height: 22.4px;">Konfigurasi Perangkat Wifi</td>\n<td style="height: 22.4px;">Minggu II Juli 2024</td>\n</tr>\n<tr style="height: 22.4px;">\n<td style="height: 22.4px;">Pengetesan dan penanggualan kendala</td>\n<td style="height: 22.4px;">Minggu II-III Juli 2024</td>\n</tr>\n<tr style="height: 22.4px;">\n<td style="height: 22.4px;">&nbsp;</td>\n<td style="height: 22.4px;">&nbsp;</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>', '2024-02-21 3:50:58', '198012212010031001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('cCazymqxMGL', '2024s106', 'Penyusunan Publikasi PDRB Menurut Lapangan Usaha Triwulan 1', '2025', '2025s106', '<p>PJK :</p>\n<p>Ridha Mutia, SE, M.Si</p>\n<p>Anggota:</p>\n<ol>\n<li>Maulizasari, S.Stat</li>\n<li>Fitri Mulyani, SST</li>\n</ol>', '<p>Penghitungan PDRB yang digunakan dalam publikasi ini ialah melalui&nbsp;pendekatan produksi yaitu menghitung nilai tambah barang dan jasa yang<br>dihasilkan seluruh unit produksi di wilayah Provinsi Aceh setiap triwulan. PDRB&nbsp;pendekatan produksi atau menurut lapangan usaha diperoleh dari selisih nilai<br>barang dan jasa yang dihasilkan dikurangi bahan baku yang digunakan sebagai&nbsp;input ditambah pajak atas produk dikurangi subsidi atas produk. Unit-unit<br>produksi tersebut dikelompokkan menjadi 17 kategori lapangan usaha, yaitu:<br>A. Pertanian, kehutanan, dan&nbsp;perikanan;<br>B. Pertambangan dan penggalian;<br>C. Industri pengolahan;<br>D. Pengadaan listrik dan gas;<br>E. Pengadaan Air;<br>F. Konstruksi;<br>G. Perdagangan besar dan eceran&nbsp;dan reparasi mobil dan sepeda&nbsp;motor;<br>H. Transportasi dan pergudangan;<br>I. Penyediaan akomodasi &amp; makan minum;<br>J. Informasi &amp; komunikasi;<br>K. Jasa keuangan;<br>L. Real estate;<br>M,N Jasa perusahaan;<br>O Administrasi pemerintahan,&nbsp;pertahanan, &amp; jaminan sosial&nbsp;wajib;<br>P Jasa pendidikan;<br>Q Jasa kesehatan &amp; kegiatan&nbsp;sosial;<br>R,S,T,U Jasa lainnya</p>', 'NULL', '2025-07-24 10:00:35', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('coKh4Qz9Nwz', '2024s102', 'Metadata Statistik Sektoral', '2024', '2024s109', '<p style="line-height: 1.5;"><strong>Ketua Tim</strong>: Wahyu Agung Sutikno<br><strong>PJK</strong>: Fikri<br><strong>Anggota</strong>: M. Alimuddin, Nur Hasanah</p>', '<ul>\n<li style="line-height: 1.5;"><strong>Link ESENSIAL: Edukasi Seputar Pembinaan Statistik Sektoral:</strong>&nbsp;<a href="https://s.id/pss-esensial">https://s.id/pss-esensial</a></li>\n<li style="line-height: 1.5;"><strong>Link Metadata Statistik:</strong> <a href="https://indah.bps.go.id/">https://indah.bps.go.id/</a></li>\n</ul>', '<ul>\n<li>Pelaksanaan Metadata Sektoral&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Sepanjang Tahun</li>\n<li>Edukasi Seputar Pembinaan Statistik Sektoral <strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</strong>19 Februari 2024</li>\n</ul>', '2024-02-20 2:46:34', '198804162008011001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
