	('DRCiGmxGBft', '2024s105', 'Survei Usaha Penyedia Makan Minum Skala Kecil (VREST-UMK)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Effendy</p>\n<p>Anggota&nbsp; &nbsp; : Cut Sandra&nbsp;</p>', '<p>Link Dashboard:</p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pelatihan/Briefing&nbsp;Innas dan Petugas*)</td>\n<td>&nbsp; April 2024</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp; Mei - Juli 2024</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>\n<p>*) Pelatihan/Briefing dilakukan secara online</p>', '2024-02-06 11:41:42', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('DvIjOuDFsmN', '2024s104', 'Pengutipan Direktori Perusahaan Konstruksi 2025', '2025', '2025s104', '<ol>\n<li>Cut Malahayati</li>\n<li>Fikri</li>\n</ol>', '<ul>\n<li>Secara &nbsp;garis &nbsp;besar, &nbsp;tujuan &nbsp;dari &nbsp;kegiatan &nbsp;Pengutipan &nbsp;Perusahaan &nbsp;Konstruksi adalah sebagai berikut:<br>1. &nbsp;Menyaring dan mendapatkan perusahaan konstruksi yang belum terdapat di direktori perusahaan konstruksi.<br>2. &nbsp;Mendapatkan &nbsp;informasi &nbsp;tentang &nbsp;perusahaan &nbsp;konstruksi &nbsp;aktif &nbsp;yang &nbsp;memiliki proyek sebagai alternatif pengganti sampel survei perusahaan konstruksi.<br>3. &nbsp;Memperkaya &nbsp;sampling &nbsp;frame &nbsp;sebagai &nbsp;dasar &nbsp;pengambilan &nbsp;sampel &nbsp;survei perusahaan konstruksi.</li>\n<li>kegiatan Pengutipan oleh BPS Provinsi dan BPS Kabupaten/Kota dilakukan dengan melakukan &nbsp;kunjungan &nbsp;ke &nbsp;paling &nbsp;sedikit &nbsp;2 &nbsp;OPD &nbsp;(Organisasi &nbsp;Perangkat &nbsp;Daerah)/Instansi Terkait/Asosiasi, baik di provinsi maupun di kabupaten/kota.</li>\n<li>Monitoring Dashboard:&nbsp;<a title="Monitoring Dashboard" href="https://fasih-dashboard.bps.go.id/">https://fasih-dashboard.bps.go.id</a>&nbsp;</li>\n<li>Buku Pedoman Pengutipan Direktori Perusahaan Konstruksi 2025: <a title="Buku Pedoman Pengutipan Direktori Perusahaan Konstruksi 2025" href="https://drive.bps.go.id/apps/onlyoffice/s/42TYC3MqsMdFXy9?fileId=71470149">https://drive.bps.go.id/apps/onlyoffice/s/42TYC3MqsMdFXy9?fileId=71470149</a></li>\n<li>Daftar Sampel:&nbsp;<a title="Daftar Sampel" href="https://docs.google.com/spreadsheets/d/1GjhmnFoWqrLPgEbxoQASrSrWwKNY_qhoE7kBveKIWug/edit?gid=1339402030#gid=1339402030">https://docs.google.com/spreadsheets/d/1GjhmnFoWqrLPgEbxoQASrSrWwKNY_qhoE7kBveKIWug/edit?gid=1339402030#gid=1339402030</a></li>\n<li>Dokumen Pengutipan Direktori Perusahaan Konstruksi 2025: <a title="Dokumen Pengutipan Direktori Perusahaan Konstruksi 2025" href="https://drive.bps.go.id/s/42TYC3MqsMdFXy9">https://drive.bps.go.id/s/42TYC3MqsMdFXy9</a></li>\n</ul>', 'NULL', '2025-07-25 17:43:23', '198804162008011001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('dXINai0SvSt', '2024s104', 'Survei Industri Mikro dan Kecil (IMK) Triwulanan', '2025', '2025s104', '<p>Melly<br>Rodiah</p>', '<ul>\n<li>Survei Industri Mikro dan Kecil Triwulanan menghasilkan indikator Indeks Produksi IMK Triwulanan untuk memenuhi kebutuhan PDRB sektor industri pengolahan per triwulan.</li>\n<li>Kegiatan ini menggunakan moda CAPI dengan aplikasi FASIH, dengan sampel berupa usaha/perusahaan terpilih yang berskala mikro dan kecil pada 23 kabupaten/kota di Provinsi Aceh.</li>\n<li>Monitoring Dashboard: <a href="https://fasih-dashboard.bps.go.id">https://fasih-dashboard.bps.go.id</a>&nbsp;</li>\n</ul>', 'NULL', '2025-02-17 11:21:26', '198604222009022005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('dYERBtUF0jX', '2024s103', 'Survei Nasional Pengalaman Hidup Anak dan Remaja (SNPHAR) 2024', '2024', '2024s102', '<p><strong>Ketua Tim:</strong> Abd.Hakim<br><strong>PJK</strong>: M.Ridha &nbsp; &nbsp;<br><strong>Anggota</strong> : Darwis &nbsp; &nbsp;Maulidya &nbsp; &nbsp;Bahzur A &nbsp; &nbsp;Juliana &nbsp; &nbsp;Zelvia &nbsp; &nbsp;A.Sugito</p>', '<p>-</p>', '<table style="border-collapse: collapse; width: 100.031%; border-width: 0px;" border="1"><colgroup><col style="width: 50.0403%;"><col style="width: 50.0403%;"></colgroup>\n<tbody>\n<tr>\n<td class="xl65" style="height: 12.5pt; width: 363pt; border-width: 0px;" width="484" height="17">Pelatihan Petugas Pemutakhiran (Daring)</td>\n<td class="xl66" style="width: 308pt; border-width: 0px;" width="410">18-19 Apr 2024</td>\n</tr>\n<tr>\n<td class="xl65" style="height: 12.5pt; border-width: 0px; border-top-style: none; border-top-color: initial;" height="17">Pelaksanaan Pemutakhiran</td>\n<td class="xl66" style="border-width: 0px; border-top-style: none; border-top-color: initial;">29 Apr-10 Mei 2024</td>\n</tr>\n<tr>\n<td class="xl65" style="height: 12.5pt; border-width: 0px; border-top-style: none; border-top-color: initial;" height="17">Pelatihan Petugas (Luring)</td>\n<td class="xl66" style="border-width: 0px; border-top-style: none; border-top-color: initial;">29 Apr-4 Mei 2024</td>\n</tr>\n<tr>\n<td class="xl65" style="height: 12.5pt; border-width: 0px; border-top-style: none; border-top-color: initial;" height="17">Pelaksanaan Lapangan</td>\n<td class="xl66" style="border-width: 0px; border-top-style: none; border-top-color: initial;">20 Mei-7 Juni 2024</td>\n</tr>\n</tbody>\n</table>', '2024-03-18 9:44:04', '198109132006021001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('DzDjCZyQpZE', '2024s106', 'Rekonsiliasi PDRB Kabupaten/Kota', '2024', '2024s106', '<div class="daftar">\n<p>Ketua Tim: Meita Jumiartanti</p>\n<ul>\n<li>PIC Produksi: Ridha Meutia &amp; Fitri Mulyani</li>\n<li>PIC Pengeluaran: Hendra Dharmawan &amp; Ar Razy Ridha Maulana</li>\n</ul>\n</div>', '<p>(akan dilengkapi kemudian)</p>', '<p>Rekon Tahunan</p>\n<p>Rekon Triwulanan</p>', '2024-02-20 12:00:56', '198512092009021002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('E1eg0TEvwZh', '2024s105', 'Survei Usaha Penyediaan Makanan Minuman (VREST)', '2025', '2025s103', '<p>Akhmad Sugito</p>', '<p>Tujuan</p>', 'NULL', '2025-07-25 15:33:40', '198407082008011003', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('E9m9ydApOd1', '2024s106', 'Penyusunan Publikasi PDRB Menurut Pengeluaran Triwulan 3', '2025', '2025s106', '<p>PJK:&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>\n<p>Hendra Dharmawan, SST, M.Si</p>\n<p>Anggota:&nbsp; &nbsp;</p>\n<ol>\n<li>Mazaya Alifah Syadzwina, S.Tr.Stat</li>\n<li>Cahya Danu Rahman, SST</li>\n</ol>', '<p>Salah satu parameter yang digunakan untuk melihat gambaran kinerja&nbsp;perekonomian secara makro suatu wilayah dalam periode tertentu adalah&nbsp;Produk Domestik Regional Bruto (PDRB). Jika PDRB dilihat dari sisi&nbsp;pengeluaran dapat menggambarkan konsumsi masyarakat, konsumsi&nbsp;pemerintah, investasi dan neraca perdagangan.<br>Publikasi Produk Domestik Regional Bruto Menurut Pengeluaran Provinsi Aceh Triwulan 3 Tahun 2025 mendiseminasikan kajian tentang gambaran kinerja perekonomian secara lebih dini dan lengkap pada periode tersebut.</p>', 'NULL', '2025-07-24 10:06:58', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('EdsusCVKE1D', '2024s105', 'Survei Jasa Penunjang Angkutan Domestik', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Hani\'ah</p>\n<p>Anggota&nbsp; &nbsp; : Akhmad Sugito&nbsp;</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ferfi Hamdina&nbsp;</p>', '<p>Link Dashboard</p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pelatihan Innas dan Petugas</td>\n<td>&nbsp;</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;&nbsp;2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-05 11:43:53', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('eE46KLiqzzx', '2024s103', 'Statisik Kependudukan', '2024', '2024s102', '<p><strong>Ketua </strong>Tim: Abd.Hakim<br><strong>PJK</strong>:M.Ridha &nbsp; &nbsp;<br><strong>Anggota </strong>:A.Sugito &nbsp; &nbsp;Darwis &nbsp; &nbsp;Juliana &nbsp; &nbsp;Zelvia &nbsp; &nbsp;Maulidya &nbsp; &nbsp;Fitral</p>', '<p><em>Statistik kependukan berisi informasi terkait data Demografi (Jumlah Penduduk &amp; Parameter Demografi)</em></p>\n<p>Proyeksi Penduduk (<strong>Link Untuk Internal)</strong> dapat di akses melalui link : <a href="https://drive.google.com/drive/u/2/folders/0Bw2KuSYZGXpyc1FEcGZfOGhCTFk?resourcekey=0-Sh6eLh1F0qLw_GrQhKpGvw">https://drive.google.com/drive/u/2/folders/0Bw2KuSYZGXpyc1FEcGZfOGhCTFk?resourcekey=0-Sh6eLh1F0qLw_GrQhKpGvw</a>&nbsp;</p>\n<p>Parameter Demografi dapat di akses melalui link : <a href="https://drive.google.com/drive/u/2/folders/1kT4U5hqqL0sFZ9y0Sh85QXSin3zwRPsH">https://drive.google.com/drive/u/2/folders/1kT4U5hqqL0sFZ9y0Sh85QXSin3zwRPsH</a>&nbsp;</p>', '<p><span style="font-size: 12pt;"><strong><span style="color: rgb(186, 55, 42);"><span style="line-height: 107%; font-family: Calibri, \'sans-serif\';">Jadwal Pelaksanaan Implementasi Platform Sistem Statistik Hayati Indonesia (SSHI) : N/A</span></span></strong></span></p>\n<p><span style="color: rgb(186, 55, 42);"><strong>Provinsi Aceh tidak termasuk dalam wilayah Uji Coba SUPAS2025&nbsp;</strong></span></p>', '2024-03-18 9:45:04', '198109132006021001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('eElZOm8dMx5', '2024s101', 'Revisi Anggaran', '2024', '2024s101', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Reza Rezki Pulungan</p>\n<p>Anggota : Kanasha Humaira</p>', '<p>Revisi Anggaran terdiri atas:&nbsp;</p>\n<p>a. Revisi Anggaran dalam hal Pagu Anggaran berubah;</p>\n<p>b. Revisi Anggaran dalam hal Pagu Anggaran tetap; dan</p>\n<p>c. Revisi Administrasi.</p>\n<p>&nbsp;</p>\n<p>Petunjuk Teknis Revisi Anggaran</p>\n<p><a href="https://drive.google.com/file/d/12lO15qo7JKledsMboIeXXoi0d-098POd/view">1. PMK No 62 Tahun 2023 Tentang Perencanaan Anggaran, Pelaksanaan Anggaran serta Akuntansi dan Pelaporan Keuangan</a></p>\n<p><a href="https://drive.google.com/file/d/1IiIQJPSGhjfdX0OG1iwMNukAIqPYVgU8/view">2. PER-9/PB/2023 Tentang Petunjuk Teknis Revisi Anggaran yang menjadi Kewenangan Direktorat Jenderal Perbendaharaan</a></p>\n<p>&nbsp;</p>', '<p><strong>Batas Akhir Revisi Anggaran</strong></p>\n<table style="border-collapse: collapse; width: 100%;" border="1"><colgroup><col style="width: 38.1066%;"><col style="width: 61.8536%;"></colgroup>\n<tbody>\n<tr>\n<td>Hari kesepuluh bulan Februari 2024</td>\n<td>Pemutakhiran Halaman III DIPA Triwulan I 2024</td>\n</tr>\n<tr>\n<td>Hari kesepuluh bulan April 2024</td>\n<td>Pemutakhiran Halaman III DIPA Triwulan II 2024</td>\n</tr>\n<tr>\n<td>Hari kesepuluh bulan Juli 2024</td>\n<td>Pemutakhiran Halaman III DIPA Triwulan III 2024</td>\n</tr>\n<tr>\n<td>Hari kesepuluh bulan Oktober 2024</td>\n<td>Pemutakhiran Halaman III DIPA Triwulan IV 2024</td>\n</tr>\n<tr>\n<td>31 Oktober 2024</td>\n<td>Pengesahan revisi anggaran yang menjadi kewenangan DJA</td>\n</tr>\n<tr>\n<td>30 November 2024</td>\n<td>Pengesahan revisi anggaran yang menjadi kewenangan DJPb</td>\n</tr>\n<tr>\n<td>27 Desember 2024</td>\n<td>Pemutakhiran data berkaitan dengan revisi POK oleh KPA, termasuk yang mengakibatkan perubahan halaman III DIPA</td>\n</tr>\n<tr>\n<td>31 Desember 2024</td>\n<td>Revisi anggaran penyelesaian pagu minus belanja pegawai</td>\n</tr>\n</tbody>\n</table>', '2024-06-25 14:13:38', '198504232008011001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
