	('Gr1FwOO7rX8', '2024s101', 'Penyusunan Perjanjian Kinerja BPS Provinsi Aceh Tahun 2024', '2024', '2024s101', '<p>Reza Rezki Pulungan</p>\n<p>Kanasha Humaira</p>', '<p><strong>Perjanjian kinerja</strong>&nbsp;adalah lembar/<strong>dokumen</strong>&nbsp;yang berisikan penugasan dari pimpinan instansi yang lebih tinggi kepada pimpinan instansi yang lebih rendah untuk melaksanakan program/kegiatan yang disertai dengan indikator&nbsp;<strong>kinerja</strong>.</p>\n<p>Dokumen terkait penyusunan Perjanjian Kinerja 2024 dapat diakses pada tautan&nbsp;<strong><a href="https://s.id/PK2024_Aceh">http://s.id/PK2024_Aceh</a></strong></p>', '<table style="border-collapse: collapse; width: 69.694%;" border="1"><colgroup><col style="width: 50.5159%;"><col style="width: 49.4841%;"></colgroup>\n<tbody>\n<tr>\n<td style="text-align: center;"><strong>Kegiatan</strong></td>\n<td style="text-align: center;"><strong>Tanggal</strong></td>\n</tr>\n<tr>\n<td>1. Pelaporan target PK 2024</td>\n<td>paling lambat 30 Januari 2024</td>\n</tr>\n<tr>\n<td>2. Penandatanganan PK 2024</td>\n<td>29 Januari 2024</td>\n</tr>\n<tr>\n<td>3. Upload pada Si Monev BPS</td>\n<td>Paling lambat 13 Februari 2024&nbsp;</td>\n</tr>\n<tr>\n<td>4. Upload&nbsp; E SAKIP REVIU MENPAN</td>\n<td>Paling lambat 13 Februari 2024</td>\n</tr>\n</tbody>\n</table>', '2024-03-26 12:19:47', '198504232008011001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('GwijEQUfrix', '2024s103', 'Potensi Desa (PODES) 2024', '2024', '2024s102', '<p><strong>Ketua Tim</strong>: Abd.Hakim<br><strong>PJK</strong>: A.Sugito &nbsp; &nbsp;<br><strong>Anggota</strong>: Juliana &nbsp; &nbsp;Fitral &nbsp; &nbsp;M.Ridha &nbsp; &nbsp;Zelvia &nbsp; &nbsp;Maulidya &nbsp; &nbsp;Darwis &nbsp; &nbsp;Mukhlis &nbsp; &nbsp;Bahzur A Chairina</p>', '<p>Pelatihan Inda :</p>\n<p><a href="https://drive.google.com/drive/folders/1nwypJM9ATIP6yelp9enGkqqlKG4ZYlnD">https://drive.google.com/drive/folders/1nwypJM9ATIP6yelp9enGkqqlKG4ZYlnD</a>&nbsp;</p>\n<p><a href="https://drive.google.com/drive/folders/1WyZ8NrZMPqlnOrSTCxp1rc-Ub0mjMvI5">https://drive.google.com/drive/folders/1WyZ8NrZMPqlnOrSTCxp1rc-Ub0mjMvI5</a>&nbsp;</p>\n<p>&nbsp;</p>\n<p>Monitoring PODES 2024 Aceh</p>\n<p><a href="https://s.bps.go.id/monitoringpodes24_aceh">https://s.bps.go.id/monitoringpodes24_aceh</a>&nbsp;</p>', '<table style="border-collapse: collapse; width: 671pt;" border="0" width="894" cellspacing="0" cellpadding="0"><colgroup><col style="mso-width-source: userset; mso-width-alt: 16896; width: 363pt;" width="484"> <col style="mso-width-source: userset; mso-width-alt: 14312; width: 308pt;" width="410"> </colgroup>\n<tbody>\n<tr style="height: 12.5pt;">\n<td class="xl67" style="height: 12.5pt; width: 363pt;" width="484" height="17">Pelatihan Admin LMS&nbsp;</td>\n<td class="xl68" style="width: 308pt;" width="410">18-20 Mar 2024</td>\n</tr>\n<tr style="height: 12.5pt;">\n<td class="xl65" style="height: 12.5pt; border-top: none;" height="17">Pelatihan Innas&nbsp;</td>\n<td class="xl66" style="border-top: none;">25-29 Mar 2024</td>\n</tr>\n<tr style="height: 12.5pt;">\n<td class="xl65" style="height: 12.5pt; border-top: none;" height="17">Pelatihan Inda&nbsp;</td>\n<td class="xl66" style="border-top: none;">1-5 Apr 2024</td>\n</tr>\n<tr style="height: 12.5pt;">\n<td class="xl65" style="height: 12.5pt; border-top: none;" height="17">Pelatihan Petugas&nbsp;</td>\n<td class="xl66" style="b