	('H26Opp6emHK', '2024s106', 'Penyusunan Publikasi Statistik Daerah', '2025', '2025s106', '<p>PJK:</p>\n<p>Hilda Aprina, SST, M.Si</p>\n<p>Anggota:</p>\n<p>Azwar, SE</p>', '<p>Publikasi ini menyajikan gambaran umum kondisi wilayah Provinsi Aceh</p>\n<p>yang dilihat dari beberapa aspek antara lain kondisi geografis, iklim, kependudukan, ketenagakerjaan, sosial, ekonomi, dan pariwisata.</p>', 'NULL', '2025-07-24 8:19:53', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('h8G4j1lh8Or', '2024s101', 'Pengelolaan Internalisasi Nilai Inti, Prinsip, Etika dan Branding ASN serta Penguatan Budaya Organisasi', '2024', '2024s108', '<p>Ketua :&nbsp;<strong>Yan Yan Gustiana</strong></p>\n<p>Anggota :</p>\n<p>Maulizasari</p>\n<div class="hc-details hc-details-open-top">\n<div id="hover_340058828">Mazaya Alifah Syadzwina</div>\n<div>Rodiah</div>\n</div>\n<p>Wahdini</p>\n<p>Reza Rezki Pulungan</p>\n<p>Edo Mara Nasution</p>\n<p>Hendra Gunawan</p>\n<p>&nbsp;</p>', '<p>Reviu undang-undang lama tentang ASN&nbsp;<em>UU No. 05 tahun 2014</em> <strong>VS</strong> undang-undang terbaru <em>UU No. 20 tahun 2023</em> <a href="https://drive.bps.go.id/apps/files/?dir=/%5B02.%20Share%20-%20BPS%20Provinsi%20Aceh%5D/08%20Tim%20Tranformasi%20dan%20Budaya%20Organisasi/2.%20Internalisasi%20Nilai%20%26%20Budaya%20Organisasi/Februari&amp;fileid=26712186">UU No. 20 tahun 2023 tentang ASN</a></p>', '<p>Jadwal menyusul</p>', '2024-02-22 12:50:27', '199509142019032002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('HcaTUru2iTc', '2024s102', 'Sharing Knowledge Teknologi Informasi (SKTI)', '2025', '2025s105', '<p>Fitral Pratomo SST<br>Oriza Santifa S.Si, M.Si<br>Kahar Muzzakar SST, M.Si<br>Munandar S.Si<br>Wira Junardi SST, M.T.<br>M. Alimuddin SST, M.T<br>Adrian Devano S.Tr.Stat.<br>Muhammad Farhan S.Tr.Stat<br>Zahlul Fuadi S.Tr.Stat.</p>', '<p><strong>Sharing Knowledge Teknologi Informasi (SKTI)&nbsp;</strong>dilaksanakan dengan tujuan untuk meningkatkan dan menambah pengetahuan seputar Teknologi Informasi bagi seluruh pegawai BPS se-Provinsi Aceh. Link SKTI <strong><a href="https://s.id/skti1100">s.id/skti1100</a></strong></p>', 'NULL', '2025-07-23 14:34:33', '199906212022011001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('HDqjO0XYK3U', '2024s101', 'Monitoring Pengisian SKP Tahunan', '2024', '2024s101', '<p>Wahdini, S.Psi. &nbsp; &nbsp;</p>\n<p>Muhammad Hafidz Al Ahmad Bit, S.Tr.Stat.</p>\n<p>&nbsp;Cut Emalita, SE.</p>\n<p>Ika Virnaristanti, S.Si.,M.Si</p>', '<p>Montoring dilakukan hingga ke tahap semua SKP Tahunan telah dinilai.</p>\n<p>&nbsp;</p>', '<p>Minggu ke -1 dan ke - 2 Januari 2024.</p>', '2024-03-21 11:16:18', '199905312021041001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('hf2d4Z6Nhhi', '2024s102', 'Pojok Statistik', '2024', '2024s109', '<p><strong>Ketua Tim</strong>: Wahyu Agung Sutikno<br><strong>PJK</strong>: Nur Hasanah<br><strong>Anggota</strong>: M. Alimuddin, Fikri</p>', '<p>Kegiatan di Pojok Statistik mencakup:</p>\n<ol>\n<li>Internalisasi Pojok Statistik</li>\n<li>Visitasi BPS ke Pojok Statistik USK dan UINAR</li>\n<li>Refreshing Pojok Statistik Virtual (PSV)</li>\n<li>Statistics Data Camp</li>\n</ol>\n<p>&nbsp;</p>', '<ol>\n<li>Internalisasi Pojok Statistik 16 Februari 2024</li>\n<li>Visitasi BPS ke Pojok Statistik USK (23 Februari, 22 Mei, dan 29 Mei 2024) dan UINAR (23 dan 29 Februari 2024)</li>\n<li>Refreshing Pojok Statistik Virtual (PSV) pada 3 dan 28 Maret 2024</li>\n<li>Statistics Data Camp (14 Juni - 26 September 2024)</li>\n</ol>', '2024-02-20 15:06:58', '198607312009022006', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('HfauKZTF9WR', '2024s101', 'Penginputan Masterplan', '2025', '2025s101', '<p>PJK : Reza Rezki Pulungan</p>\n<p>Anggota : 1. Kanasha Humaira</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2. Thariana Ayu Islami</p>', '<p>Penginputan melalui aplikasi IPLAN&nbsp;</p>', 'NULL', '2025-07-28 8:40:36', '198504232008011001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('HHtAMsyxg7T', '2024s103', 'Indeks Demokrasi Indonesia (IDI) 2024', '2025', '2025s102', '<p><strong>Ketua </strong>Tim: Abd.Hakim<br><strong>PJK</strong>:M.Ridha &nbsp;&nbsp;<br><strong>Anggota</strong>: Darwis,Alfi,Juliana,Naura,Ismaturahmi,Maulidya</p>', '<p>Indeks Demokrasi Indonesia (IDI) adalah&nbsp;<strong>indikator komposit yang menunjukkan tingkat perkembangan demokrasi di Indonesia</strong>. Indikator ini didapatkan melalui kompilasi berbagai fenomena terkait demokrasi yang terjadi di suatu daerah.</p>\n<p dir="ltr">File Mekanisme FGD IDI : <a href="http://s.bps.go.id/Mekanisme_FGD_IDI">s.bps.go.id/Mekanisme_FGD_IDI</a>&nbsp;&nbsp;</p>\n<p dir="ltr">web entry):&nbsp;<a href="https://statpolkam.bps.go.id">https://statpolkam.bps.go.id</a></p>', '<p>Pengumpulan Data Dokumen : 1 Desember 2024 - 31 Januari 2025<br>Pelaksanaan FGD IDI 2024 : 1 Maret 2025 31 Maret 2025</p>', '2025-07-26 22:26:21', '198109132006021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('Hl3zU42WI0k', '2024s102', 'Web SERASI', '2024', '2024s105', '<p><strong>Ketua Tim : </strong>Fitral</p>\n<p><strong>PJK :</strong> Ichsan</p>\n<p><strong>Anggota:</strong> Egi</p>', '<p>link : <a href="s.id/serasi1100" target="_blank" rel="noopener">s.id/serasi1100</a></p>', '<ul>\n<li>Perancangan : Juli 2024</li>\n<li>Pengembangan : Juli - Agustus 2024</li>\n<li>Evaluasi : Agustus - September 2024</li>\n</ul>', '2024-08-20 10:31:33', '199501232018021001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('hW9N0QIaKqD', '2024s102', 'Pemutakhiran MFD', '2024', '2024s105', '<ol>\n<li>\n<p><strong>Ketua Tim</strong>: Fitral Pratomo</p>\n<p><strong>Pjk</strong>: Wira Junardi</p>\n<p><strong>Anggota</strong>:&nbsp;</p>\n<ul>\n<li>Ichsan Hasanudin</li>\n<li>Anandika Dian Pramesti</li>\n</ul>\n</li>\n</ol>', '<p>1. Pemutakhiran MFDOnline melalui&nbsp;<a href="http://frs.bps.go.id/area" target="_blank" rel="noopener"><strong><em>frs.bps.go.id/area</em></strong></a>&nbsp;terdiri dari:</p>\n<ul>\n<li>PWA, perubahan wilayah administrasi level provinsi,&nbsp;kecamatan, dan desa</li>\n<li>MB, perubahan Blok Sensus (BS)</li>\n<li>MS, Perubahan Satuan Lingkungan Setempat (SLS)</li>\n</ul>\n<p>2. Rilis Master wilkerstat, <strong><em><a href="https://s.bps.go.id/MFD_Rilis_Daerah" target="_blank" rel="noopener">folder MFD</a></em></strong></p>\n<p>2. Publikasi Master File Wilayah (MFW) tahun 2023, <strong><em><a title="publikasi MFW 2023" href="https://aceh.bps.go.id/publication/2023/10/31/a270f9a67778b1a118623743/master-file-wilayah-provinsi-aceh-2023.html" target="_blank" rel="noopener">publikasi MFW 2023</a></em></strong></p>\n<p>&nbsp;</p>', '<ul>\n<li>Pemutakhiran MFD 2024 Semester I : 1 Februari - 30 Juni 2024</li>\n<li>Rilis Master&nbsp;MFD 2024 Semester I : Oktober 2024</li>\n<li>Publikasi Master File Wilayah Tahun 2024 : Oktober 2024</li>\n<li>Pemutakhiran MFD 2024 Semester II : Juli - Desember 2024</li>\n<li>Rilis Master&nbsp;MFD 2024 Semester II : Januari&nbsp;2025</li>\n</ul>\n<p>&nbsp;</p>', '2024-02-21 10:39:44', '198906132012111001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('i72Wddg5IPB', '2024s101', 'Penyusunan Rencana Kerja dan Anggaran Tahun 2025', '2024', '2024s101', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Reza Rezki Pulungan</p>\n\n<p>Anggota&nbsp; : Kanasha Humaira</p>', '<p>Penginputan pada aplikasi sakti pada tautan&nbsp;<a href="https://sakti.kemenkeu.go.id/">https://sakti.kemenkeu.go.id/</a></p>', '<p>Penginputan RKA Tahun 2025 dimulai sekitar bulan Agustus 2024</p>', '2024-01-23 14:12:00', '198504232008011001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('IdONtJQL6AD', '2024s101', 'Revisi Anggaran', '2025', '2025s101', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Reza Rezki Pulungan</p>\n<p>Anggota : 1. Kanasha Humaira</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2. Thariana Ayu Islami</p>', '<p>Revisi Anggaran terdiri atas:&nbsp;</p>\n<p>a. Revisi Anggaran dalam hal Pagu Anggaran berubah;</p>\n<p>b. Revisi Anggaran dalam hal Pagu Anggaran tetap; dan</p>\n<p>c. Revisi Administrasi.</p>\n<p>&nbsp;</p>\n<p>Petunjuk Teknis Revisi Anggaran</p>\n<ol>\n<li><a title="Peraturan Menteri Keuangan 107 Tahun 2024 tentang Perubahan atas Peraturan&nbsp;Menteri Keuangan Nomor 62 Tahun 2023 tentang Perencanaan Anggaran, Pelaksanaan Anggaran, serta Akuntansi dan Pelaporan Keuangan;" href="https://drive.google.com/file/d/1LK6QBTowyeqD4CYZJziCHrkV40CYQQsp/view?usp=sharing">Peraturan Menteri Keuangan 107 Tahun 2024 tentang Perubahan atas Peraturan Menteri Keuangan Nomor 62 Tahun 2023 tentang Perencanaan Anggaran, Pelaksanaan </a><a title="Peraturan Menteri Keuangan 107 Tahun 2024 tentang Perubahan atas Peraturan&nbsp;Menteri Keuangan Nomor 62 Tahun 2023 tentang Perencanaan Anggaran, Pelaksanaan Anggaran, serta Akuntansi dan Pelaporan Keuangan;" href="https://drive.google.com/file/d/1LK6QBTowyeqD4CYZJziCHrkV40CYQQsp/view?usp=sharing">Anggaran, serta Akuntansi dan Pelaporan Keuangan;</a></li>\n</ol>\n<p><a href="https://drive.google.com/file/d/1IiIQJPSGhjfdX0OG1iwMNukAIqPYVgU8/view" target="_blank" rel="noopener">&nbsp; &nbsp; &nbsp; 2. PER-9/PB/2023 Tentang Petunjuk Teknis Revisi Anggaran yang menjadi Kewenangan Direktorat Jenderal Perbendaharaan</a></p>', 'NULL', '2025-07-21 11:14:34', '198504232008011001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('iDUsNik1Ioz', '2024s106', 'Snapshot Perekonomian Regional Triwulanan', '2025', '2025s106', '<p>PJK:</p>\n<p>Hendra Dharmawan, SST, M.Si</p>', '<p>Pelaksanaan Pendataan Snapshot Perekonomian Regional Triwulanan</p>', 'NULL', '2025-07-24 11:21:08', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('IfAzk27uUWz', '2024s103', 'DTSEN 2025', '2025', '2025s102', '<p><strong>Ketua </strong>Tim: Abd.Hakim<br><strong>PJK</strong>:M.Ridha &nbsp;&nbsp;<br><strong>Anggota</strong>: Darwis,Alfi,Juliana,Naura,Ismaturahmi,Maulidya</p>', '<p>DTSEN adalah singkatan dari Data Terpadu Sosial Ekonomi Nasional, yang merujuk pada basis data terpadu yang menggabungkan data sosial dan ekonomi. Sistem ini dibangun untuk meningkatkan akurasi dan transparansi dalam penyaluran bantuan sosial di Indonesia. Selain itu, DTSEN juga berfungsi sebagai sistem yang berisi informasi tentang kondisi sosial dan ekonomi masyarakat di tingkat nasional.</p>\n<p>Pelatihan :</p>\n<p dir="ltr"><a href="http://s.bps.go.id/link-ytb-pembukaan-pelatihanDTSEN25">s.bps.go.id/link-ytb-pembukaan-pelatihanDTSEN25</a>&nbsp;</p>\n<p dir="ltr"><a href="https://linktr.ee/GC_DTSEN_Kemensos">https://linktr.ee/GC_DTSEN_Kemensos</a></p>\n<p dir="ltr"><a href="http://s.id/youtube-Pembukaan-Pelatihan-DSTEN">s.id/youtube-Pembukaan-Pelatihan-DSTEN</a>&nbsp;</p>\n<p dir="ltr"><a href="http://s.bps.go.id/biodata-innas-DTSEN2025">s.bps.go.id/biodata-innas-DTSEN2025</a></p>\n<p dir="ltr">Monitoring</p>\n<p dir="ltr"><a href="https://dashboard.apps.bps.go.id">https://dashboard.apps.bps.go.id</a>&nbsp;</p>\n<p dir="ltr"><a href="https://s.bps.go.id/mon-kegdtsen25-1100">s.bps.go.id/mon-kegdtsen25-1100</a></p>\n<p dir="ltr">User Dashboard GC</p>\n<p dir="ltr"><a href="http://s.bps.go.id/user-dashboard-GCDTSEN">s.bps.go.id/user-dashboard-GCDTSEN</a>&nbsp;</p>\n<p dir="ltr">Permasalahan Lapangan</p>\n<p dir="ltr"><a href="http://s.bps.go.id/PermasalahanGCKemensos2025">s.bps.go.id/PermasalahanGCKemensos2025</a>&nbsp; &nbsp;</p>\n<p dir="ltr">Dokumentasi</p>\n<p dir="ltr"><a href="http://s.bps.go.id/dok-dtsen1100">s.bps.go.id/dok-dtsen1100</a></p>', 'NULL', '2025-07-26 22:50:21', '198109132006021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('iHdQs2RoyXz', '2024s101', 'Nilai Kinerja Anggaran', '2024', '2024s101', '<p>-</p>', '<p>-</p>', '<p>-</p>', '2024-02-26 15:11:01', '198407082008011003', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('iNFKyrGohnO', '2024s103', 'Response Rate Survei Berbasis Rumah Tangga (Sosial)', '2024', '2024s102', '<p>Ketua Tim: Abd. Hakim</p>\n<p>Tim Penyusun : Zelvia,Maulidya,A.Sugito,Juliana,M.Ridha,Darwis</p>', '<p>Penjelasan lebih lanjut terkait jadwal kegiatan (Susenas, Seruti, Sakernas dan SNLIK) dapat diakses melalui <a href="https://s.id/bupesta">https://s.id/bupesta</a>&nbsp;</p>', '<p>Penjelasan lebih lanjut terkait informasi kegiatan (Susenas, Seruti, Sakernas dan SNLIK) dapat diakses melalui <a href="https://s.id/bupesta">https://s.id/bupesta</a>&nbsp;</p>', '2024-02-26 12:02:25', '198407082008011003', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('inwlyNWpXof', '2024s105', 'Survei Harga Produsen Pertanian (HPT)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Mursalina</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>', '<p>Link Dashboard:&nbsp;<a href="https://webentry.bps.go.id/shp/" target="_blank" rel="noopener">https://webentry.bps.go.id/shp/</a></p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pelatihan Innas dan Petugas</td>\n<td>&nbsp;Januari 2024</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;Januari - Desember&nbsp;2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-05 10:42:43', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('IQ6z4wFLqu6', '2024s103', 'Survei Ekonomi Rumah Tangga Triwulan (Seruti) 2025', '2025', '2025s102', '<p><strong>Ketua </strong>Tim: Abd.Hakim<br><strong>PJK</strong>:Subhan &nbsp;&nbsp;<br><strong>Anggota</strong>: Juliana,Naura,M.Ridha,Darwis,Alfi,Ismaturahmi,Maulidya</p>', '<p>Survei Ekonomi Rumah Tangga Triwulanan (Seruti) merupakan survei berbasis rumah tangga yang merupakan integrasi tiga survei yaitu Survei Sosial Ekonomi Nasional (Susenas), Survei Khusus Konsumsi Rumah Tangga Triwulanan (SKKRT), dan Survei Khusus Tabungan dan Investasi Rumah tangga (SKTIR). Survei ini dilaksanakan untuk mengurangi duplikasi kegiatan dan meningkatkan efisiensi, serta menghasilkan data statistik ekonomi rumah tangga yang lebih berkualitas. Pentingnya menjaga kualitas data statististik ekonomi rumah tangga ini menjadi urgent karena data ini menjadi salah satu sumber data dalam penyusunan PDRB menurut pengeluaran.&nbsp;</p>', '<table style="border-collapse: collapse; width: 294pt;" border="0" width="390" cellspacing="0" cellpadding="0"><colgroup><col style="width: 130px;" width="110"> <col style="width: 149px;" width="169"> <col style="width: 112px;" width="111"> </colgroup>\n<tbody>\n<tr style="height: 15.0pt;">\n<td class="xl66" style="height: 15pt; width: 83pt; text-align: center;" width="110" height="20"><strong>Kegiatan</strong></td>\n<td class="xl68" style="width: 211pt; text-align: center;" colspan="2" width="280"><strong>Jadwal</strong></td>\n</tr>\n<tr style="height: 15.0pt;">\n<td class="xl67" style="height: 15.0pt; width: 83pt;" width="110" height="20">Seruti Triwulan 1</td>\n<td class="xl65" style="border-top: none; border-left: none; width: 127pt; overflow: hidden; padding-bottom: 2px; padding-top: 2px;" width="169">8-Feb-25</td>\n<td class="xl65" style="border-top: none; border-left: none; width: 84pt;" width="111">17-Feb-25</td>\n</tr>\n<tr style="height: 15.0pt;">\n<td class="xl67" style="height: 15.0pt; border-top: none; width: 83pt; overflow: hidden; padding-bottom: 2px; padding-top: 2px;" width="110" height="20">Seruti Triwulan 2</td>\n<td class="xl65" style="border-top: none; border-left: none; width: 127pt;" width="169">10-Jun-25</td>\n<td class="xl65" style="border-top: none; border-left: none; width: 84pt;" width="111">30-Jun-25</td>\n</tr>\n<tr style="height: 15.0pt;">\n<td class="xl67" style="height: 15.0pt; border-top: none; width: 83pt; overflow: hidden; padding-bottom: 2px; padding-top: 2px;" width="110" height="20">Seruti Triwulan 3</td>\n<td class="xl65" style="border-top: none; border-left: none; width: 127pt;" width="169">11-Sep-25</td>\n<td class="xl65" style="border-top: none; border-left: none; width: 84pt;" width="111">20-Sep-25</td>\n</tr>\n<tr style="height: 15.0pt;">\n<td class="xl67" style="height: 15.0pt; border-top: none; width: 83pt; overflow: hidden; padding-bottom: 2px; padding-top: 2px;" width="110" height="20">Seruti Triwulan 4</td>\n<td class="xl65" style="border-top: none; border-left: none; width: 127pt;" width="169">11-Nov-25</td>\n<td class="xl65" style="border-top: none; border-left: none; width: 84pt;" width="111">30-Nov-25</td>\n</tr>\n</tbody>\n</table>', '2025-07-26 21:38:40', '198109132006021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('IuemjIgqT4X', '2024s105', 'Kompilasi Data Jasa Angkutan Domestik Panjang Jalan PJ II.6 dan PJ II.5', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Hani\'ah</p>\n<p>Anggota&nbsp; &nbsp; : Akhmad Sugito&nbsp;</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ferfi Hamdina&nbsp;</p>', '<p>Link Dashboard:&nbsp;</p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pelatihan Innas dan Petugas</td>\n<td>&nbsp;</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;&nbsp;2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-05 11:42:09', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('j3F3ljkdj0T', '2024s101', 'Perencanaan, Pemilihan Penyedia dan Pengelolaan Kontrak Pengadaan Barang dan Jasa Pemerintah', '2024', '2024s101', '<p>Rediansyah Arief, SP, M.Si</p>\n<p>Chairina, S.M.</p>\n<p>Nasliyah Husna, S.P</p>\n<p>Dhien Auliatu Asra, S.E.</p>', '<p>Link Kontrak Tahun 2024 <a href="https://drive.google.com/drive/folders/1FAMu5QHPZM-dWTGCI468WPx5785MWGJE">https://drive.google.com/drive/folders/1FAMu5QHPZM-dWTGCI468WPx5785MWGJE</a></p>', '<p>Tanggal 1 Januari 2024 sampai dengan 31 Desember 2024</p>', '2024-02-26 14:11:12', '198902272012122001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('jEf1ZqQZgsl', '2024s102', 'Monitoring Keamanan Endpoint dengan SIEM', '2024', '2024s105', '<p><strong>Ketua : Fitral</strong></p>\n<p>Anggota:&nbsp;</p>\n<ul>\n<li>Munandar [PJK]</li>\n<li>Wira</li>\n<li>Hafidz</li>\n<li>Kahar&nbsp;</li>\n</ul>', '<p>Agar keamanan perangkat end user khususnya Personal Desktop lebih bisa di pantau dan dilakukan mitigasi, maka di gunakan SIEM (System Information Event Management).</p>\n<p>SIEM yang digunakan ada Wazuh dan akan coba terus untuk digunakan untuk tujuan keamanan.&nbsp;</p>', '<table style="border-collapse: collapse; width: 100.02%;" border="1"><colgroup><col style="width: 49.9621%;"><col style="width: 49.9621%;"></colgroup>\n<tbody>\n<tr>\n<td>Instalasi&nbsp;</td>\n<td>Juli 2024</td>\n</tr>\n<tr>\n<td>Add Endpoint</td>\n<td>Juli - September 2024</td>\n</tr>\n<tr>\n<td>Melakukan Update keamanan End point devices</td>\n<td>Juli-Desember 2024</td>\n</tr>\n</tbody>\n</table>', '2024-08-20 15:59:49', '198012212010031001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('JiVkK2CA3oz', '2024s105', 'Survei Pola Distribusi Komoditi Pangan (Poldis)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Hani\'ah</p>\n<p>Anggota&nbsp; &nbsp; : Akhmad Sugito&nbsp;</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ferfi Hamdina&nbsp;</p>', '<p>Link Dashboard:</p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pelatihan Innas dan Petugas</td>\n<td>&nbsp;</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;&nbsp;2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-05 11:26:40', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('JRPIk2lXriW', '2024s103', 'Indeks Demokrasi Indonesia (IDI) 2023', '2024', '2024s102', '<p><strong>Ketua Tim</strong>: Abd.Hakim<br><strong>PJK</strong>:M.Ridha &nbsp; &nbsp;<br><strong>Anggota </strong>:A.Sugito &nbsp; &nbsp;Darwis &nbsp; &nbsp;Juliana &nbsp; &nbsp;Zelvia &nbsp; &nbsp;Maulidya &nbsp; &nbsp;Chairina &nbsp; &nbsp;Mukhlis</p>', '<p><strong>Dashboard Input Berita ( Hanya dapat diakses oleh akun yang terdaftar) </strong>: <a href="https://statpolkam.bps.go.id/idi/">https://statpolkam.bps.go.id/idi/</a>&nbsp;</p>', '<p><span data-sheets-userformat="{" data-sheets-value="{" data-sheets-root="1">Pengumpulan Data/Koding: Jan - Des 2024</span></p>', '2024-02-21 9:13:17', '198109132006021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('JT58LDHrSas', '2024s103', 'Statistik politik dan keamanan (Statpolkam) 2024', '2024', '2024s102', '<p><strong>Ketua Tim</strong>: Abd.Hakim<br><strong>PJK</strong>:Juliana &nbsp; &nbsp;<br><strong>Anggota </strong>: Maulidya,A.Sugito,M.Ridha,Zelvia,Darwis</p>', '<p>-</p>', '<table style="border-collapse: collapse; width: 100.031%; border-width: 0px;" border="1"><colgroup><col style="width: 50.0403%;"><col style="width: 50.0403%;"></colgroup>\n<tbody>\n<tr>\n<td class="xl65" style="height: 13pt; width: 363pt; border-width: 0px;" width="484" height="17">Pengumpulan Data</td>\n<td class="xl66" style="width: 308pt; border-width: 0px;" width="410">1 Feb-30 Agust 2024</td>\n</tr>\n<tr>\n<td class="xl65" style="height: 12.5pt; border-width: 0px; border-top-style: none; border-top-color: initial;" height="17">Konsultasi dan Evaluasi Data</td>\n<td class="xl66" style="border-width: 0px; border-top-style: none; border-top-color: initial;">1 Feb-30 Agust 2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-20 11:14:38', '198109132006021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('Ju4A87D8Wg5', '2024s106', 'Penyusunan Angka PDRB Triwulan 2', '2025', '2025s106', '<p>PJK :</p>\n<p>Meita Jumiartanti, SST, M.Si</p>\n<p>Anggota:</p>\n<ol>\n<li>Hendra Dharmawan, SST, M.Si</li>\n<li>Ridha Mutia, SE, M.Si</li>\n<li>Hilda Aprina, SST, M.Si</li>\n<li>Cahya Danu Rahman, SST</li>\n<li>Maulizasari, S.Stat</li>\n<li>Fitri Mulyani, SST</li>\n<li>Mazaya Alifah Syadzwina, S.Tr.Stat</li>\n<li>Azwar, SE</li>\n</ol>\n<p>&nbsp;</p>', '<p><strong><span class="deskripsi-label">Tujuan dan Manfaat Kegiatan</span></strong></p>\n<p>Menyediakan data dan indikator ekonomi makro sebagai evaluasi dan perencanaan pembangunan</p>\n<p>&nbsp;</p>\n<p><strong><span class="deskripsi-label">Frekuensi Penyelenggaraan</span></strong></p>\n<p>Triwulanan dan Tahunan</p>', 'NULL', '2025-07-22 15:53:18', '198910212010122006', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('jzKLxL9MgZf', '2024s106', 'Survei Baseline Monitoring dan Evaluasi Program Makan Bergizi Gratis (MBG)', '2025', '2025s106', '<p>PJK:</p>\n<p>Cahya Danu Rahman, SST</p>', '<p>Dalam rangka mengukur outcome program MBG untuk anak sekolah&nbsp;pada jangka pendek, perlu dilakukan survei baseline guna menilai&nbsp;pengaruh MBG yang diberikan untuk anak sekolah terhadap indikator&nbsp;ketenagakerjaan, perubahan konsumsi rumah tangga, serta perubahan&nbsp;perilaku siswa dan rumah tangga terhadap pola makan bergizi di rumah&nbsp;tangga. Pelaksanaan Survei Baseline Monitoring dan Evaluasi Program&nbsp;MBG rencananya akan dilaksanakan dua kali, yaitu pada bulan Juli 2025&nbsp;dan bulan November 2025.</p>', 'NULL', '2025-07-24 11:41:29', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('jZQNMxbgDe3', '2024s102', 'Konfigurasi, perawatan dan monitoring perangkat TI', '2025', '2025s105', '<ol>\n<li>\n<p><strong>Ketua Tim</strong>: Fitral Pratomo</p>\n<p><strong>Pjk</strong>: Munandar</p>\n<p><strong>Anggota</strong>:&nbsp;</p>\n<ul>\n<li>M. Alimuddin&nbsp;SST, M.T</li>\n<li>Wira Junardi</li>\n</ul>\n</li>\n</ol>', '<ol>\n<li>Kegiatan Konfigurasi, Monitoring dan penanganan kendala perangkat utama jaringan</li>\n<li>Kegiatan Penanganan kendala pada perangkat Pengguna</li>\n<li>Monitoring dan penerapan keamanan perangkat pengguna</li>\n</ol>', '<p>Januari - Desember 2025</p>', '2025-02-28 8:59:04', '198012212010031001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('KayUpFmX4zH', '2024s104', 'Survei Air Bersih (Tahunan dan Triwulanan)', '2024', '2024s104', '<ol>\n<li>Andariati Afrida</li>\n<li>Cut Malahayati</li>\n<li>Fikri</li>\n<li>Ridha Mutia</li>\n</ol>', '<p>Survei Air Bersih dilakukan pada 21 Kabupaten/Kota di Provinsi Aceh secara Tahunan dan Triwulanan.&nbsp;</p>', '<ol>\n<li>Tahunan</li>\n<li>Triwulanan:&nbsp; Triwulan I pendataan dilakukan pada Januari 2024&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Triwulan II pendataan dilakukan pada April 2024&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Triwulan III pendataan dilakukan pada Juli 2024&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Triwulan IV pendataan dilakukan pada Januari 2025</li>\n</ol>', '2024-09-05 11:10:49', '196803101992122001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('kEXaJUPpHvO', '2024s105', 'International Comparison Program (ICP) komoditas kebutuhan rumah tangga', '2024', '2024s103', '<p>Ketua Tim : Titiek Zurryati</p>\n<p>PJK : Mursalina</p>\n<p>Anggota: Dwi Susanti</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Andariati Afrida</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Nyimas Eka</p>', '<p>Link Kegiatan ICP : <a href="http://s.bps.go.id/ICP2024_Aceh">http://s.bps.go.id/ICP2024_Aceh</a>&nbsp;</p>', '<table style="border-collapse: collapse; width: 100%;" border="1"><colgroup><col style="width: 49.9665%;"><col style="width: 49.9665%;"></colgroup>\n<tbody>\n<tr>\n<td>Pelatihan</td>\n<td>&nbsp;Februari 2024</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;Januari - Desember 2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-28 10:37:10', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('KKjbPMg0uiJ', '2024s102', 'Pemutakhiran Kerangka Geospasial dan Muatan Wilkerstat SE2026', '2025', '2025s105', '<ol>\n<li>\n<p><strong>Ketua Tim</strong>: Fitral Pratomo</p>\n<p><strong>Pjk</strong>: Kahar Muzakar</p>\n<p><strong>Anggota</strong>:&nbsp;</p>\n<ul>\n<li>Wira Junardi</li>\n<li>Muhammad Farhan</li>\n</ul>\n</li>\n</ol>', '<p dir="ltr" role="presentation">Kegiatan ini memiliki 2 (dua) tahapan sebagai berikut:</p>\n<ol>\n<li dir="ltr" aria-level="1">\n<p dir="ltr" role="presentation">Kegiatan lapangan yang terdiri dari pemutakhiran peta SLS, pemutakhiran muatan SLS, pembentukan Sub-SLS, dan pengambilan titik koordinat wilayah konsentrasi ekonomi;</p>\n</li>\n<li dir="ltr" aria-level="1">\n<p dir="ltr" role="presentation">Kegiatan pengolahan yang terdiri dari pengolahan muatan wilkerstat dan pengolahan peta wilkerstat;</p>\n</li>\n</ol>\n<p><strong id="docs-internal-guid-c5a4011e-7fff-367c-b52c-925650c6d68e">Jadwal kegiatan dapat dilihat pada lampiran dan penjelasan umum dapat diunduh melalui link <a href="http://s.bps.go.id/penjelasan_wilkerstat">https://s.bps.go.id/penjelasan_wilkerstat</a>;</strong></p>', 'NULL', '2025-02-18 8:42:31', '200101292023021004', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('KSdyJ9iowbM', '2024s106', 'Survei Monitoring dan Evaluasi Program Makanan Bergizi Gratis (MBG)', '2025', '2025s106', '<p>PJK:</p>\n<p>Cahya Danu Rahman, SST</p>', '<p>Pelaksanaan Survey Monitoring dan Evaluasi Program MBG merupakan langkah penting untuk memastikan efektivitas dan keberlanjutan program yang bertujuan meningkatkan gizi masyarakat.</p>\n<p>Survey ini mengumpulkan data komprehensif terkait pelaksanaan program, termasuk distribusi, kualitas makanan, serta dampak yang dirasakan oleh penerima manfaat. Survey ini diharapkan dapat memberikan gambaran akurat mengenai keberhasilan program dan menjadi dasar untuk perbaikan di masa mendatang.</p>', 'NULL', '2025-07-24 11:35:44', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('kxBsHliDIul', '2024s105', 'Survei Harga Perdagangan Besar (SHPB)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Melly</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Cut Malahayati&nbsp; &nbsp;</p>', '<p>Link Dashboard: <a href="https://webentry.bps.go.id/shpb/" target="_blank" rel="noopener">https://webentry.bps.go.id/shpb/</a></p>\n<p>&nbsp;</p>', '<table style="border-collapse: collapse; width: 43.0676%;" border="1"><colgroup><col style="width: 42.0418%;"><col style="width: 57.9582%;"></colgroup>\n<tbody>\n<tr>\n<td>Pencacahan</td>\n<td>Januari - Desember 2024</td>\n</tr>\n<tr>\n<td>Pengolahan</td>\n<td>Januari - Desember 2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-05 10:48:27', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('KXuUSWw0TMC', '2024s106', 'Penghitungan PDRB Triwulanan Provinsi Aceh', '2024', '2024s106', '<div class="daftar">\n<div class="daftar">\n<p>Ketua Tim: Meita Jumiartanti</p>\n<ul>\n<li>PIC Produksi: Ridha Meutia &amp; Fitri Mulyani</li>\n<li>PIC Pengeluaran: Hendra Dharmawan</li>\n</ul>\n</div>\n</div>', '<p>(akan dilengkapi kemudian)</p>', '<p>(akan dilengkapi kemudian)</p>', '2024-02-20 12:04:59', '198512092009021002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('kY8QVyfJnLM', '2024s101', 'Pendataan Satuan Harga Barang dan Jasa', '2024', '2024s101', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; : Reza Rezki Pulungan</p>\n\n<p>Anggota : Kanasha Humaira</p>\n\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Nelvi Istiqamah</p>', '<p>aplikasi dapat di akses pada tautan <a href="http://shbj.bps.go.id">shbj.bps.go.id</a></p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>', '<p>Brifing Petugas : 1&nbsp;Agustus 2024</p>\n\n<p>Pendataan&nbsp; &nbsp; &nbsp; &nbsp; ; 2 s.d 30 Agustus 2024</p>\n\n<p>Pengolahan&nbsp; &nbsp; &nbsp; : 14 Agustus s.d 8 September 2024</p>\n\n<p>Laporan&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : 25 September s.d 8 Oktober 2024</p>', '2024-01-23 2:06:08', '198504232008011001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('KYjUqBCcQco', '2024s102', 'Monitoring dan Evaluasi Keterbukaan Informasi Badan Publik Tahun 2024', '2024', '2024s107', '<ul>\n<li>Ketua: Tasdik</li>\n<li>Wakil Ketua: Hendri Achmad Hudori</li>\n</ul>', '<ul>\n<li>Website PPID: <a href="https://ppid.bps.go.id/?mfd=1100" target="_blank" rel="noopener">https://ppid.bps.go.id/?mfd=1100</a></li>\n</ul>', '<ul>\n<li>Pengumpulan kuesioner: 10 Juni 2024 ✅</li>\n<li>Visitasi &amp; presentasi: (belum terjadwal)</li>\n</ul>', '2024-06-19 11:17:42', '199711192021042001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('kyke9eKGXrT', '2024s102', 'Diskusi dan Sharing Knowledge Tim Pengolahan & TI', '2024', '2024s105', '<ol>\n<li>Fitral Pratomo (Ketua Tim Pengolahan &amp; TI)</li>\n<li>Munandar</li>\n<li>Kahar Muzzakar</li>\n<li>Wira Junardi</li>\n<li>Anandika Dian Pramesti&nbsp;</li>\n</ol>', '<p>Kegiatan ini terkait diskusi dan sharing knowledge kegiatan Tim Pengolahan &amp; TI</p>\n<ul>\n<li>Dokumentasi, notulensi, KAK, dan bahan paparan kegiatan Penguatan Tim Pengolahan &amp; TI 7-10 Oktober 2024 dapat diakses di&nbsp;<a href="https://drive.google.com/drive/folders/1akXNhxwB_kSgjz01TLCbOcTsJHsuWIZ1?usp=drive_link" target="_blank" rel="noopener">sini</a></li>\n</ul>', '<ul>\n<li>7-10 Oktober 2024: Penguatan Tim Pengolahan &amp; TI di Mata Ie Resort, Kota Sabang&nbsp;</li>\n</ul>', '2024-10-11 14:21:18', '199711192021042001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('L2t01YvSBvC', '2024s106', 'Penyusunan Publikasi PDRB Menurut Lapangan Usaha Triwulan 3', '2025', '2025s106', '<p>PJK :</p>\n<p>Ridha Mutia, SE, M.Si</p>\n<p>Anggota:</p>\n<ol>\n<li>Maulizasari, S.Stat</li>\n<li>Fitri Mulyani, SST</li>\n</ol>', '<p>Penghitungan PDRB yang digunakan dalam publikasi ini ialah melalui&nbsp;pendekatan produksi yaitu menghitung nilai tambah barang dan jasa yang<br>dihasilkan seluruh unit produksi di wilayah Provinsi Aceh setiap triwulan. PDRB&nbsp;pendekatan produksi atau menurut lapangan usaha diperoleh dari selisih nilai<br>barang dan jasa yang dihasilkan dikurangi bahan baku yang digunakan sebagai&nbsp;input ditambah pajak atas produk dikurangi subsidi atas produk. Unit-unit<br>produksi tersebut dikelompokkan menjadi 17 kategori lapangan usaha, yaitu:<br>A. Pertanian, kehutanan, dan&nbsp;perikanan;<br>B. Pertambangan dan penggalian;<br>C. Industri pengolahan;<br>D. Pengadaan listrik dan gas;<br>E. Pengadaan Air;<br>F. Konstruksi;<br>G. Perdagangan besar dan eceran&nbsp;dan reparasi mobil dan sepeda&nbsp;motor;<br>H. Transportasi dan pergudangan;<br>I. Penyediaan akomodasi &amp; makan minum;<br>J. Informasi &amp; komunikasi;<br>K. Jasa keuangan;<br>L. Real estate;<br>M,N Jasa perusahaan;<br>O Administrasi pemerintahan,&nbsp;pertahanan, &amp; jaminan sosial&nbsp;wajib;<br>P Jasa pendidikan;<br>Q Jasa kesehatan &amp; kegiatan&nbsp;sosial;<br>R,S,T,U Jasa lainnya</p>', 'NULL', '2025-07-24 10:09:30', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('l9kqAFAY15S', '2024s102', 'Web Buku Tamu + Antrian', '2024', '2024s105', '<p>Developer:</p>\n<ul>\n<li>Ichsan H</li>\n<li>Munandar</li>\n</ul>', '<p>link: <a href="https://webapps.bps.go.id/aceh/loket/" target="_blank" rel="noopener">webapps.bps.go.id/aceh/loket/</a></p>', '<p>Sepanjang tahun</p>', '2024-02-26 15:24:06', '199503172018022001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('lJIHPQa4nnW', '2024s105', 'Survei Harga Kemahalan Konstruksi (SHKK)', '2024', '2024s103', '<p>Ketua Tim : Titiek Zurryati</p>\n<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Melly</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Cut Malahayati&nbsp; &nbsp;</p>', '<p>Link Dashboard: <a href="https://webentry.bps.go.id/shkk/" target="_blank" rel="noopener">https://webentry.bps.go.id/shkk/</a></p>\n<p>&nbsp;</p>', '<table style="width: 500px;" border="1" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td>Kegiatan</td>\n<td>Jadwal</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>\n<ul>\n<li>Triwulan 1: Januari 2024</li>\n<li>Triwulan 2 : April 2024</li>\n<li>Triwulan 3 : Juli 2024</li>\n<li>Triwulan 4 : Oktober 2024</li>\n</ul>\n</td>\n</tr>\n<tr>\n<td>Rekonsiliasi Daerah</td>\n<td>&nbsp;Mei - Juni 2024</td>\n</tr>\n<tr>\n<td>Rekonsiliasi Nasional</td>\n<td>&nbsp;Juli 2024</td>\n</tr>\n<tr>\n<td>Refreshing Pencacahan</td>\n<td>&nbsp;Oktober 2024</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>', '2024-02-05 10:46:13', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('Ln2XxHRQcs1', '2024s104', 'Updating Direktori Perusahaan Pertanian (DPP) dan Direktori Usaha Pertanian Lainnya (DUTL) Tahun 2024', '2024', '2024s104', '<p>Andariati Afrida</p>\n<p>Hendra Gunawan</p>\n<p>Raiski Ramadhoni</p>\n<p>Nilam Humaira</p>\n<p>Kahar Muzakar</p>', '<p><span style="font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; mso-ansi-language: SV; mso-fareast-language: SV; mso-bidi-language: AR-SA;">Updating DPP DUTL 2024 bertujuan untuk memutakhirkan direktori perusahaan pertanian dan direktori usaha pertanian lainnya agar lengkap, akurat, dan terpercaya sesuai dengan keadaan terkini, dengan menggunakan prelist hasil pencacahan lengkap UPB dan UTL ST2023.</span></p>', '<p><img src="data:image/png;base64,"></p>', '2024-06-20 9:56:45', '198306042006021003', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('LNViPGoUwWt', '2024s105', 'Penyusunan BRS Statistik Harga Produsen', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Mursalina</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>', '<table dir="ltr" border="1" cellspacing="0" cellpadding="0" data-sheets-root="1"><colgroup><col width="509"><col width="127"><col width="100"></colgroup>\n<tbody>\n<tr>\n<td style="text-align: center;" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Berita Resmi Statistik (BRS) &quot;}"><strong>Berita Resmi Statistik (BRS)</strong></td>\n<td style="text-align: center;" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Penyusun&quot;}"><strong>Penyusun</strong></td>\n<td style="text-align: center;" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Pemeriksaan&quot;}"><strong>Pemeriksaan</strong></td>\n</tr>\n<tr>\n<td data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Nilai Tukar Petani dan Perkembangan Harga Produsen Gabah&quot;}">Nilai Tukar Petani dan Perkembangan Harga Produsen Gabah</td>\n<td data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Mursalina&quot;}">Mursalina</td>\n<td data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Titiek Z&quot;}">Titiek Zurryati</td>\n</tr>\n</tbody>\n</table>', '<table dir="ltr" style="width: 42.6658%; height: 45.7812px;" border="1" cellspacing="0" cellpadding="0" data-sheets-root="1"><colgroup><col style="width: 79.9058%;" width="509"><col style="width: 19.9372%;" width="127"></colgroup>\n<tbody>\n<tr style="height: 23.3906px;">\n<td style="text-align: center; height: 23.3906px;" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Berita Resmi Statistik (BRS) &quot;}"><strong>Berita Resmi Statistik (BRS)</strong></td>\n<td style="text-align: center; height: 23.3906px;" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Penyusun&quot;}"><strong>Jadwal Rilis</strong></td>\n</tr>\n<tr style="height: 22.3906px;">\n<td style="height: 22.3906px;" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Nilai Tukar Petani dan Perkembangan Harga Produsen Gabah&quot;}">Nilai Tukar Petani dan Perkembangan Harga Produsen Gabah</td>\n<td style="height: 22.3906px;" data-sheets-value="{&quot;1&quot;:2,&quot;2&quot;:&quot;Mursalina&quot;}">Setiap Awal Bulan</td>\n</tr>\n</tbody>\n</table>', '2024-02-21 15:58:11', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('lsGoCs9qdsQ', '2024s102', 'EA (Enumaration Area)', '2024', '2024s105', '<p><strong>Ketua Tim</strong>: Fitral Pratomo</p>\n<p><strong>Pjk</strong>: Wira Junardi</p>\n<p><strong>Anggota</strong>:&nbsp;</p>\n<ul>\n<li>Ichsan Hasanudin</li>\n<li>Anandika Dian Pramesti</li>\n</ul>', '<p>Pemutakhiran wilayah SLS yang mengalami/terdampak perubahan&nbsp;dari hasil Identifikasi SLS Podes 2024&nbsp;</p>', '<ol>\n<li>Pelatihan Innas&nbsp; : 5-8 Maret 2024</li>\n<li>Briefing Admin : 11 Maret 2024</li>\n<li>Pelatihan Inda : Maret - April 2024</li>\n<li>Pelaksanaan Pemutakhiran SLS : Juni - Juli 2024</li>\n<li>Pelaksanaan Pengolahan Muatan dan Peta : Juli - Agustus 2024</li>\n</ol>', '2024-02-21 10:25:36', '198906132012111001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('lUb4zWjbhmI', '2024s106', 'Survei Khusus Tahunan (SKT) DNPeng', '2024', '2024s106', '<p>Ketua Tim: Meita Jumiartanti</p>\n<p>PJK: Hendra Dharmawan<br>Anggota: Ar Razy Ridha Maulana, Edo Mara Nst, Zulviyana, dan Ita Meriati</p>', '<p>Belum Ada</p>', '<p>Pelatihan Petugas: Juni 2024</p>\n<p>Pengumpulan Data: Juli-September 2024</p>\n<p>Pemeriksaan Data: Agustus-September 2024</p>\n<p>Pengolahan Data: Agustus-September 2024<br>Tabulasi Data: Desember 2024</p>', '2024-02-19 9:54:33', '198512092009021002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('LUcl61285S0', '2024s101', 'Pendataan Satuan Harga Barang dan Jasa (SHBJ)', '2025', '2025s101', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Reza Rezki Pulungan</p>\n<p>Anggota : 1. Kanasha Humaira</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2. Thariana Ayu Islami</p>', '<p>1.Maksud dan Tujuan<br>Pendataaan SHBJ dimaksudkan untuk menunjang perencanaan pembangunan di bidang<br>statistik khususnya sebagai acuan nilai tertinggi suatu rincian belanja yang dibutuhkan<br>dalam pelaksanaan kegiatan. Adapun tujuan kegiatan ini adalah untuk mengumpulkan data<br>harga barang dan jasa yang digunakan sebagai ancar-ancar pelaksanaan pengadaan di<br>lingkungan BPS Provinsi Aceh</p>\n<p><br>2. Hasil dan Keluaran<br>Adapun hasil dan keluaran dari Pendataan SHBJ adalah sebagai berikut:<br>1. Tersedianya data harga barang dan jasa sebagai ancar-ancar untuk keperluan<br>perencanaan di lingkungan BPS Provinsi Aceh<br>2. Tersedianya Publikasi/Laporan Perkiraan Harga Barang dan Jasa BPS Provinsi Aceh</p>\n<p>&nbsp;</p>\n<p>3. Penerima Manfaat<br>Penerima manfaat dari Survei SHBJ meliputi pihak internal maupun eksternal. Bagi internal<br>BPS, hasil Survei SHBJ digunakan untuk keperluan perencanaan di lingkungan internal<br>BPS. Sedangkan bagi pihak eksternal seperti Pemerintah Daerah, hasil Survei SHBJ dapat<br>digunakan dengan persetujuan Kepala BPS Provinsi.</p>\n<p><br>4. Lingkup Kegiatan<br>Kegiatan SHBJ tahun&nbsp; meliputi 4 (empat) kegiatan pokok, yaitu:<br>1. Persiapan: pemutakhiran cakupan komoditas, pemutakhiran metodologi,<br>penyusunan kuesioner, pencetakan kuesioner (hanya dilakukan oleh BPS Provinsi).<br>2. Pelaksanaan: pencacahan lapangan, pengawasan, monitoring.<br>3. Pengolahan: entri, validasi, dan tabulasi.<br>4. Penyusunan publikasi</p>\n<p>&nbsp;</p>', 'NULL', '2025-07-26 10:13:08', '198504232008011001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('lzLII3EQhat', '2024s104', 'Survei Konstruksi Triwulanan', '2025', '2025s104', '<ol>\n<li>Cut Malahayati</li>\n<li>Fikri</li>\n</ol>', '<ul>\n<li>Survei &nbsp;Perusahaan &nbsp;Konstruksi Triwulanan &nbsp;2025 &nbsp;(SKTR-2025) &nbsp;bertujuan &nbsp;untuk mengetahui perkembangan sektor konstruksi secara umum dengan referensi waktu triwulanan. Karakteristik yang dikumpulkan meliputi jumlah dan balas jasa pekerja tetap dan kontrak; upah pekerja tidak tetap/harian; nilai pekerjaan konstruksi yang diselesaikan dalam periode triwulanan tahun 2025.</li>\n<li>&nbsp;Moda pendataan kegiatan &nbsp;Survei Perusahaan Konstruksi Triwulanan (SKTR-2025) menggunakan Computer-Assisted Personal Interviews&nbsp;<br>(CAPI).</li>\n<li>Monitoring Dashboard:&nbsp;<a title="Monitoring Dashboard" href="https://fasih-dashboard.bps.go.id/">https://fasih-dashboard.bps.go.id</a>&nbsp;</li>\n<li>Buku Pedoman Survei Konstruksi Triwulanan 2025: <a title="Buku Pedoman Survei Konstruksi Triwulanan 2025" href="https://drive.bps.go.id/apps/onlyoffice/s/42TYC3MqsMdFXy9?fileId=71470149">https://drive.bps.go.id/apps/onlyoffice/s/42TYC3MqsMdFXy9?fileId=71470149</a></li>\n<li>Daftar Sampel: <a title="Daftar Sampel" href="https://docs.google.com/spreadsheets/d/1GjhmnFoWqrLPgEbxoQASrSrWwKNY_qhoE7kBveKIWug/edit?gid=1339402030#gid=1339402030">https://docs.google.com/spreadsheets/d/1GjhmnFoWqrLPgEbxoQASrSrWwKNY_qhoE7kBveKIWug/edit?gid=1339402030#gid=1339402030</a></li>\n<li>Dokumen Survei Konstruksi Triwulanan 2025: <a title="Dokumen Survei Konstruksi Triwulanan 2025" href="https://drive.bps.go.id/s/42TYC3MqsMdFXy9">https://drive.bps.go.id/s/42TYC3MqsMdFXy9</a></li>\n</ul>', 'NULL', '2025-02-05 11:57:50', '198804162008011001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('M4ZvGtzOgKy', '2024s105', 'Pelaksanaan Kegiatan Updating Direktori Pariwisata', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Effendy</p>\n<p>Anggota&nbsp; &nbsp; : Cut Sandra&nbsp;</p>', '<p>Link Dashboard: https://fasih-sm.bps.go.id/survey-collection/collect/57f07399-6cb6-42b4-b05a-bd925cdb1193</p>', '<table style="width: 473.984px; border-collapse: collapse; border-width: 0px;" border="1">\n<tbody>\n<tr>\n<td style="border-width: 0px;">Pencacahan Hotel</td>\n<td style="border-width: 0px;">&nbsp; Januari - Februari 2024</td>\n</tr>\n<tr>\n<td style="border-width: 0px;">Pencacahan Lainnya</td>\n<td style="border-width: 0px;">&nbsp; Januari - Maret 2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-21 3:49:37', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('M88A3EyO1qR', '2024s101', 'Penyiapan ruangan dan Penyediaan Mobiler pendukung Kegiatan', '2024', '2024s101', '<p>PJK : Fadlun Andrian</p>\n\n<p>anggota :</p>\n\n<ul>\n	<li>Iswahyudi</li>\n	<li>tim Outshorshing</li>\n</ul>', '<p>Penyediaan perlengkapan BMN Kegiatan ( meja , Kursi,&nbsp;jaringan pendukung )</p>', '<table border="1" cellpadding="1" cellspacing="1" style="width: 500px;">\n	<tbody>\n		<tr>\n			<td>\n			<p>KEGIATAN :</p>\n			</td>\n			<td>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;JADWAL&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</td>\n		</tr>\n		<tr>\n			<td>\n			<p>Realese&nbsp;Rutin</p>\n			</td>\n			<td>&nbsp;Setiap awal bulan</td>\n		</tr>\n	</tbody>\n</table>\n\n<p>&nbsp;</p>', '2024-01-23 10:57:15', '198604092011011016', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('mb47vZ0HfIY', '2024s102', 'Profiling SBR (Statistical Business Register)', '2025', '2025s105', '<ol>\n<li>\n<p><strong>Ketua Tim</strong>: Fitral Pratomo</p>\n<p><strong>Pjk</strong>: Kahar Muzakar</p>\n<p><strong>Anggota</strong>:&nbsp;</p>\n<ul>\n<li>Wira Junardi</li>\n</ul>\n</li>\n</ol>', '<p>Profiling merupakan mekanisme untuk melakukan&nbsp;pemutakhiran perusahaan yang terdapat pada&nbsp;database SBR secara <em>on desk</em>. Sumber data yang&nbsp;digunakan bisa dari googling ataupun usaha/perusahaan yang pernah menjadi sampel survey&nbsp;BPS. Kegiatan profiling terdiri dari:</p>\n<ol>\n<li>Profiling Periodik\n<ul>\n<li>Sampel dialokasikan oleh Tim SBR Pusat</li>\n<li>Periode profiling ditentukan oleh Tim SBR Pusat</li>\n<li>Approval dilakukan oleh Tim&nbsp;SBR Pusat</li>\n</ul>\n</li>\n<li>Profiling Mandiri\n<ul>\n<li>Tim SBR BPS Provinsi atau&nbsp;Kabupaten/Kota dapat&nbsp;memilih sampel yang akan&nbsp;diprofiling</li>\n<li>Tim SBR BPS Provinsi atau&nbsp;Kabupaten/Kota dapat&nbsp;melakukan profiling kapan saja</li>\n<li>Approval dilakukan oleh Tim&nbsp;SBR Pusat</li>\n</ul>\n</li>\n</ol>', 'NULL', '2025-02-18 9:14:07', '198906132012111001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('mDNEVRgheEd', '2024s105', 'Survei Harga Perdesaan (SHPed)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Mursalina</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>', '<p>Link Dashboard: <a href="https://webentry.bps.go.id/shped" target="_blank" rel="noopener">https://webentry.bps.go.id/shped</a></p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;Januari - Desember&nbsp;2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-05 11:18:25', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
