xt .5pt; mso-border-left-alt: solid windowtext .5pt; mso-border-alt: solid windowtext .5pt; padding: 0in 5.4pt 0in 5.4pt; height: 28.35pt;" valign="top" width="178">\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: 115%;"><span style="font-family: \'Bookman Old Style\',serif; mso-fareast-font-family: Arial; mso-bidi-font-family: Arial; mso-ansi-language: EN-US;">199905312021041001</span></p>\n</td>\n<td style="width: 96.75pt; border-top: none; border-left: none; border-bottom: solid windowtext 1.0pt; border-right: solid windowtext 1.0pt; mso-border-top-alt: solid windowtext .5pt; mso-border-left-alt: solid windowtext .5pt; mso-border-alt: solid windowtext .5pt; padding: 0in 5.4pt 0in 5.4pt; height: 28.35pt;" valign="top" width="129">\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: 115%;"><span style="font-family: \'Bookman Old Style\',serif; mso-fareast-font-family: Arial; mso-bidi-font-family: Arial; mso-ansi-language: EN-US;">Analis SDM Aparatur Ahli Pertama</span></p>\n</td>\n<td style="width: 77.15pt; border-top: none; border-left: none; border-bottom: solid windowtext 1.0pt; border-right: solid windowtext 1.0pt; mso-border-top-alt: solid windowtext .5pt; mso-border-left-alt: solid windowtext .5pt; mso-border-alt: solid windowtext .5pt; padding: 0in 5.4pt 0in 5.4pt; height: 28.35pt;" valign="top" width="103">\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: 115%;"><span style="font-family: \'Bookman Old Style\',serif; mso-fareast-font-family: Arial; mso-bidi-font-family: Arial; color: black; mso-themecolor: text1; mso-ansi-language: EN-US;">Anggota</span></p>\n</td>\n</tr>\n<tr style="mso-yfti-irow: 9; height: 28.35pt;">\n<td style="width: 29.5pt; border: solid windowtext 1.0pt; border-top: none; mso-border-top-alt: solid windowtext .5pt; mso-border-alt: solid windowtext .5pt; padding: 0in 5.4pt 0in 5.4pt; height: 28.35pt;" valign="top" width="39">\n<p class="MsoListParagraph" style="mso-add-space: auto; text-indent: -16.5pt; line-height: 115%; mso-list: l0 level1 lfo1; margin: 0in 0in .0001pt 16.5pt;"><!-- [if !supportLists]--><span lang="IN" style="font-family: \'Bookman Old Style\',serif; mso-fareast-font-family: \'Bookman Old Style\'; mso-bidi-font-family: \'Bookman Old Style\'; color: black; mso-themecolor: text1;"><span style="mso-list: Ignore;">8.<span style="font: 7.0pt \'Times New Roman\';">&nbsp;&nbsp; </span></span></span><!--[endif]--><span lang="IN" style="font-family: \'Bookman Old Style\',serif; mso-fareast-font-family: Arial; mso-bidi-font-family: Arial; color: black; mso-themecolor: text1;">&nbsp;</span></p>\n</td>\n<td style="width: 141.25pt; border-top: none; border-left: none; border-bottom: solid windowtext 1.0pt; border-right: solid windowtext 1.0pt; mso-border-top-alt: solid windowtext .5pt; mso-border-left-alt: solid windowtext .5pt; mso-border-alt: solid windowtext .5pt; padding: 0in 5.4pt 0in 5.4pt; height: 28.35pt;" valign="top" width="188">\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: 115%;"><span style="font-family: \'Bookman Old Style\',serif; mso-fareast-font-family: Arial; mso-bidi-font-family: Arial;', '<p>Pojok Statistik merupakan layanan&nbsp;<strong><span data-asw-org-font-size="16">kolaborasi</span></strong> antara Badan Pusat Statistik dan Perguruan Tinggi. Kegiatan ini merupakan salah satu bentuk kepedulian BPS dalam penyebarluasan ragam dan manfaat produk statistik yang dihasilkan oleh BPS di lingkungan Perguruan Tinggi. Melalui Pojok Statistik, diharapkan literasi dan pemanfaatan statistik di lingkungan Perguruan Tinggi meningkat.</p>\n<p>Saat ini di Provinsi Aceh ada tiga Pojok Statistik, yaitu:</p>\n<ol>\n<li>&nbsp;Pojok Statistik Universitas Syiah Kuala, Banda Aceh (USK)</li>\n<li>&nbsp;Pojok Statistik Universitas Islam Negeri (UIN) Ar- Raniry, Banda Aceh (UINAR)</li>\n<li>&nbsp;Pojok Statistik Universitas Almuslim, Bireuen (Umuslim)</li>\n</ol>\n<p>BPS Provinsi Aceh membina dua Pojok Statistik, yaitu Pojok Statistik USK dan UINAR.</p>\n<p>BPS Kabupaten Bireuen membina Pojok Statistik Umuslim.</p>\n<p>Selain dalam bentuk fisik, tersedia juga Pojok Statistik Virtual yang dapat diakses melalui <a href="https://pojokstatistik.bps.go.id/">https://pojokstatistik.bps.go.id/</a>&nbsp;</p>', '<p>Aktivitas Pojok Statistik Tahun 2025:</p>\n<ol>\n<li>&nbsp;Internalisasi Pojok Statistik pada 11 Februari 2025</li>\n<li>&nbsp;Refreshing Pojok Statistik Virtual pada 13 Maret 2025</li>\n<li>&nbsp;Pembinaan Teknis Pojok Statistik (Optimalisasi Pojok Statistik: Strategi Promosi Berbasis Konten Kreatif) pada 23-24 April 2025</li>\n<li>&nbsp;Internalisasi Monitoring dan Evaluasi Pojok Statistik pada 17 Juni 2025</li>\n</ol>', '2025-10-06 10:33:08', '198607312009022006', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('PuKClBkRdaA', '2024s103', 'Survey Angkatan Kerja Nasional (SAKERNAS) 2025', '2025', '2025s102', '<p><strong>Ketua </strong>Tim: Abd.Hakim<br><strong>PJK</strong>:Juliana &nbsp; &nbsp;<br><strong>Anggota</strong>: Naura,M.Ridha,Darwis,Alfi,Ismaturahmi,Maulidya</p>', '<p>Survei Angkatan Kerja Nasional (Sakernas) merupakan survei yang dirancang&nbsp;khusus untuk mengumpulkan data ketenagakerjaan secara berkesinambungan. Data dan&nbsp;indikator ketenagakerjaan hasil Sakernas sangat penting bagi kelangsungan pembangunan&nbsp;dan dipergunakan secara luas untuk perencanaan, monitoring, dan evaluasi program&nbsp;pembangunan pemerintah khususnya bidang ketenagakerjaan di berbagai sektor. Dari&nbsp;Sakernas diperoleh estimasi data dan indikator pokok ketenagakerjaan seperti jumlah&nbsp;penduduk bekerja, jumlah pengangguran, TPT, TPAK, dan lain-lain di tingkat nasional,&nbsp;provinsi, dan kabupaten/kota. Beberapa indikator ketenagakerjaan hasil Sakernas juga dapat&nbsp;digunakan untuk keperluan pemantauan indikator SDGs dan RPJMN.</p>\n<p><strong>Dokumentasi Kegiatan</strong> : <a href="https://drive.google.com/drive/u/3/folders/1O52XUv1lMI7T7nh0qA_Y1SdW0k4uSfxE">https://drive.google.com/drive/u/3/folders/1O52XUv1lMI7T7nh0qA_Y1SdW0k4uSfxE</a>&nbsp;</p>\n<p><strong>Dasboard Monitoring (Hanya dapat diakses oleh akun yang terdaftar)</strong>&nbsp;:&nbsp;<a href="https://fasih-dashboard.bps.go.id/login/">https://fasih-dashboard.bps.go.id</a></p>\n<p><strong>Dashboard Evaluasi (Hanya dapat diakses oleh akun yang terdaftar)</strong>:&nbsp;<a href="https://fasih-sm.bps.go.id/">https://fasih-sm.bps.go.id</a>&nbsp;</p>', '<table dir="ltr" border="1" cellspacing="0" cellpadding="0" data-sheets-root="1" data-sheets-baot="1"><colgroup><col width="250"><col width="200"><col width="97"><col width="100"></colgroup>\n<tbody>\n<tr>\n<td colspan="1" rowspan="4">\n<div>SAKERNAS</div>\n</td>\n<td>Sakernas Februari</td>\n<td>8 Feb 2025</td>\n<td>28 Feb 2025</td>\n</tr>\n<tr>\n<td>Sakernas Mei</td>\n<td>8 May 2025</td>\n<td>30 May 2025</td>\n</tr>\n<tr>\n<td>Sakernas Agustus</td>\n<td>8 Aug 2025</td>\n<td>31 Aug 2025</td>\n</tr>\n<tr>\n<td>Sakernas November</td>\n<td>8 Nov 2025</td>\n<td>30 Nov 2025</td>\n</tr>\n</tbody>\n</table>', '2025-07-26 15:20:15', '198109132006021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('PytrDfKD2Ps', '2024s104', 'Updating Direktori Perusahaan Non Migas', '2024', '2024s104', '<p style="line-height: 1.1;"><strong>Cut Malahayati</strong></p>\n<p style="line-height: 1.1;">Fikri</p>\n<p style="line-height: 1.1;">Nova Misrina</p>\n<div dir="ltr" aria-hidden="true">\n<div class="input-box" spellcheck="false">\n<div class="cell-input editable" dir="ltr" style="line-height: 1.1;" tabindex="0" role="combobox" contenteditable="true" aria-autocomplete="list" aria-label="C32">Ridha Mutia</div>\n</div>\n</div>\n<div aria-hidden="true">&nbsp;</div>\n<p>&nbsp;</p>', '<p>Periode <em>Updating</em> Direktori Perusahaan Non Migas adalah <strong>Tahunan&nbsp;</strong>dengan <strong><em>Output&nbsp;</em></strong>Daftar Direktori Perusahaan Non Migas</p>', '<p><em>on progess</em></p>', '2024-02-21 9:29:55', '198607292009022005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('Q6eWXPVvBQv', '2024s101', 'Ujian Kompetensi Pejabat Fungsional', '2024', '2024s101', '<p>Muhammad Hafidz Al Ahmad Bit, S.Tr.Stat.</p>\n<p>Wahdini, S.Psi.</p>\n<p>Cut Emalita, SE.</p>\n<p>Ika Virnaristanti, S.Si.,M.Si</p>', '<p>Pendaftaran hingga pelaksanaan ukom.</p>', '<p>Jadwal Statistisi dan Prakom : Februari, Juni, Oktober</p>\n<p>JF Lainnya : Tentatif</p>', '2024-03-21 11:19:46', '199905312021041001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
