	('qAacBwq6bpA', '2024s104', 'Laporan Pemotongan Ternak Bulanan (LPTB)', '2024', '2024s104', '<p style="line-height: 1.4;">Nilam Humaira</p>\n<p style="line-height: 1.4;">Raiski Ramdhoni<br>Teti Safrida Purba</p>', '<ul>\n<li>Kegiatan LPTB menggunakan moda CAPI dengan aplikasi FASIH</li>\n<li>Link Monitoring :&nbsp;<a href="https://dashboard.bps.go.id/simental2024/">https://dashboard.bps.go.id/simental2024/</a></li>\n<li style="line-height: 1.5;">Pengelolaan Survei <a href="https://fasih-sm.bps.go.id/">https://fasih-sm.bps.go.id/</a>&nbsp;</li>\n</ul>', '<p><img src="data:image/png;base64,', '2024-02-20 12:24:02', '198607292009022005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
