	('qboHHYHR8Au', '2024s104', 'Survei Industri Besar dan Sedang (IBS) Bulanan', '2024', '2024s104', '<p><strong>Melly</strong></p>\n<p>Rodiah</p>', '<ul>\n<li>Link Dashboard: <a href="https://webentry.bps.go.id/ibs">https://webentry.bps.go.id/ibs</a></li>\n<li>Materi Briefing SIBS Bulanan 2024: &nbsp;<a href="http://s.bps.go.id/briefsibsbulanan">http://s.bps.go.id/briefsibsbulanan</a>&nbsp;</li>\n<li>Alokasi sampel 2024:&nbsp;<a href="http://s.bps.go.id/AlokasiSampel_IBSBulanan_2024">http://s.bps.go.id/AlokasiSampel_IBSBulanan_2024</a></li>\n<li class="MsoNormal">Penanggung Jawab Kabkota: <a href="http://s.bps.go.id/Email_AdminFasih_Bulanan2024">http://s.bps.go.id/Email_AdminFasih_Bulanan2024</a></li>\n</ul>\n<p class="MsoNormal" style="margin-bottom: .0001pt;">&nbsp;</p>', '<p><strong>Pencacahan</strong>: Januari - Desember 2024</p>', '2024-02-15 11:13:41', '198604222009022005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('qeSJw1xk1Wp', '2024s101', 'Pemenuhan Permintaan Narasumber, Anggota Tim dalam Kegiatan Statistik K/L/D/I', '2024', '2024s108', '<p>Ketua :&nbsp;<strong>Yan Yan Gustiana</strong></p>\n<p>Anggota :</p>\n<p>Maulizasari</p>\n<div class="hc-details hc-details-open-top">\n<div id="hover_340058828">Mazaya Alifah Syadzwina</div>\n<div>Rodiah</div>\n</div>\n<p>Wahdini</p>\n<p>Reza Rezki Pulungan</p>\n<p>Edo Mara Nasution</p>\n<p>Hendra Gunawan</p>', '<p>.</p>', '<p>.</p>', '2024-02-22 12:57:53', '199509142019032002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('qFz5NyB7ix5', '2024s105', 'Penyusunan BRS Inflasi, NTP, Pariwisata, Transportasi dan Ekspor Impor', '2025', '2025s103', '<p>Tim Hadija</p>\n<p>&nbsp;</p>', '<p>BRS rutin setiap bulan yang berisi informasi terkait perubahan harga, nilai tukar petani, jumlah wisatawan, tingkat penghunian kamar hotel, keadaan transportasi dan ekspor impor.</p>', 'NULL', '2025-03-06 8:40:57', '198410312008011005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
