	('QZCL27h5NdX', '2024s104', 'Survei Perusahaan Non Migas', '2024', '2024s104', '<p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: 1.5;"><strong><span style="font-size: 10.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-fareast-language: EN-ID;">Cut Malahayati (PJK)</span></strong></p>\n<p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: 1.5;"><span style="font-size: 10.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-fareast-language: EN-ID;">Fikri</span></p>\n<p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: 1.5;"><span style="font-size: 10.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-fareast-language: EN-ID;">Nova Misrina</span></p>\n<p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: 1.5;"><span style="font-size: 10.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-fareast-language: EN-ID;">Ridha Mutia</span></p>', '<p>Periode Survei Perusahaan Non Migas adalah <strong>Tahunan</strong> dengan<strong><em> Output</em>&nbsp;</strong>Data Produksi, Nilai, Jlh Tenaga Kerja, Balas Jasa.</p>', '<p><em>on progress</em></p>', '2024-02-21 9:12:07', '198607292009022005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('r45WyEDsj1x', '2024s105', 'Survei Kesejahteraan Petani (SKP)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Mursalina</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>', '<p>Link:</p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pelatihan&nbsp;</td>\n<td>&nbsp;Mei 2024</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;Juni 2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-05 11:22:18', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('RgcRLwR8Dqh', '2024s106', 'Survei Khusus Triwulan Neraca Produksi (SKTNP)', '2024', '2024s106', '<p><strong>Ketua Tim:</strong> Meita Jumiartanti</p>\n<ul>\n<li><strong>PIC SKTNP:</strong> Fitri Mulyani</li>\n<li><strong>Anggota:</strong> Ridha Mutia, Azwar&nbsp;</li>\n</ul>', '<p><strong>Tujuan Survei</strong></p>\n<p style="text-align: justify;"><em>Survei ini bertujuan untuk memperoleh informasi terkini dan tercepat mengenai perkembangan indikator produksi, tenaga kerja, indikator harga dan pendapatan/output yang akan digunakan dalam&nbsp;penyusunan PDB/PDRB triwulanan lapangan usaha barang dan jasa. Kegiatan usaha yang menjadi fokus SKTNP 2024 adalah kegiatan usaha yang belum memiliki indikator produksi yang rutin dalam penyusunan PDB/PDRB triwulanan. Indikator produksi tersebut akan diperoleh dengan cara melihat perkembangan perusahaan/usaha. Perusahaan/usaha yang terpilih menjadi sampel akan disurvei selama <strong>empat kali </strong>periode pencacahan dalam satu tahun kegiatan.</em></p>\n<p>&nbsp;</p>\n<p><strong>Dokumentasi Kegiatan</strong></p>\n<p><a href="s.bps.go.id/KAK-SKDNP">s.bps.go.id/KAK-SKDNP</a></p>\n<p style="line-height: 1;"><strong>Link Bahan Ajar</strong></p>\n<p><a href="s.bps.go.id/BahanPelatihanSKDNP24">s.bps.go.id/BahanPelatihanSKDNP24</a></p>\n<p><strong>QnA Pelatihan Inda</strong></p>\n<p><a href="http://s.bps.go.id/QnA-Pelatihan-Inda" target="_blank" rel="noopener">s.bps.go.id/QnA-Pelatihan-Inda</a> &nbsp;</p>', '<p><span style="font-size: 12pt;"><strong>Pelaksanaan Lapangan (Pengumpulan &amp; Pengawasan)&nbsp;</strong></span></p>\n<ul>\n<li style="font-style: italic;"><em><strong>Data Triwulan IV 2023 &gt;&gt; </strong>Januari 2024</em></li>\n<li style="font-style: italic;"><em><strong>Data Triwulan I 2024&nbsp; &nbsp;&gt;&gt; </strong>April 2024</em></li>\n<li style="font-style: italic;"><em><strong>Data Triwulan II 2024&nbsp; &gt;&gt; </strong>Juli 2024</em></li>\n<li style="font-style: italic;"><em><strong>Data Triwulan III 2024 &gt;&gt; </strong>Oktober 2024</em></li>\n</ul>', '2024-02-20 12:42:33', '199503172018022001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('rIYNWnH6SXI', '2024s106', 'Survei Neraca Terintegrasi (SINASI)', '2024', '2024s106', '<p><strong>Ketua Tim:</strong>&nbsp;Meita Jumiartanti</p>\n<ul>\n<li><strong>PIC SINASI:</strong>&nbsp;Fitri Mulyani</li>\n<li><strong>Anggota:</strong> Ridha Mutia, Azwar</li>\n</ul>', '<p><strong>Tujuan Survei</strong></p>\n<p style="text-align: justify;"><em>Survei Neraca Terintegrasi pada tahun 2024 ini bertujuan untuk </em><em>memperoleh informasi terbaru mengenai parameter yang akan digunakan </em><em>dalam penyusunan PDB, SUT, dan Tabel I-O. Tujuan dari survei ini adalah </em><em>memperoleh data dan informasi yang akan digunakan untuk penyusunan </em><em>matriks margin perdagangan dan pengangkutan (Trade and Transport Margin/TTM), struktur pendapatan, serta struktur pengeluaran </em><em>usaha/perusahaan.&nbsp;</em></p>\n<p style="text-align: justify;">&nbsp;</p>\n<p><strong>Dokumentasi Kegiatan</strong></p>\n<p><a href="s.bps.go.id/KAK-SKDNP">s.bps.go.id/KAK-SKDNP</a></p>\n<p><strong>Link Bahan Ajar</strong></p>\n<p><a href="s.bps.go.id/BahanPelatihanSKDNP24">s.bps.go.id/BahanPelatihanSKDNP24</a></p>\n<p><strong>QnA Pelatihan Inda</strong></p>\n<p><a href="http://s.bps.go.id/QnA-Pelatihan-Inda" target="_blank" rel="noopener">s.bps.go.id/QnA-Pelatihan-Inda</a> &nbsp;</p>', '<p><strong>Pelatihan Petugas &gt;&gt;</strong> 3-7 Maret 2024</p>\n<p><strong>Pendataan Lapangan &gt;&gt;</strong> Mei-Oktober 2024</p>', '2024-02-19 9:49:01', '199503172018022001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('roWEJTMB2mG', '2024s103', 'Survei Nasional Literasi dan Inklusi Keuangan (SNLIK) 2024', '2024', '2024s102', '<p>PJK: Zelvia</p>\n<p>Anggota: Maulidya; Darwis; Juliana</p>', '<p>Buku Pedoman dll: <a href="https://linktr.ee/snlik24" target="_blank" rel="noopener">https://linktr.ee/snlik24&nbsp;</a></p>\n<p>Dokumentasi Pelaksanaan : <a href="http://s.bps.go.id/dokumentasi_snlik24">http://s.bps.go.id/dokumentasi_snlik24</a>&nbsp;</p>\n<p>Alokasi Petugas&nbsp; : <a href="https://drive.google.com/drive/u/6/folders/1dqlyOTKq3xGfBPz6CtW91uJaPLS_GL_I">https://drive.google.com/drive/u/6/folders/1dqlyOTKq3xGfBPz6CtW91uJaPLS_GL_I</a>&nbsp;</p>\n<p>Alokasi DSBS : <a href="https://drive.google.com/drive/u/6/folders/1dqlyOTKq3xGfBPz6CtW91uJaPLS_GL_I">https://drive.google.com/drive/u/6/folders/1dqlyOTKq3xGfBPz6CtW91uJaPLS_GL_I</a>&nbsp;</p>', '<table style="border-collapse: collapse; width: 100.031%; border-width: 0px;" border="1"><colgroup><col style="width: 50.0403%;"><col style="width: 50.0403%;"></colgroup>\n<tbody>\n<tr>\n<td class="xl65" style="height: 15.75pt; width: 363pt; border-width: 0px;" width="484" height="21">Briefing Petugas</td>\n<td class="xl67" style="width: 308pt; border-width: 0px;" width="410">8 Jan 2024</td>\n</tr>\n<tr>\n<td class="xl65" style="height: 15.75pt; border-width: 0px; border-top-style: none; border-top-color: initial;" height="21">Pemutakhiran Rumah Tangga</td>\n<td class="xl66" style="border-width: 0px; border-top-style: none; border-top-color: initial;">9-16 Jan 2024</td>\n</tr>\n<tr>\n<td class="xl65" style="height: 15.75pt; border-width: 0px; border-top-style: none; border-top-color: initial;" height="21">Pencacahan Lapangan</td>\n<td class="xl66" style="border-width: 0px; border-top-style: none; border-top-color: initial;">17 Jan -5 Feb 2024</td>\n</tr>\n<tr>\n<td class="xl65" style="height: 12.5pt; border-width: 0px; border-top-style: none; border-top-color: initial;" height="17">Supervisi Pemutakhiran dan Pencacahan</td>\n<td class="xl66" style="border-width: 0px; border-top-style: none; border-top-color: initial;">9 Jan -5 Feb 2024</td>\n</tr>\n</tbody>\n</table>', '2024-03-18 9:44:26', '198109132006021001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('RS3X5lwY7Wu', '2024s106', 'Survei Khusus Lembaga Non Profit Melayani Rumah Tangga (SKLNPRT) Triwulanan', '2025', '2025s106', '<p>PJK :</p>\n<p>Mazaya Alifah Syadzwina, S.Tr.Stat</p>', '<p>Lembaga Non Profit yang melayani rummahtangga yang semula merupakan satu institusi dengan rumahtangga, pada saat ini dinyatakan sebagai institusi yang berdiri sendiri sebagai salah satu pelaku ekonomi. Tidak berbeda jauh dengan konsumsi rumahtangga, peranan ekonomi konsumsi lembaga non profit yang melayani rumahtangga (LNPRT) juga dibutuhkan bagi pembentukan PDB disisi penggunaan. Pola konsumsi Lembaga Non Profit yang melayani rumahtangga triwulanan diperoleh melalui Survei Khusus Lembaga Non Profit Triwulanan (SKLNPT). Pola konsumsi tersebut digunakan untuk menyusun komponen PDB dari sisi penggunaan triwulanan.</p>', 'NULL', '2025-07-24 11:13:59', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('rV49e1YVn7H', '2024s105', 'Survei Harga Produsen Beras di Penggilingan (HPBG)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Mursalina</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>', '<p>Link Dashboard:&nbsp;<a title="https://webentry.bps.go.id/shp/" href="https://webentry.bps.go.id/shp/" target="_blank" rel="noopener">https://webentry.bps.go.id/shp/</a></p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pelatihan Innas dan Petugas</td>\n<td>&nbsp;Januari 2024</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;Januari - Desember&nbsp;2024</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>', '2024-02-05 11:04:18', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('rwRxbjyTGQC', '2024s102', 'Pemetaan Wilkerstat', '2024', '2024s105', '<ol>\n<li>\n<p><strong>Ketua Tim</strong>: Fitral Pratomo</p>\n<p><strong>Pjk</strong>: Wira Junardi</p>\n<p><strong>Anggota</strong>:&nbsp;</p>\n<ul>\n<li>Ichsan Hasanudin</li>\n<li>Anandika Dian Pramesti</li>\n</ul>\n</li>\n</ol>', '<ul>\n<li>Pemetaan Wilayah Kerja Statistik (Wilkerstat) dilakukan untuk mengupdate peta sesuai dengan perubahan master wilkerstat (MFD)</li>\n<li>Pengelolaan peta digital dilakukan melalui aplikasi&nbsp;<em><strong><a href="https://dataspasial.bps.go.id/gs/" target="_blank" rel="noopener">dataspasial.bps.go.id/gs</a></strong></em></li>\n<li>Aplikasi manajemen data geotagging kegiatan sensus/survei <em><strong><a href="https://wilkerstat.bps.go.id/" target="_blank" rel="noopener">wilkerstat.bps.go.id</a></strong></em></li>\n</ul>', '<ul>\n<li>Perbaikan peta BS unmatch Master 2023 Semester 1 : Februari 2024</li>\n<li>Pemutakhiran peta SLS hasil kegiatan EA : Juli - Agustus 2024</li>\n</ul>', '2024-02-21 11:20:45', '198906132012111001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('rwyu7NDzata', '2024s102', 'SQL Lab', '2024', '2024s105', '<p>Ketua tim : Fitral</p>\n<p>Pjk : Kahar</p>', '<p>-</p>', '<p>-</p>', '2024-08-20 14:01:41', '199501232018021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('RZM8Hghz6gh', '2024s102', 'Web Sipadu', '2025', '2025s105', '<p><strong>Project Leader</strong>&nbsp;: Fitral</p>\n<p><strong>Developer</strong> : Fitral, Ichsan, Adrian, Zahlul, Farhan</p>', '<p>Sistem Informasi Pelayanan Terpadu (SIPADU) merupakan aplikasi yang digunakan untuk menunjang kegiatan sehari-hari BPS Provinsi Aceh seperti melakukan presensi, mengirimkan undangan kegiatan internal (seperti rapat atau pelatihan), booking ruangan zoom meeting, pembuatan nomor surat, pelaporan perjalanan&nbsp;dinas, dan lain sebagainya.</p>', 'NULL', '2025-06-03 7:46:09', '200101292023021004', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('SBRhaaogx8V', '2024s105', 'Penyusunan BRS Statistik Distribusi', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : Hani\'ah</p>\n<p>Anggota&nbsp; &nbsp; : Akhmad Sugito&nbsp;</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ferfi Hamdina&nbsp;</p>', '<table dir="ltr" border="1" cellspacing="0" cellpadding="0" data-sheets-root="1"><colgroup><col width="47"><col width="509"><col width="127"><col width="100"></colgroup>\n<tbody>\n<tr>\n<td style="text-align: center;" data-sheets-value="{"><strong>No.</strong></td>\n<td style="text-align: center;" data-sheets-value="{"><strong>Berita Resmi Statistik (BRS)</strong></td>\n<td style="text-align: center;" data-sheets-value="{"><strong>Penyusun</strong></td>\n<td style="text-align: center;" data-sheets-value="{"><strong>Pemeriksaan</strong></td>\n</tr>\n<tr>\n<td style="text-align: center;" data-sheets-value="{">1.</td>\n<td style="text-align: left;" data-sheets-value="{">Perkembangan Tranportasi</td>\n<td style="text-align: center;" data-sheets-value="{">Akhmad Sugito</td>\n<td style="text-align: center;" data-sheets-value="{">Hani\'ah</td>\n</tr>\n<tr>\n<td style="text-align: center;" data-sheets-value="{">2.</td>\n<td style="text-align: left;" data-sheets-value="{">Perkembangan Ekspor dan Impor Aceh</td>\n<td style="text-align: center;" data-sheets-value="{">Hani\'ah</td>\n<td style="text-align: center;" data-sheets-value="{">Titiek Zurryati</td>\n</tr>\n</tbody>\n</table>', '<table dir="ltr" style="width: 52.5117%; height: 67.1718px;" border="1" cellspacing="0" cellpadding="0" data-sheets-root="1"><colgroup><col style="width: 7.15198%;" width="47"><col style="width: 66.9358%;" width="509"><col style="width: 25.9122%;" width="100"></colgroup>\n<tbody>\n<tr style="height: 22.3906px;">\n<td style="text-align: center; height: 22.3906px;" data-sheets-value="{"><strong>No.</strong></td>\n<td style="text-align: center; height: 22.3906px;" data-sheets-value="{"><strong>Berita Resmi Statistik (BRS)</strong></td>\n<td style="text-align: center; height: 22.3906px;" data-sheets-value="{"><strong>Jadwal Rilis</strong></td>\n</tr>\n<tr style="height: 22.3906px;">\n<td style="text-align: center; height: 22.3906px;" data-sheets-value="{">1.</td>\n<td style="text-align: left; height: 22.3906px;" data-sheets-value="{">Perkembangan Tranportasi</td>\n<td style="text-align: center; height: 22.3906px;" data-sheets-value="{">Setiap Awal Bulan</td>\n</tr>\n<tr style="height: 22.3906px;">\n<td style="text-align: center; height: 22.3906px;" data-sheets-value="{">2.</td>\n<td style="text-align: left; height: 22.3906px;" data-sheets-value="{">Perkembangan Ekspor dan Impor Aceh</td>\n<td style="text-align: center; height: 22.3906px;" data-sheets-value="{">Setiap Bulan tanggal 15</td>\n</tr>\n</tbody>\n</table>', '2024-02-21 3:41:26', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('SHvpCKHL1fy', '2024s104', 'Survei Industri Besar dan Sedang (IBS) Tahunan', '2025', '2025s104', '<p>Pjk: Melly</p>', '<ul>\n<li>Survei Industri Besar dan Sedang (IBS) Tahunan 2025&nbsp; atau disebut <strong>Survei Tahunan Perusahaan Industri Manufaktur (STPIM)</strong> mencakup perusahaan industri manufaktur skala menengah dan besar yang terpilih menjadi sampel di seluruh kabupaten/kota. Pada tahun 2025 sampel Provinsi Aceh terpilih sebanyak 99 sampel perusahaan.</li>\n<li><!--[endif]--><span lang="EN-US" style="font-size: 11.0pt; line-height: 115%; font-family: \'Arial\',sans-serif;">Pencacahan STPIM Tahun 2025 menggunakan moda CAPI (wawancara langsung oleh petugas) atau moda CAWI (pengisian mandiri secara online oleh perusahaan).</span></li>\n<li><span lang="EN-US" style="font-size: 11.0pt; line-height: 115%; font-family: \'Arial\',sans-serif;">Daftar sampel STPIM Tahun 2025 dapat diakses melalui tautan&nbsp;<span lang="EN-US" style="font-size: 11.0pt; line-height: 107%; font-family: \'Calibri\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: \'Times New Roman\'; mso-bidi-theme-font: minor-bidi; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;"><a title="http://s.bps.go.id/sampel_stpim2024" href="http://s.bps.go.id/sampel_stpim2024"><span style="font-family: \'Arial\',sans-serif;">http://s.bps.go.id/sampel_stpim2024</span></a></span></span></li>\n<li>Monitoring Dashboard:&nbsp;<a href="https://fasih-dashboard.bps.go.id">https://fasih-dashboard.bps.go.id</a>&nbsp;</li>\n<li>Manajemen Kegiatan Survei: <a href="https://fasih-sm.bps.go.id/">https://fasih-sm.bps.go.id/</a>&nbsp;</li>\n</ul>', 'NULL', '2025-07-25 17:34:38', '198604222009022005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('SMgcAZid4Cv', '2024s102', 'Statistical Business Register (SBR)', '2024', '2024s105', '<ol>\n<li>\n<p><strong>Ketua Tim</strong>: Fitral Pratomo</p>\n<p><strong>Pjk</strong>: Wira Junardi</p>\n<p><strong>Anggota</strong>:&nbsp;</p>\n<ul>\n<li>Munandar</li>\n</ul>\n</li>\n</ol>', '<p>Pemutakhiran database&nbsp;usaha/perusahaan&nbsp;untuk penyusunan kerangka induk&nbsp;survei ekonomi dan data statistik&nbsp;unit bisnis</p>', '<ul>\n<li>Pelatihan Instruktur Nasional : Agustus 2024</li>\n<li>Pelatihan Petugas Lapangan : Agustus 2024</li>\n<li>Pencacahan Lapangan : Agustus - September 2024</li>\n<li>Pengawasan Lapangan : Agustus - September 2024</li>\n</ul>', '2024-02-21 10:44:40', '198906132012111001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('sN5CqSZc3u1', '2024s104', 'Survei Statistik Pertanian Hortikultura (SPH)', '2024', '2024s104', '<p>Hendra Gunawan</p>\n<p>Nilam Humaira</p>', '<ul>\n<li>Pengumpulan data Komoditas Hortikultura Sayuran, Buah-Buahan, Tanaman Biofarmaka, dan Tanaman Hias.</li>\n<li>Untuk mendapatkan data luas/jumlah tanaman, produksi dan rata-rata harga di petani pada tingkat kecamatan.</li>\n<li>Pengolahan dan Monitoring dapat diakses pada alamat: <a href="https://pengolahan.bps.go.id/produksi/hortikultura/sph2021">https://pengolahan.bps.go.id/produksi/hortikultura/sph2021</a>&nbsp;</li>\n</ul>', '<ul>\n<li>Pengolahan dokumen SPH paling lambat tanggal 20 setelah periode laporan&nbsp;berakhir setiap bulannya.</li>\n</ul>', '2024-03-13 10:24:09', '198306042006021003', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('SSzViDQnobN', '2024s102', 'Pembinaan Statistik Sektoral (PSS)', '2024', '2024s109', '<p style="line-height: 1.5;"><strong>Ketua Tim</strong>: Wahyu Agung Sutikno<br><strong>Koordinator</strong>: M. Alimuddin<br><strong>Anggota</strong>: Nur Hasanah, Fikri</p>', '<ul>\n<li style="line-height: 1.5;"><strong>Materi Final Pelatihan Pembinaan Statistik Sektoral Tahap 1:&nbsp;</strong><a href="https://s.bps.go.id/pss1_mat">https://s.bps.go.id/pss1_mat</a></li>\n<li style="line-height: 1.5;"><strong>Pelatihan Pembinaan Statistik Sektoral Tahap 2:&nbsp;</strong><a href="http://s.bps.go.id/pss2">http://s.bps.go.id/pss2</a></li>\n<li style="line-height: 1.5;"><strong>Materi Terkait PSS dan Forum SDI: </strong><a href="https://s.bps.go.id/forumsdi">https://s.bps.go.id/forumsdi</a></li>\n<li style="line-height: 1.5;"><strong>Monitoring Rekapitulasi Dokumentasi Pembinaan Statistik Sektoral: </strong><a href="https://webapps.bps.go.id/rujukan/pembinaan/public/monev/rekap">https://webapps.bps.go.id/rujukan/pembinaan/public/monev/rekap</a></li>\n<li style="line-height: 1.5;"><strong>Daftar Indikatif Data Prioritas 2024 seluruh K/L:</strong> <a href="https://link.bappenas.go.id/DP24">https://link.bappenas.go.id/DP24</a></li>\n<li style="line-height: 1.5;"><strong>Dokumentasi Pembinaan Statistik Sektoral:</strong> <a href="https://s.bps.go.id/dok_pembinaan">https://s.bps.go.id/dok_pembinaan</a></li>\n<li style="line-height: 1.5;"><strong>Monitoring Pembinaan dan EPSS:</strong> <a href="http://s.bps.go.id/monitoring_EPSS24">http://s.bps.go.id/monitoring_EPSS24</a></li>\n<li style="line-height: 1.5;"><strong>Rencana Pembinaan Statistik Sektoral 2024: </strong><a href="https://drive.bps.go.id/s/nXMXraa4GmLwBea">https://drive.bps.go.id/s/nXMXraa4GmLwBea</a></li>\n<li style="line-height: 1.5;"><strong>Link JDIH BAPPENAS: </strong><a href="https://jdih.bappenas.go.id/home/viewhasilpencarian/10">https://jdih.bappenas.go.id/home/viewhasilpencarian/10</a></li>\n</ul>\n<p>&nbsp;</p>', '<p>&