	('sTUMc8AXUY7', '2024s105', 'Survei Harga Produsen (HP)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Mursalina</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>', '<p>Link Dashboard: <a href="https://webentry.bps.go.id/shp/" target="_blank" rel="noopener">https://webentry.bps.go.id/shp/</a></p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pelatihan Innas dan Petugas</td>\n<td>&nbsp;Januari 2024</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;Januari - Desember&nbsp;2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-05 10:41:31', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('sZrNXkRVcyq', '2024s101', 'Rapat kunjungan kerja kanwil DJPB Aceh di BPS Provinsi Aceh', '2024', '2024s101', '<p>Ketua : Tasdik Ilhamudin</p>\n<p>Anggota :&nbsp;</p>\n<p>Edo Mara Nasution</p>\n<p>Reza Rezki Pulungan</p>\n<p>Kanasha Humaira</p>\n<p>Meita Jumiartanti</p>\n<p>Rediansyah Arief</p>\n<p>Andi Arif Ginting</p>\n<p>Teti Safrida Purba</p>\n<p>Zukhra</p>\n<p>Bahzur Andria</p>\n<p>Nova Misrina</p>\n<p>Ferfi Hamdina</p>', '<p>Dalam rangka meningkatkan kualitas laporan keuangan dan pendampingan kepada UAPPA-W lingkup kanwil DJPb Provinsi Aceh, maka dilaksanakanlah FGD bersama pengelola keuangan BPS Provinsi Aceh terkait evaluasi perencanaan, pelaksanaan dan pelaporan keuangan tahun 2023 pada satker BPS Provinsi Aceh.</p>', '<p>20 Februari 2024</p>', '2024-02-21 8:00:15', '198306172005021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('tD6HSzKvZin', '2024s103', 'Statistik politik dan keamanan (Statpolkam) 2025', '2025', '2025s102', '<p><strong>Ketua </strong>Tim: Abd.Hakim<br><strong>PJK</strong>:M.Ridha &nbsp;&nbsp;<br><strong>Anggota</strong>: Darwis,Alfi,Juliana,Naura,Ismaturahmi,Maulidya</p>', '<p>Pelaksanaan kegiatan ini (STATPOLKAM) merupakan kegiatan pengumpulan data sekunder dari beberapa dinas dan instansi yang bertujuan untuk menyajikan gambaran tentang keadaan politik dan keamanan dengan melihat kondisi politik berdasarkan indikator Pegantian Antar Waktu (PAW).</p>\n<p>web entry : <a href="https://simonpolkam.web.bps.go.id">https://simonpolkam.web.bps.go.id</a>&nbsp;<br>pedoman dan kuesioner: &nbsp;<a href="https://s.bps.go.id/simonpolkam2025">https://s.bps.go.id/simonpolkam2025</a></p>\n<p>pertanyaan: <a href="https://git.bps.go.id/issue-olah/simonpolkam/-/issues">https://git.bps.go.id/issue-olah/simonpolkam/-/issues</a>&nbsp;</p>', '<p><strong>Pengumpulan data melalui aplikasi Simonpolkam</strong> : 1 Feb - 30 Agustus 2025</p>', '2025-07-26 22:11:41', '198109132006021001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('tIPbSgPwooD', '2024s105', 'Survei Lembaga Keuangan Koperasi Simpan Pinjam (KSP)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Effendy</p>\n<p>Anggota&nbsp; &nbsp; : Cut Sandra&nbsp;</p>', '<p>Link Dashboard:</p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp; Maret - Juli 2024</td>\n</tr>\n<tr>\n<td>Pengolahan</td>\n<td>&nbsp; September 2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-06 10:53:31', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('tncQFiDc0Iv', '2024s105', 'Survei Tambahan Paket Komoditas SPDT IHPB Tahun 2023', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Melly</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Cut Malahayati&nbsp; &nbsp;</p>', '<p>Link:&nbsp;</p>', '<table style="width: 473.984px;" border="1"><colgroup><col style="width: 236.484px;"><col style="width: 236.5px;"></colgroup>\n<tbody>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;Maret - Desember&nbsp;2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-05 10:15:49', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('TnXhi67Yzw6', '2024s106', 'Penyusunan Publikasi PDRB Menurut Lapangan Usaha Triwulan 4 Tahun 2024', '2025', '2025s106', '<p>PJK :</p>\n<p>Ridha Mutia, SE, M.Si</p>\n<p>Anggota:</p>\n<ol>\n<li>Maulizasari, S.Stat</li>\n<li>Fitri Mulyani, SST</li>\n</ol>', '<p>Penghitungan PDRB yang digunakan dalam publikasi ini ialah melalui&nbsp;pendekatan produksi yaitu menghitung nilai tambah barang dan jasa yang<br>dihasilkan seluruh unit produksi di wilayah Provinsi Aceh setiap triwulan. PDRB&nbsp;pendekatan produksi atau menurut lapangan usaha diperoleh dari selisih nilai<br>barang dan jasa yang dihasilkan dikurangi bahan baku yang digunakan sebagai&nbsp;input ditambah pajak atas produk dikurangi subsidi atas produk. Unit-unit<br>produksi tersebut dikelompokkan menjadi 17 kategori lapangan usaha, yaitu:<br>A. Pertanian, kehutanan, dan&nbsp;perikanan;<br>B. Pertambangan dan penggalian;<br>C. Industri pengolahan;<br>D. Pengadaan listrik dan gas;<br>E. Pengadaan Air;<br>F. Konstruksi;<br>G. Perdagangan besar dan eceran&nbsp;dan reparasi mobil dan sepeda&nbsp;motor;<br>H. Transportasi dan pergudangan;<br>I. Penyediaan akomodasi &amp; makan minum;<br>J. Informasi &amp; komunikasi;<br>K. Jasa keuangan;<br>L. Real estate;<br>M,N Jasa perusahaan;<br>O Administrasi pemerintahan,&nbsp;pertahanan, &amp; jaminan sosial&nbsp;wajib;<br>P Jasa pendidikan;<br>Q Jasa kesehatan &amp; kegiatan&nbsp;sosial;<br>R,S,T,U Jasa lainnya</p>', 'NULL', '2025-07-24 10:20:45', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('ToiXNCxBrEL', '2024s104', 'Survei Data Kehutanan Triwulanan (DKT)', '2024', '2024s104', '<p>Nilam Humaira</p>\n<p>Raiski Ramadhoni</p>\n<p>Teti Safrida Purba</p>', '<ul>\n<li>Kegiatan Survei DKT menggunakan moda CAPI dengan aplikasi FASIH</li>\n<li>Pengelolaan Survei : <a href="https://fasih-sm.bps.go.id/login">https://fasih-sm.bps.go.id/login</a>&nbsp;</li>\n</ul>', '<p><img src="data:image/png;base64,"></p>', '2024-02-20 12:23:09', '198607292009022005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('trxviTTkcQo', '2024s106', 'Survei Khusus Studi Penyusunan Perubahan Inventori (SKSPPI)', '2025', '2025s106', '<p>PJK:</p>\n<p>Cahya Danu Rahman, SST</p>\n<p>Anggota:</p>\n<p>Mazaya Alifah Syadzwina, S.Tr.Stat</p>', '<p><strong><span class="deskripsi-label">Penjelasan Umum</span></strong></p>\n<p>Mengingat pentingnya penghitungan perubahan inventori sebagai tolak ukur penghitungan produktivitas ekonomi suatu negara, Survei Khusus Studi Penyusunan Perubahan Inventori (SKSPPI) perlu dilakukan untuk memperoleh informasi yang akurat dan rinci mengenai besarnya nilai posisi barang inventori.</p>\n<p>&nbsp;</p>\n<p><strong><span class="deskripsi-label">Tujuan dan Manfaat Kegiatan</span></strong></p>\n<p>Memperoleh gambaran yang mendasar mengenai kuantitas dan posisi nilai inventori/persediaan pada awal tahun dan akhir tahun, - Memperoleh data inventori, pola dan strukturnya menurut karakteristik, jenis dan klasifikasi lapangan usaha, - Memperoleh informasi mengenai rasio inventori terhadap nilai produksi (output) dan polanya pada sektor-sektor ekonomi, - Menerapkan System National Account 2008 (SNA 2008) yang berkaitan dengan Perubahan inventori.</p>\n<p>&nbsp;</p>\n<p><strong><span class="deskripsi-label">Frekuensi Kegiatan</span></strong></p>\n<p>Tahunan</p>', 'NULL', '2025-07-24 11:27:09', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('Ts0STkgLlfi', '2024s104', 'Survei Tahunan Perusahaan Industri Manufaktur (STPIM)', '2024', '2024s104', '<p><strong>Melly</strong></p>\n<p>Rodiah</p>', '<ul>\n<li>Link Dashboard: <a href="https://webentry.bps.go.id/ibs">https://webentry.bps.go.id/ibs</a></li>\n</ul>\n<p>&nbsp;</p>\n<ul>\n<li>Daftar Sampel 2024: <a href="http://s.bps.go.id/stpim2024">http://s.bps.go.id/stpim2024</a></li>\n</ul>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>', '<p><strong>Updating Direktori&nbsp; </strong>:<strong> &nbsp;</strong>Maret - April 2024</p>\n<p><strong>Pencacahan&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </strong>:<strong> &nbsp;</strong>Mei- Oktober 2024</p>', '2024-02-15 11:12:41', '198604222009022005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('U0gQLWKcwAh', '2024s102', 'PEKPPP', '2025', '2024s107', '<p>aaa</p>', '<p>aaaaa</p>', 'NULL', '2025-01-31 9:02:57', '199711192021042001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('U0nrPAayOEg', '2024s105', 'Survei Harga Konsumen (SHK)', '2024', '2024s103', '<p>Ketua Tim : Titiek Zurryati</p>\n<p>PJK : Mursalina</p>\n<p>Anggota: Dwi Susanti</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Andariati Afrida</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Nyimas Eka</p>', '<p>Link Dashboard: <a title="shk.bps.go.id" href="shk.bps.go.id" target="_blank" rel="noopener">shk.bps.go.id</a></p>', '<table style="width: 500px;" border="1" cellspacing="1" cellpadding="1">\n<tbody>\n<tr>\n<td>Pencacahan SHK</td>\n<td>Januari - Desember 2024</td>\n</tr>\n<tr>\n<td>Pengolahan SHK</td>\n<td>Januari - Desember 2024</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>', '2024-02-05 10:45:36', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('Ugrr3pc2ZzU', '2024s101', 'Penyusunan Laporan Keuangan TA2023', '2024', '2024s101', '<p>Tasdik Ilhamudin</p>\n<p>Edo Mara Nasution</p>\n<p>Teti Safrida Purba</p>\n<p>Bahzur Andria</p>', '<p class="MsoListParagraphCxSpFirst" style="mso-add-space: auto; text-align: justify; text-indent: 18.0pt; line-height: 115%; margin: 0cm 0cm .0001pt 18.0pt;"><span lang="EN-US" style="font-size: 12.0pt; line-height: 115%; font-family: \'Calibri Light\',sans-serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: Calibri; mso-bidi-theme-font: minor-latin;">Pasal 33 Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Pelaporan Keuangan dan Kinerja Instansi Pemerintah menyatakan bahwa untuk mendukung keandalan laporan keuangan pemerintah maka perlu diselenggarakan sistem pengendalian intern yang di dalamnya mencakup proses rekonsiliasi antara transaksi keuangan yang diakuntansikan oleh Pengguna Anggaran/Kuasa Pengguna Anggaran (PA/KPA) dengan data transaksi keuangan yang diakuntansikan oleh Bendahara Umum Negara. </span><span style="font-family: \'Calibri Light\', sans-serif; font-size: 12pt; text-indent: 18pt;">Salah satu karakteristik yang merupakan prasyarat normatif yang diperlukan agar laporan keuangan pemerintah dapat memenuhi kualitas yang dikehendaki menurut Kerangka Konseptual Standar Akuntansi Pemerintahan adalah keandalan (reliability).</span><span style="mso-spacerun: yes;">&nbsp; </span><span style="font-family: \'Calibri Light\', sans-serif; font-size: 12pt; text-indent: 18pt;">Pasal 46 ayat (1) Peraturan Menteri Keuangan Nomor 213/PMK.05/2013 tentang Sistem Akuntansi dan Pelaporan Keuangan Pemerintah Pusat sebagaimana telah diubah dengan Peraturan Menteri Keuangan Nomor 215/PMK.05/2016 menyatakan bahwa dalam rangka meyakinkan keandalan dalam penyusunan laporan keuangan dilakukan rekonsiliasi. Pasal 46B ayat (10) Peraturan Menteri Keuangan Nomor 213/PMK.05/2013 tentang Sistem Akuntansi dan Pelaporan Keuangan Pemerintah Pusat sebagaimana telah diubah dengan Peraturan Menteri Keuangan Nomor 215/PMK.05/2016 menyatakan bahwa ketentuan lebih lanjut mengenai tata cara pelaksanaan rekonsiliasi diatur dengan Peraturan Menteri Keuangan.</span></p>', '<p>Januari - Februari 2024</p>', '2024-02-21 8:03:44', '198306172005021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('uJ3YnFxkVZo', '2024s101', 'Penyiapan Peralatan dan Jaringan untuk PMB STIS 2024', '2024', '2024s105', '<p>Menyiapkan perangkat PC, Jaringan,monitoring dan penanganan kendala koneksi saat ujian PMB</p>', '<p>link SPMB https://spmb.stis.ac.id/</p>', '<table style="border-collapse: collapse; width: 99.982%;" border="1"><colgroup><col style="width: 48.5514%;"><col style="width: 51.4317%;"></colgroup>\n<tbody>\n<tr>\n<td>Penyiapan Peralatan dan pengetesan</td>\n<td>7-9 Agustus 2024</td>\n</tr>\n<tr>\n<td>Pelaksanaan Kegiatan ujian, monitoring dan penangan kendala</td>\n<td>10-11 Agustus 2024</td>\n</tr>\n</tbody>\n</table>', '2024-08-20 10:49:15', '198012212010031001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('unAwQ8GzSgs', '2024s106', 'Penyusunan Angka PDRB Triwulan 4 Tahun 2024', '2025', '2025s106', '<p>PJK :</p>\n<p>Meita Jumiartanti, SST, M.Si</p>\n<p>Anggota:</p>\n<ol>\n<li>Hendra Dharmawan, SST, M.Si</li>\n<li>Ridha Mutia, SE, M.Si</li>\n<li>Hilda Aprina, SST, M.Si</li>\n<li>Cahya Danu Rahman, SST</li>\n<li>Maulizasari, S.Stat</li>\n<li>Fitri Mulyani, SST</li>\n<li>Mazaya Alifah Syadzwina, S.Tr.Stat</li>\n<li>Azwar, SE</li>\n</ol>', '<p><strong><span class="deskripsi-label">Tujuan dan Manfaat Kegiatan</span></strong></p>\n<p>Menyediakan data dan indikator ekonomi makro sebagai evaluasi dan perencanaan pembangunan</p>\n<p>&nbsp;</p>\n<p><strong><span class="deskripsi-label">Frekuensi Penyelenggaraan</span></strong></p>\n<p>Triwulanan</p>', 'NULL', '2025-07-24 14:17:52', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
