-07-25 15:31:20', '198607312009022006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('v2kjou2pxEH', '2024s104', 'Survei Pelabuhan Pendaratan Ikan (PPI/TPI)', '2024', '2024s104', '<p>Nilam Humaira</p>\n<p>Raiski Ramdhoni</p>\n<p>Teti Safrida Purba</p>', '<ul>\n<li>Periode Kegiatan Survei Pelabuhan Pendaratan Ikan (PPI/TPI) adalah&nbsp;<strong>Triwulanan</strong></li>\n<li>Aplikasi entri data <a href="https://ipd.bps.go.id/perikanan/login">https://ipd.bps.go.id/perikanan/login</a></li>\n<li>Link Upload Dokumen Perikanan XXXXX</li>\n</ul>\n<p>&nbsp;</p>\n<p>&nbsp;</p>', '<p><img src="data:image/png;base64,"></p>', '2024-02-20 12:05:48', '198607292009022005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('V33nXUkaYYJ', '2024s104', 'Survei Perusahaan Perkebunan', '2025', '2025s104', '<p>Hendra Gunawan</p>\n<p>Raiski Ramadhoni</p>', '<ul>\n<li>Survei Perusahaan Perkebunan merupakan kegiatan pengumpulan data perkebunan yang dilakukan pada seluruh perusahaan perkebunan yaitu data&nbsp;Perusahaan Perkebunan Negara dan data Perusahaan Perkebunan Swasta di&nbsp;wilayah Republik Indonesia.</li>\n<li>Pengumpulan data perusahaan perkebunan&nbsp;dilakukan secara online yang disebut dengan Sedia Data Perusahaan Perkebunan&nbsp;melalui aplikasi SKB Online (SEDAPP Online).</li>\n<li>Pengumpulan data Survei Perusahaan Perkebunan dilakukan dengan periode bulanan&nbsp;(Sedapp Online) dan tahunan (SKB Tahunan) dengan Output Luas Tanaman dan Produksi Komoditas.</li>\n<li>Jadwal dan direktori Sedapp Online untuk target pencacahan 2025 dapat dilihat pada tautan <a href="https://s.bps.go.id/direktori_sedap2024">https://s.bps.go.id/direktori_sedapp2024</a></li>\n<li>Jadwal dan direktori SKB Tahunan untuk target pencacahan 2025 dapat dilihat pada tautan <a href="https://s.bps.go.id/direktori_sedap2024">https://s.bps.go.id/direktori_skb2024</a></li>\n<li>Input Data Sedapp Online bulanan dilakukan pada alamat: <a href="https://skb.bps.go.id/pb">https://skb.bps.go.id/pb</a></li>\n<li>Input data SKB Tahunan dilakukan pada alamat: <a href="https://pengolahan.bps.go.id/produksi/perkebunan/SKB_tahunan">https://pengolahan.bps.go.id/produksi/perkebunan/SKB_tahunan</a></li>\n</ul>', '<ul>\n<li>Pengumpulan, Pemeriksaan, dan Pengolahan Data : Setiap Bulan</li>\n<li>Tabulasi Data: Angka Tetap 2024 (Mei 2024) dan Angka Sementara 2025 ( September 2025)</li>\n</ul>\n<p>&nbsp;</p>', '2025-07-25 15:46:39', '198605212006041003', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('vbNDOoEoJoB', '2024s101', 'Pemenuhan Permindok BPK RI', '2024', '2024s101', '<p>PIC : Edo Mara Nasution</p>\n<p>Anggota : Tim Umum dan Tim Teknis Kegiatan</p>', '<p>Sebagai tindak lanjut atas pemenuhan permintaan dokumen BPK RI dalam rangka pemeriksaan terinci atas Laporan Keuangan Tahun 2023 pada Badan Pusat Statistik</p>', '<p>Periode Januari s/d Juni&nbsp;</p>', '2024-02-19 16:54:42', '198306172005021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('vBXTF705GLl', '2024s105', 'Survei Karakteristik Usaha/Business Characteristic Survey (SKU)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Effendy</p>\n<p>Anggota&nbsp; &nbsp; : Cut Sandra&nbsp;</p>', '<p>Link Dashboard:&nbsp;</p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pelatihan/Briefing Innas dan Petugas</td>\n<td>&nbsp; Juni 2024</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp; Juli - Agustus 2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-06 11:00:43', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('vF8um5cBHbj', '2024s104', 'Survei Komoditas Industri Manufaktur (SKIM)', '2024', '2024s104', '<p><strong>Melly</strong></p>\n<p>Rodiah</p>', '<p>Survei Komoditas Industri Manufaktur merupakan kegiatan survei baru yang mulai dilaksanakan tahun 2024.&nbsp;</p>', '<p><strong>Pencacahan : </strong>Mei 2024</p>', '2024-02-15 11:02:42', '198604222009022005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('vh2bLCdctjX', '2024s107', 'Pemenuhan SPIP', '2024', '2024s108', '<p>Ketua : <strong>Yan Yan Gustiana</strong></p>\n<p>Anggota :</p>\n<p>Maulizasari</p>\n<p>Mazaya Alifah Syadzwina</p>\n<div class="hc-details hc-details-open-top">\n<div>Rodiah</div>\n<div>Tasdik Ilhamudin</div>\n<div>Wahdini</div>\n<div>Ferfi Hamdina</div>\n<div>Reza Rezki Pulungan</div>\n<div>Teti Safrida Purba</div>\n<div>&nbsp;</div>\n<div>&nbsp;</div>\n</div>', '<p>Pemenuhan dokumen pendukung SPIP</p>\n<p><a title="SPIP" href="https://drive.bps.go.id/apps/files/?dir=/%5B02.%20Share%20-%20BPS%20Provinsi%20Aceh%5D/08%20Tim%20Tranformasi%20dan%20Budaya%20Organisasi/SPIP&amp;fileid=61367680">SPIP</a></p>', '<p>Sosialisasi Mitigasi Risiko : September 2024</p>', '2024-10-04 11:06:24', '199509142019032002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('VPzJF3jMUrA', '2024s103', 'Survei Sosial Ekonomi Nasional (SUSENAS)2025', '2025', '2025s102', '<p><strong>Ketua </strong>Tim: Abd.Hakim<br><strong>PJK</strong>:Subhan &nbsp;&nbsp;<br><strong>Anggota</strong>: Juliana,Naura,M.Ridha,Darwis,Alfi,Ismaturahmi,Maulidya</p>', '<p><span data-huuid="1427780944387654098">SUSENAS adalah singkatan dari&nbsp;<mark class="QVRyCf">Survei Sosial Ekonomi Nasional</mark>.&nbsp;</span><span data-huuid="1427780944387656497">Ini adalah survei rutin yang dilakukan oleh Badan Pusat Statistik (BPS) untuk mengumpulkan data sosial ekonomi rumah tangga di seluruh Indonesia.&nbsp;</span><span data-huuid="1427780944387654800">Data ini digunakan untuk berbagai keperluan, termasuk perencanaan dan evaluasi program pembangunan, serta penyediaan indikator untuk Tujuan Pembangunan Berkelanjutan (TPB)&nbsp;<a class="uVhVib" href="https://mappikab.bps.go.id/id/news/2025/01/13/3/survei-sosial-ekonomi-nasional--susenas--maret-dan-seruti-triwulan-i-2025.html" data-jsarwt="1" data-usg="AOvVaw33aSIn7vbT3VsVHQlWRkRG" data-ved="2ahUKEwjTjNX_jtqOAxVzUWwGHTNfJvwQjJEMegQIHhAB">seperti yang disebutkan oleh Badan Pusat Statistik Indonesia</a></span></p>\n<p><span data-huuid="1427780944387654800">Secara rinci susenas bertujuan : Meliputi informasi tentang pendidikan, kesehatan, perumahan, konsumsi/pengeluaran, dan berbagai aspek sosial ekonomi lainnya dari rumah tangga.</span></p>\n<p><span data-huuid="1427780944387654800">Data SUSENAS digunakan sebagai dasar dalam penyusunan rencana pembangunan nasional dan daerah, serta untuk mengevaluasi efektivitas program-program pembangunan yang telah berjalan.</span></p>\n<p><span data-huuid="1427780944387654800">SUSENAS menghasilkan berbagai indikator penting seperti kemiskinan, Indeks Pembangunan Manusia (IPM), dan rasio gini, yang digunakan untuk mengukur tingkat kesejahteraan masyarakat.<span class="pjBG2e" data-cid="a9bf4f05-fb47-46ab-be12-7fdcb33bd5e5"><span class="UV3uM">&nbsp;</span></span></span></p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>', '<table style="border-collapse: collapse; width: 593px;" border="0" width="515" cellspacing="0" cellpadding="0"><colgroup><col style="width: 384.5px;" width="346"> <col style="width: 207.5px;" width="169"> </colgroup>\n<tbody>\n<tr style="height: 14.5pt;">\n<td class="xl65" style="height: 14.5pt; width: 260pt; text-align: center;" width="346" height="19"><strong>Kegiatan</strong></td>\n<td class="xl66" style="width: 127pt; text-align: center;" width="169"><strong>Jadwal</strong></td>\n</tr>\n<tr style="height: 14.5pt;">\n<td class="xl63" style="height: 14.5pt;" height="19"><span style="font-variant: normal;">Pemutakhiran rumah tangga pada blok sensus Susenas</span></td>\n<td>1 &ndash;6 Februari 2025</td>\n</tr>\n<tr style="height: 29.0pt;">\n<td class="xl64" style="height: 29.0pt; width: 260pt;" width="346" height="39">Pengawasan dan pemeriksaan hasil<br>pemutakhiran rumah tangga</td>\n<td>1 &ndash;6 Februari 2025</td>\n</tr>\n<tr style="height: 29.0pt;">\n<td class="xl64" style="height: 29.0pt; width: 260pt;" width="346" height="39">Entry data hasil pemutakhiran rumah<br>tangga</td>\n<td>2&ndash;8 Februari 2025</td>\n</tr>\n<tr style="height: 14.5pt;">\n<td class="xl63" style="height: 14.5pt;" height="19">Penarikan sampel rumah tangga</td>\n<td>2&ndash;8 Februari 2025</td>\n</tr>\n<tr style="height: 14.5pt;">\n<td class="xl63" style="height: 14.5pt;" height="19">Pendataan rumah tangga sampel</td>\n<td>8&ndash;27 Februari 2025</td>\n</tr>\n<tr style="height: 14.5pt;">\n<td class="xl63" style="height: 14.5pt;" height="19">Pengawasan/pemeriksaan</td>\n<td>8&ndash;27 Februari 2025</td>\n</tr>\n<tr style="height: 29.0pt;">\n<td class="xl64" style="height: 29.0pt; width: 260pt;" width="346" height="39">Monitoring pendataan dengan<br>menggunakan website</td>\n<td>11 &ndash;27 Februari 2025</td>\n</tr>\n<tr style="height: 29.0pt;">\n<td class="xl64" style="height: 29.0pt; width: 260pt;" width="346" height="39">Penyerahan hasil pendataan ke BPS<br>Kab/Kota</td>\n<td>12 Februari&ndash;6 Maret 2025</td>\n</tr>\n<tr style="height: 14.5pt;">\n<td class="xl63" style="height: 14.5pt;" height="19">&nbsp;</td>\n<td>&nbsp;</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>', '2025-07-26 15:37:33', '198109132006021001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('vTl3HlDYil5', '2024s106', 'Survey Khusus Triwulanan Neraca Produksi (SKTNP) Barang dan Jasa', '2025', '2025s106', '<p>PJK:</p>\n<p>Maulizasari, S.Stat</p>', '<p>PDB merupakan indikator yang digunakan untuk melihat pertumbuhan perekonomian Indonesia. Dalam menyusun PDB, diperlukan data harga dan produksi dari barang dan jasa. Karena data harga dan produksi tidak selalu tersedia untuk triwulanan, maka diperlukan survei khusus untuk mencari indikator produksi setiap triwulanannya</p>', 'NULL', '2025-07-24 11:06:51', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('Vz8dy33vBEO', '2024s102', 'Web KOTAK', '2024', '2024s105', '<p>Ketua Tim: Fitral</p>\n<p>PJK : Ichsan&nbsp;</p>\n<p>Anggota:</p>\n<ul>\n<li>Hafidz</li>\n<li>Nelvi</li>\n<li>Zukra</li>\n<li>Andi&nbsp;</li>\n<li>Gunadi</li>\n</ul>', '<p>link : <a href="https://qna.bpsaceh.com/" target="_blank" rel="noopener">qna.bpsaceh.com</a></p>', '<p>Rilis :&nbsp;</p>', '2024-08-20 10:58:01', '199501232018021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('wAHqDZVQFtC', '2024s105', 'Penyusunan Publikasi "Nilai Tukar Petani"', '2025', '2025s103', '<p>Akhmad Sugito</p>\n<p>Dwi Susanti</p>\n<p>Mega Thursina</p>', '<p class="MsoNormal" style="margin-right: .3pt; text-align: justify; line-height: 150%; tab-stops: 54.0pt;"><span lang="SV" style="font-size: 10.0pt; mso-bidi-font-size: 11.0pt; line-height: 150%; font-family: \'Verdana\',sans-serif; mso-ansi-language: SV;">Publikasi "Nilai Tukar Petani (NTP) Provinsi Aceh 2024" merupakan kelanjutan dari publikasi yang diterbitkan oleh Badan Pusat Statistik Provinsi Aceh. Data-data yang disajikan dalam publikasi ini mencakup lima subsektor yaitu: tanaman pangan, tanaman hortikultura, tanaman perkebunan rakyat, peternakan, dan perikanan. Publikasi ini berdasarkan tahun dasar 2018 yang tersaji dalam dua tahun yaitu 2023 dan 2024. </span><span lang="SV" style="font-size: 10.0pt; mso-bidi-font-size: 11.0pt; font-family: \'Verdana\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: SV; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;">Di samping menyajikan data indeks harga yang diterima petani, indeks harga yang dibayar petani, dan nilai tukar petani, publikasi ini juga menyajikan konsep definisi, metodologi dan penjelasan mengenai diagram timbang yang digunakan dalam penyusunan NTP</span></p>', 'NULL', '2025-03-06 8:22:53', '198410312008011005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('wBMvH50bTcd', '2024s101', 'Pengelolaan Database Pengguna Data untuk Peningkatan Literasi Data secara berkelanjutan', '2024', '2024s108', '<p>Kahar Muzakar</p>', '<p>Terselenggaranya Pengelolaan Digitalisasi Layanan dan Inovasi Peningkatan Hubungan dengan Pengguna Data secara berkualitas dan berkelanjutan</p>', '<p>2024</p>', '2024-02-23 9:15:20', '199607132019012002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('wcpPWxg8xcj', '2024s103', 'Survei Penduduk Antar Sensus (SUPAS) 2025', '2025', '2025s102', '<p><strong>Ketua </strong>Tim: Abd.Hakim<br><strong>PJK</strong>:Juliana &nbsp; &nbsp;<br><strong>Anggota</strong>: Naura,M.Ridha,Darwis,Alfi,Ismaturahmi,Maulidya</p>', '<p><span data-huuid="5010011488722627408">Survei Penduduk Antar Sensus (SUPAS) adalah&nbsp;<mark class="QVRyCf">kegiatan survei yang dilakukan oleh Badan Pusat Statistik (BPS) untuk memperbarui data kependudukan dan mendapatkan informasi tentang karakteristik penduduk di antara dua Sensus Penduduk</mark>.&nbsp;</span><span data-huuid="5010011488722626611">SUPAS membantu dalam memperkirakan jumlah, distribusi, dan komposisi penduduk, serta menyediakan data untuk berbagai indikator demografi dan perencanaan pembangunan.<span class="pjBG2e" data-cid="f916d7a2-f3ad-4f59-9f5d-e86ce09caf58"><span class="UV3uM">&nbsp;</span></span></span></p>\n<p><span data-huuid="5010011488722626611">Tujuan Utama adalah : Mengumpulkan data penduduk dan indikator demografi (seperti kelahiran, kematian, dan migrasi) untuk mengisi kesenjangan informasi antara dua Sensus Penduduk.</span></p>\n<p><strong>Dasboard Monitoring (Hanya dapat diakses oleh akun yang terdaftar)</strong>&nbsp;:&nbsp;<a href="https://fasih-dashboard.bps.go.id/login/">https://fasih-dashboard.bps.go.id</a></p>\n<p><strong>Dashboard Evaluasi (Hanya dapat diakses oleh akun yang terdaftar)</strong>:&nbsp;<a href="https://fasih-sm.bps.go.id/">https://fasih-sm.bps.go.id</a>&nbsp;</p>', '<div dir="ltr" align="left">\n<table><colgroup><col width="44"><col width="369"><col width="210"></colgroup>\n<tbody>\n<tr>\n<td style="text-align: center;">\n<p dir="ltr"><strong>No.</strong></p>\n</td>\n<td style="text-align: center;">\n<p dir="ltr"><strong>Kegiatan</strong></p>\n</td>\n<td style="text-align: center;">\n<p dir="ltr"><strong>Jadwal</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">1.</p>\n</td>\n<td>\n<p dir="ltr">Penyusunan kuesioner</p>\n</td>\n<td>\n<p dir="ltr">Januari - April 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">2.</p>\n</td>\n<td>\n<p dir="ltr">Penyusunan buku pedoman</p>\n</td>\n<td>\n<p dir="ltr">Januari &ndash; April 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">3.</p>\n</td>\n<td>\n<p dir="ltr">Penyempurnaan CAPI</p>\n</td>\n<td>\n<p dir="ltr">Januari - April 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">4.</p>\n</td>\n<td>\n<p dir="ltr">Penyusunan Bahan ajar</p>\n</td>\n<td>\n<p dir="ltr">Februari - April 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">5.</p>\n</td>\n<td>\n<p dir="ltr">Workshop Instruktur Utama (Intama)</p>\n</td>\n<td>\n<p dir="ltr">April 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">6.</p>\n</td>\n<td>\n<p dir="ltr">Pelatihan Instruktur Nasional (Innas)</p>\n</td>\n<td>\n<p dir="ltr">Mei 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">7.</p>\n</td>\n<td>\n<p dir="ltr">Pelatihan Petugas</p>\n</td>\n<td>\n<p dir="ltr">Jun 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">8.</p>\n</td>\n<td>\n<p dir="ltr">Pemutakhiran</p>\n</td>\n<td>\n<p dir="ltr">11-30 Juni 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">9</p>\n</td>\n<td>\n<p dir="ltr">Pendataan Lapangan</p>\n</td>\n<td>\n<p dir="ltr">1-31 Juli 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">10.</p>\n</td>\n<td>\n<p dir="ltr">Pengawasan pelaksanaan lapangan</p>\n</td>\n<td>\n<p dir="ltr">11 Juni s.d 31 Juli 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">11.</p>\n</td>\n<td>\n<p dir="ltr">Monitoring dan evaluasi via dashboard dynamic</p>\n</td>\n<td>\n<p dir="ltr">11 Juni s.d 31 Juli 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">12.</p>\n</td>\n<td>\n<p dir="ltr">Evaluasi Data</p>\n</td>\n<td>\n<p dir="ltr">Juni - September 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">13.</p>\n</td>\n<td>\n<p dir="ltr">Finalisasi Data</p>\n</td>\n<td>\n<p dir="ltr">Oktober 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">14.</p>\n</td>\n<td>\n<p dir="ltr">Penghitungan Indikator</p>\n</td>\n<td>\n<p dir="ltr">Oktober - November 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">15.</p>\n</td>\n<td>\n<p dir="ltr">Evaluasi Indikator</p>\n</td>\n<td>\n<p dir="ltr">Oktober - November 2025</p>\n</td>\n</tr>\n<tr>\n<td>\n<p dir="ltr">16.</p>\n</td>\n<td>\n<p dir="ltr">Rilis Hasil SUPAS 2025</p>\n</td>\n<td>\n<p dir="ltr">Desember 2025</p>\n</td>\n</tr>\n</tbody>\n</table>\n</div>\n<p>&nbsp;</p>', '2025-07-26 15:28:01', '198109132006021001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('WD7TLRc7UKe', '2024s101', 'Pengelolaan Implementasi Rencana Aksi Manajemen Perubahan Tahun 2024', '2024', '2024s108', '<p>Ketua : <strong>Yan Yan Gustiana</strong></p>\n<p>CC : <strong>Hendra Gunawan</strong></p>\n<p>CA :</p>\n<p>Wira Junardi</p>\n<p>Fikri</p>\n<p>Muhammad Hafidz Al Ahmad Bit</p>\n<p>Maulizasari</p>\n<p>Mazaya Alifah Syadzwina</p>\n<p>Anandika Dian Pramesti</p>\n<p>&nbsp;</p>', '<ol>\n<li>Kegiatan Berapi (Briefing Rabu Pagi) dilakukan setiap hari rabu pagi bersama pimpinan dan seluruh pegawai BPS Provinsi Aceh maupun kabupaten/kota <em><a href="https://drive.bps.go.id/s/iqNYorG3PF56jcL?path=%2FBERAPI">BERAPI</a></em></li>\n<li><em>SK dan Surat Tugas CAN periode 2024 BPS Aceh <a href="https://drive.bps.go.id/apps/files/?dir=/%5B02.%20Share%20-%20BPS%20Provinsi%20Aceh%5D/08%20Tim%20Tranformasi%20dan%20Budaya%20Organisasi/Change%27s%20Team/Change%20Agents&amp;fileid=28845742">SK dan Surat Tugas</a></em></li>\n<li>Briefing Rabu Pagi (Berapi) merupakan media diskusi atara pimpinan dan pegawai serta media&nbsp;<em>sharing knowledge</em>&nbsp;di lingkungan BPS Provinsi Aceh.</li>\n<li>Diselenggarakan setiap hari rabu secara&nbsp;<em>Offline&nbsp;</em>maupun&nbsp;<em>Online&nbsp;</em>dengan peserta yakni pegawai di BPS Provinsi Aceh dan BPS Kabupaten/Kota se Provinsi Aceh.</li>\n<li>Dokumentasi dan Notulensi Berapi Tahun 2024 dapat diakses pada alamat:&nbsp;<a href="https://drive.bps.go.id/s/iqNYorG3PF56jcL?path=%2FBERAPI">Kegiatan Berapi</a></li>\n</ol>', '<ol>\n<li>Kegiatan Berapi dilakukan setiap hari Rabu&nbsp; <em><a href="https://drive.bps.go.id/apps/onlyoffice/s/iqNYorG3PF56jcL?fileId=27849405">Jadwal BERAPI 2024</a></em></li>\n<li>Berapi dilakukan dengan tema yang berbeda setiap minggunya dengan jadwal sebagai berikut:</li>\n<li>Minggu 1 : Sharing knowledge bersama kabupaten/kota&nbsp;</li>\n<li>Minggu 2 : Internalisasi BerAKHLAK</li>\n<li>Minggu 3 : Rabu Aspirasi</li>\n<li>Minggu 4 : Internalisasi Indikator Statistik</li>\n</ol>', '2024-03-26 9:20:35', '199509142019032002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('WfvA9ZhJbJG', '2024s102', 'Lokakarya SO ASIK', '2024', '2024s107', '<p>Ketua Tim: Hendri Achmad Hudori</p>\n<p>PJ Kegiatan: Ar Razy Ridha Maulana</p>\n<p>Anggota:</p>\n<ul>\n<li>Azwar</li>\n<li>Nyimas Eka Yunia Hasnita</li>\n<li>Rubama</li>\n<li>Marhami</li>\n<li>Nurzakiah</li>\n<li>Munandar</li>\n<li>Anandika Dian Pramesti</li>\n<li>Nelvi Istiqamah</li>\n<li>M. Reza</li>\n<li>Zulviyana</li>\n<li>M. Alimudin</li>\n</ul>', '<p>Link materi lokakarya:&nbsp;<a href="https://linktr.ee/lokakarya1100">s.id/lokakarya1100</a></p>', '<table style="border-collapse: collapse; width: 100.039%;" border="1"><colgroup><col style="width: 5.27265%;"><col style="width: 61.446%;"><col style="width: 33.2423%;"></colgroup>\n<tbody>\n<tr>\n<td style="text-align: center;"><strong>No.</strong></td>\n<td style="text-align: center;"><strong>Judul Lokakarya</strong></td>\n<td style="text-align: center;"><strong>Tanggal</strong></td>\n</tr>\n<tr>\n<td>1</td>\n<td>Sosialisasi Hasil SBH 2022</td>\n<td>15 Januari 2024</td>\n</tr>\n<tr>\n<td>&nbsp;</td>\n<td>&nbsp;</td>\n<td>&nbsp;</td>\n</tr>\n</tbody>\n</table>', '2024-03-21 11:32:36', '199711192021042001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('wUA9Fpo2qcO', '2024s104', 'Survei Kerangka Sampel Area (KSA) Padi dan Jagung (Bulanan)', '2025', '2025s104', '<div class="judul">Hendra Gunawan</div>\n<div class="daftar">\n<p>Nilam Humaira</p>\n<p>Raiski Ramadhoni</p>\n<p>&nbsp;</p>\n</div>', '<p><span class="fontstyle0">Pendataan Statistik Pertanian Tamanan Pangan Terintegrasi Dengan Metode Kerangka Sampel Area (KSA) adalah kegiatan observasi langsung tentang fase tumbuh padi dan jagung pada titik amatan pada sampelterpilih dengan menggunakan moda CAPI.&nbsp;</span></p>\n<p>&nbsp;</p>\n<p><span class="fontstyle0">Pendataan ini menghasilkan indikator penting dalam perencanaan pertanian yaitu&nbsp;</span><span class="fontstyle2">luas panen, potensi luas panen, dan luas fase amatan&nbsp;lainnya.</span>&nbsp;</p>\n<p>&nbsp;</p>\n<p>Tautan Manajemen Survei :&nbsp;<strong><a href="https://ksapro-manajemen.bps.go.id/">https://ksapro-manajemen.bps.go.id/</a></strong></p>', '<ul>\n<li>Persiapan : November- Desember 2024</li>\n<li>Pengumpulan Data : Minggu terakhir setian bulan</li>\n<li>Pengolahan Data : dalam 5 hari setelah pendataan</li>\n<li>Desiminasi : Maret dan November 2025</li>\n</ul>', '2025-07-25 18:09:19', '198607292009022005', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('X7Vd1NAqE9c', '2024s105', 'Pemutakhiran Direktori Pasar dan Pusat Perbelanjaan', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Hani\'ah</p>\n<p>Anggota&nbsp; &nbsp; : Akhmad Sugito&nbsp;</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ferfi Hamdina&nbsp;</p>', '<p>Link Dashboard:&nbsp;</p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pelatihan Innas dan Petugas</td>\n<td>&nbsp;</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;&nbsp;2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-05 11:37:50', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('X8mYSeNdX5s', '2024s105', 'Survei Pola Triwulanan Kegiatan Usaha (STKU)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Hani\'ah</p>\n<p>Anggota&nbsp; &nbsp; : Akhmad Sugito&nbsp;</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ferfi Hamdina&nbsp;</p>', '<p>Link Dashboard:</p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pelatihan Innas dan Petugas</td>\n<td>&nbsp;</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>\n<ul>\n<li>Triwulan 1 : 2024</li>\n<li>Triwulan 2 : 2024</li>\n<li>Triwulan 3 : 2024</li>\n<li>Triwulan 4 : 2024</li>\n</ul>\n</td>\n</tr>\n</tbody>\n</table>', '2024-02-05 11:40:15', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('XA8kryTUZH5', '2024s105', 'Survei Harga Produsen Jasa (HPJ)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Mursalina</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>', '<p>Link Dashboard:&nbsp;<a href="https://webentry.bps.go.id/shp/" target="_blank" rel="noopener">https://webentry.bps.go.id/shp/</a></p>', '<table style="width: 473.984px;" border="1">\n<tbody>\n<tr>\n<td>Pelatihan Innas dan Petugas</td>\n<td>&nbsp;Januari 2024</td>\n</tr>\n<tr>\n<td>Pencacahan</td>\n<td>&nbsp;Januari - Desember&nbsp;2024</td>\n</tr>\n</tbody>\n</table>', '2024-02-05 10:43:26', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('XCaTjxf3ty7', '2024s104', 'Survei Pertambangan dan Energi (PE) Tahunan', '2025', '2025s104', '<ol>\n<li>Cut Malahayati</li>\n<li>Fikri</li>\n</ol>', '<ul>\n<li>Survei Pertambangan dan Energi (PE) Tahunan terhadap usaha/perusahaan pertambangan dan energi secara umum bertujuan memberikan informasi &nbsp;yang &nbsp;bermanfaat &nbsp;bagi &nbsp;pembuatan &nbsp;kebijakan &nbsp;pemerintah &nbsp;di &nbsp;bidang pertambangan &nbsp;dan &nbsp;energi. &nbsp;Selain &nbsp;kegiatan &nbsp;survei, &nbsp;juga &nbsp;dilakukan &nbsp;kegiatan Updating Direktori Perusahaan untuk memutakhirkan data direktori perusahaan. &nbsp;Selain &nbsp;survei &nbsp;dengan &nbsp;pendekatan &nbsp;perusahaan &nbsp;sektor &nbsp;pertambangan &nbsp;dan energi, juga dilakukan Survei Captive Power, dengan pendekatan perusahaan non pertambangan dan industri pengolahan. Secara umum survei ini bertujuan untuk memperoleh data energi listrik yang dihasilkan oleh instansi/perusahaan sendiri dengan &nbsp;cara &nbsp;pembangkitan &nbsp;listrik. &nbsp;Oleh &nbsp;karena &nbsp;jenis &nbsp;perusahaan &nbsp;yang &nbsp;dicakup sangat banyak, maka cakupan perusahaannya selalu berubah di setiap tahun.</li>\n<li>Metode &nbsp;pengumpulan &nbsp;data &nbsp;survei &nbsp;pertambangan &nbsp;dan &nbsp;energi &nbsp;pada &nbsp;Tahun 2025 mulai beralih menggunakan moda pendataan CAPI/CAWI. Pendataan dapat dilakukan &nbsp;dengan &nbsp;pencacahan &nbsp;langsung, &nbsp;yaitu &nbsp;dengan &nbsp;mendatangi &nbsp;perusahaan terpilih &nbsp;dengan &nbsp;metode &nbsp;Computer-Assisted &nbsp;Personal &nbsp;Interview &nbsp;(CAPI) &nbsp;atau membawa &nbsp;kuesioner &nbsp;untuk &nbsp;wawancara. Pengumpulan &nbsp;data &nbsp;juga &nbsp;dapat &nbsp;dilakukan &nbsp;dengan metode self enumeration, yaitu perusahaan akan mengisi kuesioner sendiri melalui Computer &nbsp;Assisted &nbsp;Web &nbsp;Interviewing &nbsp;(CAWI) &nbsp;yang &nbsp;sebelumnya &nbsp;telah &nbsp;diberikan penjelasan &nbsp;teknis &nbsp;pengisian &nbsp;oleh &nbsp;petugas.&nbsp;</li>\n<li>Monitoring Dashboard:&nbsp;<a title="Monitoring Dashboard" href="https://fasih-dashboard.bps.go.id/">https://fasih-dashboard.bps.go.id&nbsp;</a></li>\n<li>Buku Pedoman Survei PE 2025:&nbsp;<a title="Buku Pedoman Survei PE 2025" href="https://drive.bps.go.id/s/oPXsi5Jqex5W35T">https://drive.bps.go.id/s/oPXsi5Jqex5W35T</a></li>\n<li>Daftar Sampel:&nbsp;<a title="Daftar Sampel" href="https://drive.bps.go.id/apps/onlyoffice/s/gjgXYCBSfttMPBQ?fileId=77291338">https://drive.bps.go.id/apps/onlyoffice/s/gjgXYCBSfttMPBQ?fileId=77291338</a></li>\n<li>Kuesioner PE 2025 dan Instrumen Lainnya:&nbsp;<a title="Kuesioner PE 2025 dan Instrumen Lainnya" href="https://drive.bps.go.id/s/3ri9ZRwGyisA9H5">https://drive.bps.go.id/s/3ri9ZRwGyisA9H5</a></li>\n</ul>\n<p>&nbsp;</p>', '<table style="border-collapse: collapse; width: 100%; height: 291.063px;" border="1"><colgroup><col style="width: 33.3333%;"><col style="width: 33.3333%;"><col style="width: 33.3333%;"></colgroup>\n<tbody>\n<tr style="height: 22.3906px;">\n<td style="text-align: center; height: 22.3906px;"><strong>Kegiatan</strong></td>\n<td style="text-align: center; height: 22.3906px;"><strong>Tanggal Mulai</strong></td>\n<td style="text-align: center; height: 22.3906px;"><strong>Tanggal Akhir</strong></td>\n</tr>\n<tr style="height: 67.1719px;">\n<td style="height: 67.1719px; line-height: 1;"><span style="font-size: 12pt;">Pengutipan Direktori Perusahaan Pertambangan dan Energi&nbsp;</span></td>\n<td style="height: 67.1719px; line-height: 1;"><span style="font-size: 12pt;">1 Januari 2025</span></td>\n<td style="height: 67.1719px; line-height: 1;"><span style="font-size: 12pt;">31 Januari 2025</span></td>\n</tr>\n<tr style="height: 67.1719px;">\n<td style="height: 67.1719px; line-height: 1;"><span style="font-size: 12pt;">Updating Perusahaan Pertambangan dan Energi (UDPE)&nbsp;</span></td>\n<td style="height: 67.1719px; line-height: 1;"><span style="font-size: 12pt;">1 Maret 2025</span><br><br></td>\n<td style="height: 67.1719px; line-height: 1;"><span style="font-size: 12pt;">31 Maret 2025</span></td>\n</tr>\n<tr style="height: 111.938px;">\n<td style="height: 111.938px; line-height: 1;"><span style="font-size: 12pt;">Pencacahan Usaha/Perusahaan,&nbsp;</span><br><span style="font-size: 12pt;">Pemeriksaan, Editing, Coding dan Data Entri&nbsp;</span><br><span style="font-size: 12pt;">dengan aplikasi FASIH&nbsp;</span></td>\n<td style="height: 111.938px; line-height: 1;"><span style="font-size: 12pt;">1 Mei 2025</span><br><br></td>\n<td style="height: 111.938px; line-height: 1;"><span style="font-size: 12pt;">31 Juli 2025</span></td>\n</tr>\n<tr style="height: 22.3906px;">\n<td style="height: 22.3906px; line-height: 1;"><span style="font-size: 12pt;">Pengawasan Lapangan&nbsp;</span></td>\n<td style="height: 22.3906px; line-height: 1;"><span style="font-size: 12pt;">1 Mei 2025</span></td>\n<td style="height: 22.3906px; line-height: 1;"><span style="font-size: 12pt;">31 Juli 2025</span></td>\n</tr>\n</tbody>\n</table>', '2025-02-05 15:35:40', '198804162008011001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('xeQvcBnsmqu', '2024s101', 'Pengembangan Kompetensi Pengelolaan Pengadaan Barang dan Jasa', '2024', '2024s101', '<p>Rediansyah Arief, SP, M.Si</p>\n<p>Chairina, S.M.</p>\n<p>Nasliyah Husna, S.P</p>\n<p>Dhien Auliatu Asra, S.E.</p>', '<p>Pengembangan Kompetensi Pengelolaan Pengadaan Barang dan Jasa</p>', '<p>Tanggal 1 Januari sampai dengan 31 Desember 2024</p>', '2024-02-26 14:26:10', '198902272012122001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('XLaZOmYB94D', '2024s101', 'Monitoring Kinerja Triwulanan', '2025', '2025s101', '<p>PJK : Reza Rezki Pulungan</p>\n<p>Anggota : 1. Kanasha Humaira</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2. Thariana Ayu Islami</p>', '<p>Monitoring Kinerja dilaksanakan berkala secara triwulanan</p>', 'NULL', '2025-07-28 8:42:46', '198504232008011001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('XPngblpGIvh', '2024s102', 'Web IndirA', '2025', '2025s105', '<p><strong>Project Leader</strong> : Fitral</p>\n<p><strong>Developer</strong> : Fitral, Amirudin, Adrian</p>', '<p>-</p>', 'NULL', '2025-05-26 14:54:25', '199906212022011001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('y4rqweoV4be', '2024s106', 'Survey Khusus Neraca Produksi (SKNP)', '2025', '2025s106', '<p>PJK:</p>\n<p>Maulizasari, S.Stat</p>', '<p><strong><span class="deskripsi-label">Penjelasan Umum</span></strong></p>\n<p>Badan Pusat Statistik (BPS) saat ini mengimplementasikan System National Account (SNA) 2008, dimana salah satu rekomendasinya adalah penyusunan Tabel Penyediaan dan Penggunaan (TPP). BPS mulai mengimplementasikan secara bertahap konsep, definisi dan metodologi yang terdapat pada SNA 2008 ke dalam TPP Indonesia. Sehingga untuk keperluan tersebut, selain data yang diperoleh dari internal BPS, maupun dari luar BPS, masih diperlukan data pelengkap lainnya. Data pelengkap ini diperoleh melalui survei khusus yaitu Survei Khusus Neraca Produksi (SKNP). Selain itu data pendapatan dan pengeluaran yang diperoleh dari pelaksanaan Survei Khusus Neraca Produksi (SKNP) dapat digunakan oleh BPS provinsi untuk mendapatkan rasio konsumsi antara yang bermanfaat bagi penghitungan Produk Domestik Regional Bruto (PDRB) menurut lapangan usaha.</p>\n<p>&nbsp;</p>\n<p><strong><span class="deskripsi-label">Tujuan dan Manfaat Kegiatan</span></strong></p>\n<p>Memperoleh informasi terbaru mengenai struktur input dan rasio konsumsi antara dari seluruh sektor ekonomi</p>\n<p>&nbsp;</p>\n<p><strong><span class="deskripsi-label">Frekuensi Kegiatan</span></strong></p>\n<p>Tahunan</p>', 'NULL', '2025-07-24 11:29:03', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('yaigKUhD0HY', '2024s106', 'Penyusunan Publikasi PDRB Menurut Lapangan Usaha 2020-2024', '2025', '2025s106', '<p>PJK :</p>\n<p>Ridha Mutia, SE, M.Si</p>\n<p>Anggota:</p>\n<ol>\n<li>Maulizasari, S.Stat</li>\n<li>Fitri Mulyani, SST</li>\n</ol>', '<p>Penghitungan PDRB yang digunakan dalam publikasi ini ialah melalui&nbsp;pendekatan produksi yaitu menghitung nilai tambah barang dan jasa yang<br>dihasilkan seluruh unit produksi di wilayah Provinsi Aceh setiap triwulan. PDRB&nbsp;pendekatan produksi atau menurut lapangan usaha diperoleh dari selisih nilai<br>barang dan jasa yang dihasilkan dikurangi bahan baku yang digunakan sebagai&nbsp;input ditambah pajak atas produk dikurangi subsidi atas produk. Unit-unit<br>produksi tersebut dikelompokkan menjadi 17 kategori lapangan usaha, yaitu:<br>A. Pertanian, kehutanan, dan&nbsp;perikanan;<br>B. Pertambangan dan penggalian;<br>C. Industri pengolahan;<br>D. Pengadaan listrik dan gas;<br>E. Pengadaan Air;<br>F. Konstruksi;<br>G. Perdagangan besar dan eceran&nbsp;dan reparasi mobil dan sepeda&nbsp;motor;<br>H. Transportasi dan pergudangan;<br>I. Penyediaan akomodasi &amp; makan minum;<br>J. Informasi &amp; komunikasi;<br>K. Jasa keuangan;<br>L. Real estate;<br>M,N Jasa perusahaan;<br>O Administrasi pemerintahan,&nbsp;pertahanan, &amp; jaminan sosial&nbsp;wajib;<br>P Jasa pendidikan;<br>Q Jasa kesehatan &amp; kegiatan&nbsp;sosial;<br>R,S,T,U Jasa lainnya</p>', 'NULL', '2025-07-24 10:29:26', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('Yc5Y9WArDOM', '2024s105', 'Pengolahan Survei Penyempurnaan Diagram Timbang Indeks Harga Perdagangan Besar (SPDT-IHPB)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Melly</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Cut Malahayati&nbsp; &nbsp;</p>', '<p>Link Dashboard: <a href="https://webapps.bps.go.id/olah/spdtihpb2023/login#/">https://webapps.bps.go.id/olah/spdtihpb2023/login#/</a></p>', '<table style="border-collapse: collapse; width: 100%; height: 111.953px;" border="1"><colgroup><col style="width: 49.9665%;"><col style="width: 49.9665%;"></colgroup>\n<tbody>\n<tr style="height: 22.3906px;">\n<td style="height: 22.3906px;">Menghitung nilai penjualan komoditas</td>\n<td style="height: 22.3906px;">&nbsp;Januari - Maret 2024</td>\n</tr>\n<tr style="height: 22.3906px;">\n<td style="height: 22.3906px;">Menentukan paket komoditas sementara</td>\n<td style="height: 22.3906px;">&nbsp;Januari - Maret 2024</td>\n</tr>\n<tr style="height: 22.3906px;">\n<td style="height: 22.3906px;">Finalisasi paket komoditas IHPB (2023 = 100)</td>\n<td style="height: 22.3906px;">&nbsp;April - Juni 2024</td>\n</tr>\n<tr style="height: 22.3906px;">\n<td style="height: 22.3906px;">Pertemuan dengan PJ SPDT IHPB Provinsi</td>\n<td style="height: 22.3906px;">&nbsp;Juni 2024</td>\n</tr>\n<tr style="height: 22.3906px;">\n<td style="height: 22.3906px;">Evaluasi IHPB (2023 = 100)</td>\n<td style="height: 22.3906px;">&nbsp;Juli - Desember 2024</td>\n</tr>\n</tbody>\n</table>', '2024-01-29 15:30:57', '198411122006042002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('YHTDCEBKm0X', '2024s106', 'Penyusunan Publikasi PDRB Menurut Lapangan Usaha Triwulan 2', '2025', '2025s106', '<p>PJK :</p>\n<p>Ridha Mutia, SE, M.Si</p>\n<p>Anggota:</p>\n<ol>\n<li>Maulizasari, S.Stat</li>\n<li>Fitri Mulyani, SST</li>\n</ol>', '<p>Penghitungan PDRB yang digunakan dalam publikasi ini ialah melalui&nbsp;pendekatan produksi yaitu menghitung nilai tambah barang dan jasa yang<br>dihasilkan seluruh unit produksi di wilayah Provinsi Aceh setiap triwulan. PDRB&nbsp;pendekatan produksi atau menurut lapangan usaha diperoleh dari selisih nilai<br>barang dan jasa yang dihasilkan dikurangi bahan baku yang digunakan sebagai&nbsp;input ditambah pajak atas produk dikurangi subsidi atas produk. Unit-unit<br>produksi tersebut dikelompokkan menjadi 17 kategori lapangan usaha, yaitu:<br>A. Pertanian, kehutanan, dan&nbsp;perikanan;<br>B. Pertambangan dan penggalian;<br>C. Industri pengolahan;<br>D. Pengadaan listrik dan gas;<br>E. Pengadaan Air;<br>F. Konstruksi;<br>G. Perdagangan besar dan eceran&nbsp;dan reparasi mobil dan sepeda&nbsp;motor;<br>H. Transportasi dan pergudangan;<br>I. Penyediaan akomodasi &amp; makan minum;<br>J. Informasi &amp; komunikasi;<br>K. Jasa keuangan;<br>L. Real estate;<br>M,N Jasa perusahaan;<br>O Administrasi pemerintahan,&nbsp;pertahanan, &amp; jaminan sosial&nbsp;wajib;<br>P Jasa pendidikan;<br>Q Jasa kesehatan &amp; kegiatan&nbsp;sosial;<br>R,S,T,U Jasa lainnya</p>', 'NULL', '2025-07-24 11:51:56', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('Yj3pV9cNI7R', '2024s101', 'Pengelolaan Internalisasi Inovasi dan Digitalisasi Layanan Terintegrasi baik internal maupun eksternal secara berkualitas', '2024', '2024s108', '<p>Kahar Muzakkar</p>', '<p>Terselenggaranya Pengelolaan Digitalisasi Layanan dan Inovasi Peningkatan Hubungan dengan Pengguna Data secara berkualitas dan berkelanjutan</p>', '<p>2024</p>', '2024-02-23 9:14:16', '199607132019012002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('ylbz1CzHH5p', '2024s104', 'Survei Konstruksi Tahunan', '2025', '2025s104', '<ol>\n<li>Cut Malahayati</li>\n<li>Fikri</li>\n</ol>', '<ul>\n<li>Survei &nbsp;Perusahaan &nbsp;Konstruksi &nbsp;Tahunan &nbsp;(SKTH) &nbsp;2024 &nbsp;bertujuan &nbsp;untuk memperoleh data perusahaan konstruksi yang memuat struktur dan ciri-ciri sektor konstruksi &nbsp;di &nbsp;Indonesia &nbsp;melalui &nbsp;data &nbsp;jumlah &nbsp;perusahaan &nbsp;konstruksi, &nbsp;banyaknya tenaga &nbsp;kerja, &nbsp;nilai &nbsp;balas &nbsp;jasa &nbsp;dan &nbsp;upah, &nbsp;pemakaian &nbsp;bahan &nbsp;bakar, &nbsp;pendapatan &nbsp;dan pengeluaran pekerjaan konstruksi, bahan/material yang digunakan, nilai konstruksi&nbsp;<br>yang diselesaikan, dan lain-lain dalam periode tahun 2024.</li>\n<li>&nbsp;Moda pendataan kegiatan &nbsp;Survei Perusahaan Konstruksi Tahunan (SKTH-2025) menggunakan Computer-Assisted Personal Interviews&nbsp;<br>(CAPI).</li>\n<li>Monitoring Dashboard:&nbsp;<a title="Monitoring Dashboard" href="https://fasih-dashboard.bps.go.id/">https://fasih-dashboard.bps.go.id</a>&nbsp;</li>\n<li>Buku Pedoman Survei Konstruksi Tahunan 2025: <a title="Buku Pedoman Survei Konstruksi Triwulanan 2025" href="https://drive.bps.go.id/apps/onlyoffice/s/42TYC3MqsMdFXy9?fileId=71470149">https://drive.bps.go.id/apps/onlyoffice/s/42TYC3MqsMdFXy9?fileId=71470149</a></li>\n<li>Daftar Sampel:&nbsp;<a title="Daftar Sampel" href="https://docs.google.com/spreadsheets/d/1GjhmnFoWqrLPgEbxoQASrSrWwKNY_qhoE7kBveKIWug/edit?gid=1339402030#gid=1339402030">https://docs.google.com/spreadsheets/d/1GjhmnFoWqrLPgEbxoQASrSrWwKNY_qhoE7kBveKIWug/edit?gid=1339402030#gid=1339402030</a></li>\n<li>Dokumen Survei Konstruksi Tahunan 2025: <a title="Dokumen Survei Konstruksi Tahunan 2025" href="https://drive.bps.go.id/s/42TYC3MqsMdFXy9">https://drive.bps.go.id/s/42TYC3MqsMdFXy9</a></li>\n</ul>', 'NULL', '2025-07-25 17:10:49', '198804162008011001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('YLiRbw4RNpg', '2024s102', 'Rekomendasi Kegiatan Statistik (ROMANTIK)', '2024', '2024s109', '<p style="line-height: 1.5;"><strong>Ketua Tim</strong>: Wahyu Agung Sutikno<br><strong>PJK</strong>: Fikri<br><strong>Anggota</strong>: M. Alimuddin, Nur Hasanah</p>', '<ul>\n<li style="line-height: 1.5;"><strong>Link ROMANTIK: </strong><a href="https://romantik.web.bps.go.id">https://romantik.web.bps.go.id</a></li>\n<li style="line-height: 1.5;"><strong>Link ESENSIAL: Edukasi Seputar Pembinaan Statistik Sektoral:</strong>&nbsp;<a href="https://s.id/pss-esensial">https://s.id/pss-esensial</a></li>\n<li style="line-height: 1.5;"><strong>Alur Kegiatan Rekomendasi Statistik :</strong> https://romantik.web.bps.go.id/panduan</li>\n</ul>', '<ul>\n<li>Pelaksanaan Rekomendasi Statistik (ROMANTIK)&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Sepanjang Tahun</li>\n</ul>', '2024-04-02 10:52:09', '198512052008011002', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('YRVHivRFMca', '2024s102', 'Monitoring dan Penanganan Kendala Jaringan pada perangkat pengguna', '2024', '2024s105', '<p><strong>Ketua : Fitral</strong></p>\n<p>Anggota:&nbsp;</p>\n<ul>\n<li>Munandar [PJK]</li>\n<li>Ichsan</li>\n<li>Iswahyudi</li>\n<li>Wira</li>\n<li>Hafidz</li>\n<li>Kahar&nbsp;</li>\n</ul>', '<p>Melakukan monitoring dengan perangkat pendukung (wireshark, monitoring dari router, cisco meraki)</p>', '<table style="border-collapse: collapse; width: 100%;" border="1"><colgroup><col style="width: 49.9665%;"><col style="width: 49.9665%;"></colgroup>\n<tbody>\n<tr>\n<td style="text-align: center;"><strong>Kegiatan</strong></td>\n<td style="text-align: center;"><strong>Waktu</strong></td>\n</tr>\n<tr>\n<td>Monitoring dan perawatan Jaringan</td>\n<td>Januari - Desember&nbsp;</td>\n</tr>\n<tr>\n<td>Penanganan Kendala pada perangkat pengguna dan Jaringan</td>\n<td>Januari- Desember</td>\n</tr>\n</tbody>\n</table>', '2024-02-21 15:57:01', '198012212010031001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('Z5hOHdYZKqH', '2024s101', 'Pemenuhan Dokumentasi RB/ZI, Mitigasi Risiko, SPIP', '2024', '2024s108', '<p>Ketua : <strong>Yan Yan Gustiana</strong></p>\n<p>Anggota :</p>\n<p>Maulizasari</p>\n<div class="hc-details hc-details-open-top">\n<div id="hover_340058828">Mazaya Alifah Syadzwina</div>\n<div>Rodiah</div>\n</div>\n<p>Wahdini</p>\n<p>Reza Rezki Pulungan</p>\n<p>Edo Mara Nasution</p>\n<p>Hendra Gunawan</p>\n<p>&nbsp;</p>', '<ol>\n<li>Kegiatan RB BPS Provinsi Aceh&nbsp;<a href="https://sites.google.com/view/zibpsaceh/rb-bps-provinsi?authuser=0">RB BPS Provinsi Aceh</a></li>\n<li>Bahan sosialisasi LKE ZI <a href="s.bps.go.id/WorkshopZI2024">s.bps.go.id/WorkshopZI2024</a></li>\n<li>Bahan paparan ZI series <a title="Bahan paparan ZI Aceh" href="https://s.id/ZI_ACEH">https://s.id/ZI_ACEH</a></li>\n<li>Penilaian mandiri ZI <a title="Penilaian mandiri ZI pintar" href="s.bps.go.id/zipintar">s.bps.go.id/zipintar</a></li>\n</ol>', '<p>Sosialisasi RB : Februari 2024</p>\n<p>Sosialisasi Mitigasi Risiko : September 2024</p>\n<p>Sosialisasi ZI series : Agustus sd. Oktober 2024</p>\n<p>&nbsp;</p>', '2024-02-22 12:52:48', '199509142019032002', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('Z6C57YDL4ns', '2024s104', 'Survei Perusahaan Migas', '2024', '2024s104', '<p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: 1.3;"><strong><span style="font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-fareast-language: EN-ID;">Cut Malahayati</span></strong></p>\n<p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: 1.3;"><span style="font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-fareast-language: EN-ID;">Fikri</span></p>\n<p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: 1.3;"><span style="font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-fareast-language: EN-ID;">Nova Misrina</span></p>\n<p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: 1.3;"><span style="font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-fareast-language: EN-ID;">Ridha Mutia</span></p>', '<p class="MsoNormal" style="margin-bottom: .0001pt;">Periode Survei Perusahaan Migas adalah&nbsp;<strong><span style="font-family: \'Calibri\',sans-serif; mso-ascii-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: \'Times New Roman\'; mso-bidi-theme-font: minor-bidi;">Tahunan</span></strong> dengan<em><strong><span style="font-family: \'Calibri\',sans-serif; mso-ascii-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: \'Times New Roman\'; mso-bidi-theme-font: minor-bidi;"> Output</span></strong></em><strong><span style="font-family: \'Calibri\',sans-serif; mso-ascii-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: \'Times New Roman\'; mso-bidi-theme-font: minor-bidi;">&nbsp;</span></strong>Data Produksi, Nilai, Jumlah Tenaga Kerja, Balas Jasa.</p>', '<p><em>on progress</em></p>', '2024-02-21 9:38:50', '198607292009022005', '0', NULL, NULL, N