	('z6KUrr5r7hY', '2024s102', 'Web So Asik', '2024', '2024s105', '<p>Developer:</p>\n<ul>\n<li>Ichsan Hasanudin</li>\n</ul>', '<p>link : soasik.web.bps.go.id</p>', '<p>Sepanjang tahun</p>', '2024-03-19 2:30:31', '199501232018021001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('zjsek5DeUnG', '2024s102', 'Menyediakan Router Cadangan', '2024', '2024s105', '<p><strong>Ketua : Fitral</strong></p>\n<p>Anggota:&nbsp;</p>\n<ul>\n<li>Munandar [PJK]</li>\n<li>Wira</li>\n<li>Hafidz</li>\n<li>Kahar&nbsp;</li>\n</ul>', '<p>Kegiatan ini bertujuan untuk menyediakan router cadangan yang akan menggantikan router utama secara cepat kalau terjadi sesuatu pada router utama. Ada dua router yang disiapkan, yaitu Router sebagai gateway jalur internet dan router untuk kegiatan UKOM untuk ruangan Rilis. Kegiatan ini meliputi Install, konfigurasi atau melakukan restore konfigurasi dari router utama.</p>', '<table style="border-collapse: collapse; width: 100.02%;" border="1"><colgroup><col style="width: 49.9621%;"><col style="width: 49.9621%;"></colgroup>\n<tbody>\n<tr>\n<td>Install dan konfigurasi</td>\n<td>Juli 2024 untuk router internet dan Agustus 2024 untuk router ruang Rilis</td>\n</tr>\n<tr>\n<td>Maintenance</td>\n<td>Agustus - Desember 2024</td>\n</tr>\n</tbody>\n</table>', '2024-08-20 15:37:15', '198012212010031001', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('ZjxMHZs6nzA', '2024s105', 'Penyusunan Publikasi Statistik Harga Pedesaan (SHPed)', '2024', '2024s103', '<p>PJK&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Mursalina</p>\n<p>Anggota&nbsp; &nbsp; : Dwi Susanti</p>', '<table dir="ltr" border="1" cellspacing="0" cellpadding="0" data-sheets-root="1"><colgroup><col width="509"><col width="127"><col width="100"></colgroup>\n<tbody>\n<tr>\n<td style="text-align: center;" data-sheets-value="{"><strong>Judul Publikasi (Indonesia)</strong></td>\n<td style="text-align: center;" data-sheets-value="{"><strong>Penyusun</strong></td>\n<td style="text-align: center;" data-sheets-value="{"><strong>Pemeriksaan</strong></td>\n</tr>\n<tr>\n<td data-sheets-value="{">Nilai Tukar Petani Provinsi Aceh 2023</td>\n<td style="text-align: center;" data-sheets-value="{">Mursalina</td>\n<td style="text-align: center;" data-sheets-value="{">Haniah</td>\n</tr>\n</tbody>\n</table>\n<p style="text-align: center;">&nbsp;</p>', '<table dir="ltr" style="width: 62.2902%;" border="1" cellspacing="0" cellpadding="0" data-sheets-root="1"><colgroup><col style="width: 64.818%;" width="509"><col style="width: 23.2236%;"><col style="width: 12.1317%;" width="100"></colgroup>\n<tbody>\n<tr>\n<td style="text-align: center;" data-sheets-value="{"><strong>Judul Publikasi (Indonesia)</strong></td>\n<td style="text-align: center;"><strong>ARC/NonARC</strong></td>\n<td style="text-align: center;" data-sheets-value="{"><strong>Tanggal Rilis di Web</strong></td>\n</tr>\n<tr>\n<td data-sheets-value="{">Nilai Tukar Petani Provinsi Aceh 2023</td>\n<td style="text-align: center;">ARC</td>\n<td style="text-align: center;" data-sheets-value="{">15 Maret 2024</td>\n</tr>\n</tbody>\n</table>', '2024-03-13 3:02:22', '197902252002122004', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	('ZujgnOy76iU', '2024s106', 'Penyusunan Angka PDRB Triwulan 1', '2025', '2025s106', '<p>PJK :</p>\n<p>Meita Jumiartanti, SST, M.Si</p>\n<p>Anggota:</p>\n<ol>\n<li>Hendra Dharmawan, SST, M.Si</li>\n<li>Ridha Mutia, SE, M.Si</li>\n<li>Hilda Aprina, SST, M.Si</li>\n<li>Cahya Danu Rahman, SST</li>\n<li>Maulizasari, S.Stat</li>\n<li>Fitri Mulyani, SST</li>\n<li>Mazaya Alifah Syadzwina, S.Tr.Stat</li>\n<li>Azwar, SE</li>\n</ol>', '<div class="daftar">\n<p><strong><span class="deskripsi-label">Tujuan dan Manfaat Kegiatan</span></strong></p>\n<p>Menyediakan data dan indikator ekonomi makro sebagai evaluasi dan perencanaan pembangunan</p>\n<p>&nbsp;</p>\n<p><strong><span class="deskripsi-label">Frekuensi Penyelenggaraan</span></strong></p>\n<p>Triwulanan</p>\n</div>', 'NULL', '2025-07-24 12:00:16', '198910212010122006', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
